/* Evolvlings: path conversations of era 5, El Invierno Largo (the ten eras plan, https://claude.ai/artifact/RFy6uGdhz9DJeW7e9ZfdkE).
   Same format as the zone files (see rpg/events-aurora.js). These events only come up while the Glade lives in era 5:
   need.era says so (lore.js needOk), and need.layer counts the guardians beaten since the era began.
   Another generation has passed since Las Forjas Hondas. How era 4 ended (m4_campana / m4_ascuas / m4_forja) is
   still in the flags and changes a few lines and options.
   The winter doesn't end. The White Deep keeps root ice, which never melts, and has become the Glade's granary;
   a girl of the House of Ice (Lirio) and a boy of the House of the Mushroom (Moho) want to marry, and the old law of
   the second statue forbids it.
   The nine peoples you bring together set the u5_* flags; with all nine, the final dilemma offers the Wedding
   (rpg/data-eras.js derives e5_nueve). The m5_* flags are the marks this era leaves on the next.
   Loaded after the zone files (it adds to them). English text: rpg/events-era5.en.js. */
window.EVEVENTS = window.EVEVENTS || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Entrega 1: el granero, Lirio y Moho, las raciones y la Tumba Helada ==================== */

  /* ---------- Fondo Blanco: el granero, los dos enamorados, la regente, el hielo de raíz y la voz del rey ---------- */
  add("deep", {
    "e5-granero": { kind: "encuentro", need: { era: 5, layer: 1 }, first: true, who: { centeno: "Centeno, intendente del granero" }, start: "a", nodes: {
      a: { say: [[null, "En la entrada del Fondo Blanco hay una fila que baja por la ladera y se pierde en la nieve. Gente del Prado, del Bosque, de los Altos. Algunos llevan días esperando. Tienen la cara quemada por el frío."],
                 [null, "Adentro, en una sala de hielo azul, hay sacos apilados hasta el techo. El hielo de las paredes no gotea: es hielo de raíz, que no se derrite nunca. La comida que se guarda aquí no se pudre."],
                 ["centeno", "Soy Centeno. Soy del Bosque, pero la regente me puso a repartir porque sé contar y no soy de aquí. Así nadie dice que el Fondo reparte para el Fondo."],
                 ["centeno", "Un saco por familia por semana. Si alcanza. Este mes no alcanza."]],
           opts: [{ t: "«¿Cuánta comida queda?»", go: "cuanta", once: true },
                  { t: "«Cuando la Campana sonó, ¿alguien supo que iba a pasar esto?»", go: "campana", cNeed: "m4_campana" },
                  { t: "«Sin hornos, el Claro no tenía cómo calentarse.»", go: "ascuas", cNeed: "m4_ascuas" },
                  { t: "«Con una forja por pueblo, el frío subió por todos lados.»", go: "forja", cNeed: "m4_forja" },
                  { t: "Ayudarlo a repartir", go: "ayudar" },
                  { t: "Ponerte en la fila, como todo el mundo", go: "fila" }] },
      cuanta: { say: [["centeno", "Para dos inviernos, si nadie más llega. Llegan cien familias por semana."],
                      ["centeno", "Y el hielo de raíz no es infinito. Cada vez que se corta un bloque para una sala nueva, el Fondo se enfría un poco más. Los viejos dicen que se enfría el Claro entero."]], back: "a" },
      campana: { say: [["centeno", "Nadie. Sonó, se durmió la Raíz y todos festejaron. Al otro día nevó. Era temprano para la nieve. Nadie le dio importancia."],
                       ["centeno", "Mi abuela dice que la nieve de esa noche todavía está debajo de la que cayó ayer. Nunca se fue."]], back: "a" },
      ascuas: { say: [["centeno", "No había. Las manos ya no se ponían de piedra, eso sí. Pero cuando vino el frío, la gente quemó las sillas, después las puertas, después las vigas."],
                      ["centeno", "Ahora queman los árboles del Bosque. Mi Bosque. Por eso estoy aquí: para que mi familia coma sin tener que cortar."]], back: "a" },
      forja: { say: [["centeno", "Despacio. Una forja chica no calienta un pueblo. La Raíz se enfrió por todas partes a la vez, y el frío subió como sube el agua en un pozo."],
                     ["centeno", "Nadie tuvo la culpa sola. Eso es lo peor: no hay a quién gritarle."]], back: "a" },
      ayudar: { say: [[null, "Pasas el día pasando sacos de mano en mano. Centeno anota cada uno en una tablilla de madera. Tiene las uñas negras de tinta."],
                      [null, "Al final del día, la fila no se achicó. Llegó más gente de la que se fue."],
                      ["centeno", "Así todos los días. No se termina. Pero hoy comieron cuarenta familias más que ayer, porque éramos dos."]], end: { xp: 14, flag: ["e5_granero", "u5_escarcha"] } },
      fila: { say: [[null, "Te pones al final de la fila. Delante tienes a una mujer del Prado con dos chicos dormidos en una manta."],
                    [null, "Tardas medio día en llegar. Cuando llegas, Centeno te reconoce y te mira raro."],
                    ["centeno", "¿Usted, en la fila? Bueno. Ahora sabe cuánto se tarda. Casi nadie de los que deciden lo sabe."]], end: { xp: 12, flag: "e5_filaHecha" } },
    } },

    "e5-lirio": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { lirio: "Lirio, de la Casa del Hielo" }, start: "a", nodes: {
      a: { say: [[null, "En un pasillo de hielo del Fondo, una muchacha con el pelo trenzado de blanco y un abrigo de la Casa del Hielo cuenta frascos de conservas en un estante. Lo hace rápido, en voz alta, sin equivocarse."],
                 [null, "Cuando una guardia pasa, se endereza y saluda. Cuando la guardia dobla la esquina, se apoya en el estante y respira hondo."],
                 ["lirio", "Me llamo Lirio. Usted es quien cuida en el Vado. Mi madre dice que es la única persona del Claro que no le debe nada al Fondo. ¿Es verdad?"]],
           opts: [{ t: "«¿Por qué lo pregunta?»", go: "porque", once: true },
                  { t: "«Parece cansada de hacer las cosas bien.»", go: "bien" },
                  { t: "«¿Hay alguien que usted quiera ver y no puede?»", go: "alguien" }] },
      porque: { say: [["lirio", "Porque necesito a alguien que no le deba nada al Fondo. Para que nadie pueda decirle que no."],
                      ["lirio", "Pero no aquí. Aquí las paredes son de hielo y el hielo lo oye todo. Eso dicen los viejos. Yo creo que lo que oye todo es la guardia."]], back: "a" },
      bien: { say: [["lirio", "Cansada. Sí. En la Casa del Hielo se hace todo bien. Se cuenta bien, se saluda bien, se casa una bien."],
                    [null, "Se le quiebra la voz en la última palabra. Se la arregla con una tos."],
                    ["lirio", "Perdón. Hace frío. Siempre hace frío."]], end: { xp: 10, flag: "e5_lirioCansada" } },
      alguien: { say: [[null, "Lirio te mira mucho rato. Después mira la esquina por donde se fue la guardia."],
                       ["lirio", "Hay un chico. De la Casa de la Seta. Se llama Moho. Se ríe de todo, hasta de la ley. Yo no me río de nada."],
                       ["lirio", "Hay una ley vieja, la de la segunda estatua, que dice que el Hielo y la Seta no se casan. Nadie sabe por qué. Pero todos la cumplen. Yo la cumplo. Mientras alguien me mira."]], end: { xp: 14, flag: "e5_lirioCuenta" } },
    } },

    "e5-moho": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { moho: "Moho, de la Casa de la Seta" }, start: "a", nodes: {
      a: { say: [[null, "En los invernaderos de la Casa de la Seta, debajo del Fondo, hace calor húmedo. Las setas crecen en estantes de madera, blancas, enormes. Un muchacho flaco las riega cantando una canción obscena sobre la regente."],
                 ["moho", "¡Visita! Pase, pase. Aquí abajo es el único lugar del Fondo donde se puede sudar. Me llamo Moho. Riego, canto, y me burlo de la ley. Las tres cosas las hago mal."],
                 ["moho", "Dicen que usted conoció a mi bisabuela, o a la abuela de mi bisabuela. En la Casa de la Seta se vive mucho y se cuenta raro. Esporina, se llama. Todavía vive. Es más vieja que el Fondo."]],
           opts: [{ t: "«¿De qué se ríe tanto?»", go: "rie", once: true },
                  { t: "«Lirio me habló de usted.»", go: "lirio", cNeed: "e5_lirioCuenta" },
                  { t: "«¿Le da miedo la ley?»", go: "miedo" }] },
      rie: { say: [["moho", "De todo lo que me da miedo. Si me río, no se nota. La regente me da miedo, así que tengo diez canciones sobre ella."],
                   ["moho", "La ley me da miedo, así que tengo veinte. El invierno me da miedo, así que me río de la nieve. Me cansé un poco, la verdad."]], back: "a" },
      lirio: { say: [[null, "Moho deja de regar. Por primera vez no sonríe."],
                     ["moho", "¿Le habló? ¿Ella? ¿De mí?"],
                     ["moho", "Entonces es verdad. Pensé que me lo había soñado. Las setas te hacen soñar cosas. Pero esto no lo soñé."],
                     [null, "Vuelve a regar, despacio. Las manos le tiemblan un poco. No canta."]], end: { xp: 14, flag: "e5_mohoSabe" } },
      miedo: { say: [["moho", "¿Miedo? No. Bueno. Sí."],
                     [null, "Se sienta en un cajón dado vuelta. Se saca el gorro de seta."],
                     ["moho", "Mi bisabuela quiso a alguien del Hielo, hace mucho. Obedeció la ley. Nunca se lo perdonó. Yo no quiero obedecer. Pero tampoco quiero que a Lirio la echen de su Casa por mi culpa."]], end: { xp: 12, flag: "e5_mohoMiedo" } },
    } },

    "e5-esporina": { kind: "dialogo", need: { era: 5, layer: 2 }, who: { esporina: "Esporina" }, start: "a", nodes: {
      a: { say: [[null, "En el invernadero más hondo de la Casa de la Seta, sentada entre setas tan altas como árboles, hay una mujer tan vieja que su piel parece corteza. Tiene un sombrero de seta lleno de notas por dentro."],
                 ["esporina", "Cuidador. Soy Esporina. A usted los años no le tocan. A mí sí. Usted me vio envejecer. Estamos a mano."],
                 ["esporina", "Mi nieto Moho, el que se ríe, quiere a la chica del Hielo. Ya lo sé. Lo sé porque yo hice lo mismo. Y no quiero que haga lo que hice después."]],
           opts: [{ t: "«¿Qué hizo después?»", go: "despues", once: true },
                  { t: "«¿Por qué existe esa ley?»", go: "ley" },
                  { t: "«Dígaselo a Moho. Ahora, no tarde.»", go: "decir" },
                  { t: "«Ese es un asunto de ellos, no suyo.»", go: "suyo" }] },
      despues: { say: [["esporina", "Obedecí. Él era del Hielo. Se llamaba Nevado. Cuidaba el Turno. Nos veíamos en la sala de los soñadores, porque ahí todos duermen y nadie mira."],
                       ["esporina", "Cuando se supo, me pidieron que eligiera: la Casa o él. Elegí la Casa. Él siguió cuidando el Turno hasta que se murió. Yo seguí regando setas. Ciento veinte años regando setas."]], back: "a" },
      ley: { say: [["esporina", "Nadie sabe. Yo tampoco. Está escrita en la base de la segunda estatua del Corazón, la de las dos figuras con las manos juntas."],
                   ["esporina", "Lo raro es que la estatua muestra al Hielo y a la Seta juntos. Y la ley dice que no se junten. Alguien leyó la estatua al revés. O alguien la leyó bien y tuvo miedo."]], back: "a" },
      decir: { say: [["esporina", "Ahora. Sí. Yo siempre digo las cosas tarde. Cuando la verdad ya no sirve para nada."],
                     [null, "Se levanta con un bastón de raíz. Tarda mucho en subir las escaleras del invernadero. No acepta tu brazo."],
                     [null, "Esa noche, Moho y Esporina hablan hasta la mañana. Cuando Moho sale, tiene los ojos rojos y no se ríe de nada en todo el día."],
                     ["esporina", "Le dije todo. Lo que hice, lo que perdí, lo que me duele todavía. No sé si lo ayudé o si le di miedo. Las dos cosas, seguro."]], end: { xp: 18, flag: "e5_esporinaDice" } },
      suyo: { say: [["esporina", "Es de ellos. Tiene razón. Y la ley es de todos. Por eso pesa."],
                    [null, "Vuelve a mirar sus setas. Ya no te habla. Al rato, sin darse vuelta, dice algo más."],
                    ["esporina", "Si los ve juntos, no le diga a nadie. Eso sí es asunto suyo."]], end: { xp: 10, flag: "e5_esporinaCalla" } },
    } },

    "e5-raciones": { kind: "dialogo", need: { era: 5, layer: 2 }, who: { cellisca: "Regente Cellisca", centeno: "Centeno, intendente del granero" }, start: "a", nodes: {
      a: { say: [[null, "En la sala del trono del Fondo, una mujer alta con una corona de hielo trabajado lee una tablilla de Centeno. Es la regente Cellisca, nieta de la nieta de Albina. Tiene las manos cruzadas sobre el pecho, como si tuviera frío por dentro."],
                 ["cellisca", "El granero no alcanza para todos este invierno. Alguien tiene que comer menos. El Consejo quiere que yo decida quiénes. Yo quiero que lo decida alguien de afuera, para que nadie pueda decir que el Fondo eligió."],
                 ["centeno", "Hay tres maneras, regente. Las tres son malas."],
                 ["cellisca", "Elija usted, Cuidador. Usted no le debe nada a nadie. Si se equivoca, la culpa es suya. Si acierta, la regencia le dio su apoyo."]],
           opts: [{ t: "«¿Por qué no decide usted?»", go: "porque", once: true },
                  { t: "Repartir por igual entre todos", go: "igual" },
                  { t: "Primero los que trabajan: los que cortan leña y cargan sacos", go: "trabajo" },
                  { t: "Primero los niños", go: "ninos" }] },
      porque: { say: [["cellisca", "Porque cuando la gente tiene hambre, odia al que reparte. Y la regencia no puede permitirse que la odien. Somos lo único que mantiene el granero cerrado."],
                      ["cellisca", "Si lo abren todos a la vez, se termina en una semana. El hambre es un argumento, Cuidador. Yo lo uso. No me pida que me guste."]], back: "a" },
      igual: { say: [["centeno", "Por igual. Un poco para todos. Nadie se muere esta semana. Todos tienen hambre."],
                     [null, "Así se hace. Las filas se alargan, pero se mueven. A la tercera semana, los que cortan leña no tienen fuerza para cortar. Hay menos leña. Hace más frío."],
                     ["cellisca", "Lo justo no calienta. Pero nadie puede decir que no fue justo."]], end: { xp: 16, flag: "m5_racionesIgual" } },
      trabajo: { say: [["centeno", "Primero los que trabajan. Los leñadores, los cargadores, los que cortan hielo. Si ellos comen, hay leña y hay comida para el mes que viene."],
                       [null, "Así se hace. La leña llega. Las salas se calientan. Pero en el Prado, donde no hay trabajo, las familias reciben medio saco. Algunos viejos dejan de bajar a la fila."],
                       ["cellisca", "Funciona. Los que comen trabajan, y los que trabajan comen. Los otros se acuerdan. El Prado se va a acordar mucho tiempo."]], end: { xp: 14, flag: "m5_racionesTrabajo" } },
      ninos: { say: [["centeno", "Primero los niños. Todos los niños de todos los pueblos comen entero. Los grandes, lo que sobre."],
                     [null, "Así se hace. Los chicos dejan de llorar en las filas. Los padres comen la mitad, y algunos menos, para que el saco dure."],
                     [null, "A la cuarta semana, dos leñadores se desmayan en el Bosque. Uno no se levanta."],
                     ["cellisca", "Los chicos van a vivir. Algunos sin padre. Así es el invierno: no deja elegir sin cobrar."]], end: { xp: 16, flag: "m5_racionesNinos" } },
    } },

    "e5-amantes": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { lirio: "Lirio, de la Casa del Hielo", moho: "Moho, de la Casa de la Seta", cellisca: "Regente Cellisca" }, start: "a", nodes: {
      a: { say: [[null, "En la sala del Turno, entre los soñadores que duermen bajo mantas enceradas, dos personas están sentadas en el suelo, despiertas, con las manos juntas. Lirio y Moho."],
                 ["lirio", "Aquí todos duermen y nadie mira. Mi tatarabuela venía aquí, dicen. Con alguien de la Seta."],
                 ["moho", "La mía también. Con alguien del Hielo. A lo mejor eran los mismos. A lo mejor la sala está acostumbrada."],
                 ["lirio", "La guardia nos vio ayer. No dijo nada todavía. Pero lo va a decir. Usted tiene que ayudarnos. Por favor."]],
           opts: [{ t: "«¿Qué quieren hacer?»", go: "querer", once: true },
                  { t: "Ayudarlos a huir por los túneles de la Seta", go: "huir" },
                  { t: "Contárselo a la regente antes que la guardia", go: "contar" },
                  { t: "«Pidan la boda en público, delante de todos.»", go: "publico" }] },
      querer: { say: [["moho", "Casarnos. Sin pedir permiso. Yo lo haría mañana, en la puerta del granero, con la fila de testigo."],
                      ["lirio", "Yo quiero que mi Casa lo acepte. No quiero escaparme. Quiero entrar por la puerta con él y que mi madre lo salude."],
                      ["moho", "Eso no va a pasar."],
                      ["lirio", "Ya sé. Lo quiero igual."]], back: "a" },
      huir: { say: [[null, "Moho conoce los túneles de la Seta mejor que nadie. Esa noche los guías hasta la salida del sur, donde los túneles dan a la nieve."],
                    [null, "Lirio se para en la salida. Mira hacia atrás, hacia el Fondo. Después mira a Moho."],
                    ["lirio", "Si me voy, nunca más voy a ser de mi Casa. Mi madre va a decir que me morí."],
                    ["moho", "Entonces vámonos juntos a ser de ninguna. Es más barato."],
                    [null, "Se van hacia el Vado, en la nieve, a pie. Al día siguiente, la Casa del Hielo cuelga una tela negra en la puerta."]], end: { xp: 18, flag: "m5_huida" } },
      contar: { say: [[null, "Vas a la sala del trono. Cellisca escucha sin moverse. Al final, asiente."],
                      ["cellisca", "Gracias. Si me lo hubiera dicho la guardia, tendría que haberlo castigado en público. Usted me lo dijo en privado. Puedo ser más suave."],
                      [null, "Al día siguiente, Lirio es mandada a la frontera norte del Fondo, a cuidar los bloques de hielo de raíz. Moho, a los invernaderos más hondos. No se pueden ver."],
                      ["cellisca", "Más suave. No dije bueno. Dije más suave."]], end: { xp: 10, flag: "m5_delatados" } },
      publico: { say: [["lirio", "¿En público? ¿Delante de todos?"],
                       ["moho", "¡Eso! ¡En la puerta del granero! ¡Con la fila de testigo!"],
                       [null, "Al día siguiente, Lirio y Moho se paran en la puerta del granero, de la mano, delante de la fila entera. Lirio habla. No le tiembla la voz."],
                       ["lirio", "Me quiero casar con Moho, de la Casa de la Seta. Lo pido en voz alta para que todos lo oigan. Si la ley dice que no, que la ley lo diga delante de ustedes."],
                       [null, "La fila se queda en silencio. Alguien aplaude. Después otro. La guardia llega corriendo. No sabe a quién llevarse primero."]], end: { xp: 20, flag: "m5_bodaPedida" } },
    } },

    "e5-hieloraiz": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { centeno: "Centeno, intendente del granero", cellisca: "Regente Cellisca" }, start: "a", nodes: {
      a: { say: [[null, "En la frontera del Fondo, donde empieza el hielo más viejo, un grupo de cortadores espera con sierras de hueso. Delante tienen una pared azul tan oscura que parece negra. Hielo de raíz."],
                 ["centeno", "Si cortamos esta pared, hay sala para el doble de comida. Nadie pasa hambre este invierno."],
                 ["cellisca", "Y el Fondo se enfría el doble. Los viejos dicen que cada bloque de hielo de raíz que se corta es frío que la Raíz no puede guardar más. Que el frío se suelta y sube."],
                 ["centeno", "Los viejos dicen muchas cosas. La fila de afuera no dice nada. Tiene hambre."]],
           opts: [{ t: "«¿Es verdad lo que dicen los viejos?»", go: "verdad", once: true },
                  { t: "Cortar. Que nadie pase hambre hoy.", go: "cortar" },
                  { t: "No cortar. El frío ya es demasiado.", go: "nocortar" }] },
      verdad: { say: [["cellisca", "Nadie sabe. Pero desde que se corta, el invierno está más duro. Puede ser casualidad. Puede ser que no."],
                      ["centeno", "Desde que se corta, también come más gente. Eso no es casualidad."]], back: "a" },
      cortar: { say: [[null, "Las sierras de hueso muerden el hielo. Sale un vapor blanco, frío, que quema la piel. Los cortadores trabajan con los ojos cerrados."],
                      [null, "En una semana hay una sala nueva, enorme. Se llena de sacos. La fila de afuera se mueve más rápido."],
                      [null, "Esa semana, el Lago se congela tres palmos más hondo. En los Altos, dos pueblos quedan tapados del todo."],
                      ["centeno", "Comen. Hoy comen. Lo de mañana, mañana."]], end: { xp: 16, coins: 15, flag: "m5_cortarHielo" } },
      nocortar: { say: [[null, "Los cortadores guardan las sierras. La pared azul queda entera."],
                        ["centeno", "Bueno. Entonces la fila espera más. Y algunos de la fila no van a llegar a la puerta."],
                        ["cellisca", "Y el invierno no empeora. Por lo menos no por nosotros. No es mucho consuelo para el que se muere esperando."],
                        [null, "Centeno se va sin despedirse. Esa noche, alguien deja una bolsa de grano en la puerta de su casa en el Bosque. Nadie sabe de dónde salió."]], end: { xp: 14, flag: "m5_noCortar" } },
    } },

    "e5-desvelo": { kind: "dialogo", need: { era: 5, layer: 2 }, who: { desvelo: "Desvelo, voz de Los Que Oyen" }, start: "a", nodes: {
      a: { say: [[null, "Frente a la Tumba Helada, un hombre de túnica gris con los ojos muy abiertos habla a una multitud de gente del Día. Habla despacio, con voz cálida. Lo escuchan como si les diera de comer."],
                 ["desvelo", "El Rey Dormido nos habla. El invierno es su mensaje. Nos dice que nos juntemos, que obedezcamos a la regencia, que esperemos. Que el que espera, come."],
                 [null, "La gente asiente. Una mujer llora. Un chico pregunta cuándo termina el invierno, y Desvelo le acaricia la cabeza."],
                 ["desvelo", "Cuando el Rey despierte, pequeño. Cuando hayamos sido buenos."]],
           opts: [{ t: "«¿Usted oyó al Rey de verdad?»", go: "oyo", once: true },
                  { t: "«En la Tumba no hay ningún rey. Hay una raíz.»", go: "raiz" },
                  { t: "«Dígales lo que sabe, no lo que quieren oír.»", go: "decir" },
                  { t: "Escuchar hasta el final", go: "escuchar" }] },
      oyo: { say: [["desvelo", "Oigo lo que oye la gente cuando tiene miedo. Que hay un sentido. Que alguien manda. Que no es en vano."],
                   ["desvelo", "Si eso es el Rey o soy yo, no lo sé. Ya no lo sé. Llevo veinte años diciéndolo."]], back: "a" },
      raiz: { say: [[null, "Desvelo te mira. Por un momento, la voz cálida se le va."],
                    ["desvelo", "Lo sé. Mi maestro abrió la puerta una vez, de chico, a escondidas. Vio la punta de la raíz y los arañazos de adentro."],
                    ["desvelo", "Pero si digo eso, ¿qué les queda? ¿Una raíz que no oye y un invierno que no se termina? Prefiero darles un rey. Un rey se puede esperar."]], back: "a" },
      decir: { say: [["desvelo", "¿Lo que sé? ¿A ellos? ¿Ahora, con hambre?"],
                     [null, "Mira a la multitud. Al chico de la pregunta. A la mujer que llora."],
                     ["desvelo", "Mañana. Mañana les digo. Hoy no puedo."],
                     [null, "Al día siguiente vuelve a hablar del Rey. Pero al final agrega una frase nueva, bajito: «Y si el Rey no despierta, igual vamos a tener que hacer algo nosotros»."]], end: { xp: 14, flag: "e5_desveloDuda" } },
      escuchar: { say: [[null, "Te quedas hasta el final. Desvelo habla una hora. Dice que el frío purifica, que la regencia es justa, que las filas son una prueba."],
                        [null, "Cuando termina, la gente se va más tranquila. Ninguno tiene más comida que antes. Pero caminan derechos."],
                        ["desvelo", "Ya ve. No les di nada. Y se van mejor que como vinieron. ¿Eso está mal?"]], end: { xp: 10, flag: "e5_desveloEscuchado" } },
    } },
  });

  /* ---------- Prado Aurora: los faroles congelados y la fila que baja ---------- */
  add("aurora", {
    "e5-faroles": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { pavesa: "Pavesa, farolera" }, start: "a", nodes: {
      a: { say: [[null, "Las calles del Prado están vacías y blancas. Los faroles tienen la llama adentro, quieta, congelada como una flor en el hielo. Alumbran, pero no calientan."],
                 [null, "Una farolera vieja sube una escalera y golpea un farol con un martillo chico. El vidrio no se rompe. La llama no se mueve."],
                 ["pavesa", "Soy Pavesa. Mi abuelo era Cerillo, el del Barrio, el de los casilleros de tiza. Prendo faroles que no se apagan y no calientan. Es el trabajo más inútil del Claro."]],
           opts: [{ t: "«¿Por qué se congelaron así?»", go: "porque", once: true },
                  { t: "Ayudarla a romper un farol para sacar la llama", go: "romper" },
                  { t: "«Junte a la gente bajo los faroles. Aunque sea luz.»", go: "juntar" }] },
      porque: { say: [["pavesa", "Nadie sabe. Una noche hizo tanto frío que la llama se quedó quieta. Desde entonces está así. Ni se apaga ni calienta."],
                      ["pavesa", "Mi abuelo decía que faltaban noches en el tablero. Ahora sobran: todas son la misma noche."]], back: "a" },
      romper: { say: [[null, "Golpeas el farol con el martillo hasta que el vidrio se raja. La llama congelada cae en tu mano. Pesa como una piedra y está fría."],
                      [null, "La pones en un cuenco con aceite. No prende nada. Pero brilla. Los chicos de la calle vienen a mirarla."]], end: { xp: 10, flag: "e5_llamaFria" } },
      juntar: { say: [[null, "Pavesa va de casa en casa golpeando puertas. Al anochecer, cuarenta personas se juntan bajo el farol más grande de la plaza, apretadas, con mantas."],
                      [null, "No hace menos frío. Pero entre cuarenta cuerpos, se siente menos. Alguien canta. Otro trae sopa aguada."],
                      ["pavesa", "La luz no calienta. La gente sí. Si los pueblos se juntan en el Corazón, el Prado va a ir así: apretado, con mantas, cantando."]], end: { xp: 18, flag: ["e5_plazaJunta", "u5_luz"] } },
    } },

    "e5-cola": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { pavesa: "Pavesa, farolera" }, start: "a", nodes: {
      a: { say: [[null, "Por el camino del Prado al Fondo baja una fila de trineos tirados por gente. Llevan viejos, chicos, cosas para cambiar. Van al granero. Tardan cuatro días."],
                 [null, "En la mitad del camino, un trineo se rompió. Una familia del Barrio está parada al costado, en la nieve, sin saber qué hacer. Los otros trineos pasan sin parar."],
                 ["pavesa", "Si se paran a ayudar, pierden el lugar en la fila. Nadie se para. Así de simple."]],
           opts: [{ t: "Arreglar el trineo", go: "arreglar" },
                  { t: "Llevar a la familia en tu propio trineo", go: "llevar" },
                  { t: "Pedirles a los que pasan que se turnen para cargarlos", go: "turnar" }] },
      arreglar: { say: [[null, "Atas el patín roto con cuerda y una rama. Tarda una hora. La fila sigue pasando."],
                        [null, "Cuando terminas, la familia está al final de la fila. Van a llegar un día después que los demás."],
                        ["pavesa", "Un día. En el granero, un día puede ser medio saco menos. Pero llegan."]], end: { xp: 12 } },
      llevar: { say: [[null, "Subes a los viejos y a los chicos en tu trineo y tiras tú. La familia camina al lado. Llegan al Fondo cuatro días después, todos."],
                      [null, "En la puerta del granero, la madre de la familia te da un pedazo de tiza. Es lo único que tiene."],
                      ["pavesa", "Tiza. Del Barrio. Para dibujar casilleros. Mi abuelo estaría contento."]], end: { xp: 16, flag: "e5_familiaLlevada" } },
      turnar: { say: [[null, "Paras la fila. Hablas fuerte. Al principio nadie quiere. Después un hombre de los Altos se baja de su trineo y dice que él carga primero."],
                      [null, "Se turnan. Cada trineo carga a la familia un tramo. La fila va más lenta, pero va junta."],
                      ["pavesa", "Más lento, juntos. El Barrio se va a acordar de quién se bajó primero. Cuando llamen del Corazón, va a ir en fila, turnándose."]], end: { xp: 18, flag: ["e5_filaTurnos", "u5_barrio"] } },
    } },
  });

  /* ---------- Cráter Tibio: las colas para dormir junto al calor ---------- */
  add("crater", {
    "e5-calor": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { chispa: "Chispa, forjadora" }, start: "a", nodes: {
      a: { say: [[null, "En el Cráter hay una cola que da la vuelta a la montaña. Gente de todos los pueblos espera con un tronco o una tabla bajo el brazo: el precio de una noche junto al fuego."],
                 [null, "Adentro, alrededor de lo que queda de los hornos, duermen cientos de personas en el suelo, en filas. Una forjadora de pelo gris camina entre ellas con un balde de brasas, repartiendo calor."],
                 ["chispa", "¡Cuidador! Soy Chispa, la de la ladera sur. La del primer clavo. Ahora tengo nietos. Y el Cráter es el único lugar tibio del Claro. Nunca pensé que iba a extrañar el humo."]],
           opts: [{ t: "«¿Por qué se cobra la entrada?»", go: "cobra", once: true },
                  { t: "«¿Cómo está su mano?»", go: "mano" },
                  { t: "«Que entren los que no tienen leña. Que paguen los que sí.»", go: "gratis" },
                  { t: "Ayudarla a repartir brasas", go: "brasas" }] },
      cobra: { say: [["chispa", "Porque sin leña no hay fuego. Y sin fuego no hay Cráter. La leña la traen ellos. Es lo justo, dicen los maestros."],
                     ["chispa", "Lo que no dicen es que los que no tienen leña duermen afuera. Y afuera no se duerme: se espera la mañana."]], back: "a" },
      mano: { say: [[null, "Chispa levanta las manos y las mira un rato, como si fueran de otra persona."],
                    ["chispa", "Son las que me dejó el Fuego. Ya no me quejo de ellas. Mis nietos tienen las manos enteras. Eso es lo que cuento."]], back: "a" },
      gratis: { say: [["chispa", "¿Gratis para los que no tienen? Los maestros me van a echar."],
                      [null, "Mira la cola. Hay una vieja sin tronco, con un chico de la mano, al final."],
                      ["chispa", "Que me echen. El Fuego aprendió a dar calor sin cobrar alguna vez. En la Noche de Ascuas, dicen. Que lo aprenda otra vez."],
                      [null, "Esa noche Chispa deja entrar a cuarenta personas sin leña. Los maestros gritan. Ella les pone un balde de brasas en las manos y les dice que repartan."]], end: { xp: 20, flag: ["e5_calorGratis", "u5_fuego"] } },
      brasas: { say: [[null, "Caminas entre las filas de gente dormida con un balde de brasas. Pones un puñado al lado de cada familia. Las brasas se apagan rápido. Vuelves a llenar el balde."],
                      [null, "Al amanecer tienes los brazos negros hasta el codo. Chispa te da una taza de algo caliente."],
                      ["chispa", "Toda la noche. Como yo, como mis hijos. Ahora sabe lo que es ser del Fuego en invierno."]], end: { xp: 12, heal: 0.05 } },
    } },
  });

  /* ---------- Bosque Hondo: los robles huecos y lo que se guarda para los suyos ---------- */
  add("forest", {
    "e5-robles": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { abeto: "Abeto, del Concejo" }, start: "a", nodes: {
      a: { say: [[null, "En el Bosque Hondo, los robles más viejos tienen puertas. El Concejo los ahuecó por dentro con cuidado, sin matarlos, para que las familias duerman adentro. Sale humo por los nudos de la corteza."],
                 ["abeto", "Soy Abeto, del Concejo. Ahuecamos los robles que ya estaban huecos, o casi. Así viven el árbol y la familia. Los dos con frío, pero vivos."],
                 ["abeto", "El problema es que hay más familias que robles. Y los de afuera quieren cortar los robles para leña. Un roble da leña para un mes. O techo para diez años."]],
           opts: [{ t: "«¿Quién decide quién duerme en los robles?»", go: "quien", once: true },
                  { t: "«Abran los robles a las familias de afuera también.»", go: "abrir" },
                  { t: "«Den un roble para leña. Uno solo.»", go: "uno" },
                  { t: "Ayudar a ahuecar otro roble", go: "ahuecar" }] },
      quien: { say: [["abeto", "El Concejo. Primero los del Bosque. Después, si sobra, los de afuera."],
                     ["abeto", "No sobra. Nunca sobra. El Concejo aprendió a decir que no hace cien años, y todavía no aprendió otra cosa."]], back: "a" },
      abrir: { say: [["abeto", "¿A los de afuera? ¿Gente del Prado durmiendo en nuestros robles?"],
                     [null, "Le recuerdas el claro de los tocones, la Madre del Bosque, los tres por uno. Que el Bosque sobrevivió porque alguien de afuera cuidó."],
                     ["abeto", "Bueno. Una familia de afuera por cada roble, junto con la de adentro. Van a estar apretados. Van a pelearse. Pero el Bosque va a ir al Corazón con las puertas abiertas."]], end: { xp: 20, flag: ["e5_roblesAbiertos", "u5_planta"] } },
      uno: { say: [[null, "El Concejo vota. Se corta un roble, el más enfermo. Da leña para un mes a cien familias."],
                   ["abeto", "Un roble. Y el mes que viene van a pedir otro. Siempre es uno. Hasta que no queda ninguno."]], end: { xp: 10, coins: 10, flag: "e5_robleCortado" } },
      ahuecar: { say: [[null, "Trabajas con Abeto dos días, con gubias y paciencia, sacando la madera muerta del corazón de un roble. Tiene que quedar la corteza viva y un dedo de madera sana."],
                       [null, "Cuando terminas, una familia del Bosque entra con sus cosas. El roble cruje, pero aguanta."],
                       ["abeto", "Diez años de techo. Si el invierno no dura más. Si dura, el roble también se va a cansar."]], end: { xp: 14, flag: "e5_robleHueco" } },
    } },

    "e5-reparto": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { centeno: "Centeno, intendente del granero" }, start: "a", nodes: {
      a: { say: [[null, "En una casa del Bosque, junto a un roble hueco, Centeno descarga un trineo de noche. Saca tres sacos del granero y los mete en un hueco debajo del piso."],
                 [null, "Cuando te ve, se queda quieto con un saco en los brazos."],
                 ["centeno", "Son para mi madre. Y para mis sobrinos. Tres sacos. De dos mil. Nadie los va a extrañar."]],
           opts: [{ t: "«¿Cuántas veces lo hizo?»", go: "veces", once: true },
                  { t: "«Devuélvalos al granero.»", go: "devolver" },
                  { t: "«Repártalos entre las familias de los robles.»", go: "repartir" },
                  { t: "No decir nada", go: "callar" }] },
      veces: { say: [["centeno", "Cada semana. Tres sacos. A veces cuatro."],
                     ["centeno", "No soy un ladrón. Soy el que reparte. ¿Usted no guardaría un poco para los suyos, si tuviera la llave?"]], back: "a" },
      devolver: { say: [[null, "Centeno mira el hueco del piso. Mira la casa, donde duermen su madre y tres chicos."],
                        ["centeno", "Los devuelvo. Mañana. Y me voy a la fila con ellos, como todos."],
                        [null, "Lo hace. Al mes, su madre está más flaca. Centeno reparte en el granero con los ojos hundidos y no se guarda ni un puñado."]], end: { xp: 16, flag: "e5_centenoDevuelve" } },
      repartir: { say: [["centeno", "¿Entre todas las familias de los robles? Son tres sacos. No alcanza para nada."],
                        [null, "Pero lo hace. Tres sacos entre cuarenta familias. Un puñado para cada una."],
                        ["centeno", "Un puñado. Bueno. Ahora soy un ladrón que reparte. Es raro, pero duermo mejor."]], end: { xp: 14, flag: "e5_centenoReparte" } },
      callar: { say: [[null, "No dices nada. Centeno termina de guardar los sacos y tapa el hueco con una alfombra."],
                      ["centeno", "Gracias. No se lo voy a olvidar. Y no me lo va a dejar olvidar, ¿no? Eso también lo sé."]], end: { xp: 8, flag: "e5_centenoGuarda" } },
    } },
  });

  /* ---------- Hondonada Umbría: las mantas de sombra ---------- */
  add("hollow", {
    "e5-mantas": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { tizna: "Tizna, tejedora de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "En la Hondonada, en un taller con telares negros, una tejedora de la Corte teje con hilos que no se ven bien: se mueven, como sombras de ramas. Las mantas que salen del telar son tibias al tacto."],
                 ["tizna", "Soy Tizna. Tejo mantas de sombra. Guardan el calor del cuerpo y no lo dejan salir. La Corte las vende caras. Y las alquila más caras todavía, por noche."],
                 ["tizna", "Lo malo es que si duermes mucho con una, la sombra de la manta se te pega. Te levantas con la sombra más oscura. Y más pesada."]],
           opts: [{ t: "«¿Cuánta gente duerme con estas mantas?»", go: "cuanta", once: true },
                  { t: "«Regálelas a los que duermen afuera del Cráter.»", go: "regalar" },
                  { t: "«Avise a todos lo de la sombra que se pega.»", go: "avisar" },
                  { t: "Probar una manta", go: "probar" }] },
      cuanta: { say: [["tizna", "Medio Prado. Los que pueden pagar. Los que no, se congelan o bajan al Fondo."],
                      ["tizna", "La Corte gana más este invierno que en cien años. Mi Reina está feliz. Yo tejo y no pienso. Es lo que me piden."]], back: "a" },
      regalar: { say: [["tizna", "¿Regalarlas? La Corte me cuelga del telar."],
                       [null, "Mira las mantas apiladas. Cien. Doscientas."],
                       ["tizna", "Veinte. Veinte se pueden perder en un traslado. Los traslados son peligrosos en invierno, ¿no?"],
                       [null, "Esa noche, veinte mantas de sombra aparecen en la cola del Cráter, sin nota. Veinte familias duermen tibias."]], end: { xp: 16, flag: "e5_mantasRegaladas" } },
      avisar: { say: [["tizna", "¿Contar lo de la sombra? ¿Que la manta abriga y cobra?"],
                      [null, "Se queda con un hilo entre los dedos. El hilo se le enrosca solo en la muñeca."],
                      ["tizna", "Bueno. Si la Corte va a ir al Corazón, que vaya diciendo lo que cobra. Por una vez, que la Hondonada venda algo con la etiqueta puesta."],
                      [null, "Al día siguiente, cada manta de sombra que sale del taller lleva un papel cosido: «Abriga. Pesa. No duermas con ella más de tres noches seguidas»."]], end: { xp: 20, flag: ["e5_mantasEtiqueta", "u5_sombra"] } },
      probar: { say: [[null, "Te envuelves en una manta de sombra. El calor es inmediato, total, como un abrazo que no termina. Te dan ganas de dormir para siempre."],
                      [null, "Te la sacas con esfuerzo. Tu sombra, en la pared, tarda un segundo en moverse cuando te mueves."],
                      ["tizna", "¿Ve? Una noche y ya. Imagínese un invierno."]], end: { xp: 10, hurt: 0.05, flag: "e5_sombraLenta" } },
    } },
  });

  /* ---------- Lago Espejo: el hielo que se cruza a pie ---------- */
  add("lake", {
    "e5-bajohielo": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { rada: "Doña Rada" }, start: "a", nodes: {
      a: { say: [[null, "El Lago Espejo está congelado de orilla a orilla. La gente lo cruza a pie, en fila, para ir del Prado al Fondo más rápido. El hielo es transparente como vidrio."],
                 [null, "Debajo se ven cosas. Una barca hundida. Una calle de piedra. Una forja redonda con una brasa roja todavía encendida. Caras. No: estatuas. O no."],
                 ["rada", "Soy Rada. Ya vieja. Leía paredes con los dedos. Ahora el lago me muestra todo lo que tapó, y no lo puedo tocar. Es como tener un libro abierto detrás de un vidrio."]],
           opts: [{ t: "«¿Qué es lo que más le asusta ver?»", go: "asusta", once: true },
                  { t: "Abrir un agujero en el hielo para tocar algo", go: "agujero" },
                  { t: "«Guíe a la gente por donde el hielo es más grueso.»", go: "guiar" }] },
      asusta: { say: [["rada", "Las caras. Hay gente debajo del hielo. Se congelaron cruzando, este invierno y el anterior. Algunos todavía tienen los ojos abiertos."],
                      ["rada", "Y las Mareas cruzamos por encima, todos los días, para ir a pedir comida. Pisando a los que no llegaron."]], back: "a" },
      agujero: { say: [[null, "Picas el hielo con una barreta hasta que sale agua negra, helada. Rada mete la mano hasta el codo."],
                       [null, "Saca una tablilla de piedra con letras. La toca con los ojos cerrados. Se le pone la mano azul."],
                       ["rada", "Dice: «El frío guarda. El que guarda, cobra». Nada más. La escribió alguien del Fondo, hace mucho. Lo sé por cómo hace las letras: rectas, como el hielo."]], end: { xp: 14, hurt: 0.05, flag: "e5_tablillaLago" } },
      guiar: { say: [[null, "Rada conoce el lago mejor que nadie. Camina delante de la fila, tanteando el hielo con un bastón, escuchando cómo suena. Donde suena hueco, cambia de camino."],
                     [null, "Pones banderas de trapo en el camino seguro. Al final del día, hay una línea de banderas de orilla a orilla."],
                     ["rada", "Ya está. Nadie más debajo del hielo por cruzar mal. Las Mareas guiamos. Es lo que hacíamos antes de que nos dieran casa. Si llaman del Corazón, vamos a ir así: adelante, tanteando."]], end: { xp: 20, flag: ["e5_banderasLago", "u5_agua"] } },
    } },
  });

  /* ---------- Cuevas del Eco: la Hondura cobra por entrar ---------- */
  add("caves", {
    "e5-entrada": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { pizca: "Pizca, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "En la boca de las Cuevas del Eco hay un portón de madera nuevo, con una ventanita. Del otro lado sale aire tibio. Afuera, gente con frío espera con monedas en la mano."],
                 [null, "Una mujer de la Hondura con el casco abollado cobra por la ventanita. Tiene las rodillas vendadas, como si las tuviera peladas desde chica."],
                 ["pizca", "¡Cuidador! Soy Pizca. La de los túneles chicos. Ahora soy la que cobra la entrada. Una moneda por noche. Adentro se duerme por turnos, en las galerías calientes."]],
           opts: [{ t: "«¿Por qué cobra la Hondura?»", go: "cobra", once: true },
                  { t: "«Usted sabe lo que es trabajar en un túnel sin que nadie la cuide.»", go: "tunel" },
                  { t: "«Abra el portón esta noche. Una sola noche.»", go: "abrir" },
                  { t: "Pagar la entrada de los que no tienen", go: "pagar", fx: { cost: 20 } }] },
      cobra: { say: [["pizca", "Porque la Hondura siempre fue la que cava y la que se queda abajo. Ahora todos quieren estar abajo, porque abajo hace calor. Por primera vez, abajo vale algo."],
                     ["pizca", "No me mire así. Mi abuela empujó baldes por la mitad del precio. Yo cobro una moneda. Es la primera vez que la Hondura cobra en vez de pagar."]], back: "a" },
      tunel: { say: [[null, "Pizca deja de contar monedas. Se mira las rodillas."],
                     ["pizca", "Lo sé. Lo sé mejor que nadie."],
                     ["pizca", "Bueno. Los chicos entran gratis. Todos los chicos, de todos los pueblos. Y los que vengan con un chico de la mano también. Si la Hondura va al Corazón, que vaya con la puerta abierta para los chicos."]], end: { xp: 20, flag: ["e5_chicosGratis", "u5_piedra"] } },
      abrir: { say: [["pizca", "¿Una noche? ¿Y si mañana nadie quiere pagar?"],
                     [null, "Pero abre el portón. Entra gente, mucha, demasiada. Adentro, las galerías se llenan. Hay gritos, empujones, un chico que se pierde y lo encuentran al amanecer."],
                     ["pizca", "Una noche. Ya está. Mañana vuelvo a cobrar. Pero esta noche durmió todo el mundo tibio. Mal, apretado, pero tibio."]], end: { xp: 12, flag: "e5_portonAbierto" } },
      pagar: { say: [[null, "Le das a Pizca un puñado de monedas. Ella las cuenta dos veces, como hacen en la Hondura."],
                     ["pizca", "Veinte noches. Las reparto entre los que esperan sin moneda. Qué cosa rara, Cuidador. Paga lo que nadie le cobra."]], end: { xp: 14, flag: "e5_entradaPagada" } },
    } },
  });

  /* ---------- Los Altos: los pasos cerrados ---------- */
  add("heights", {
    "e5-pasos": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { romanza: "Romanza, mensajera" }, start: "a", nodes: {
      a: { say: [[null, "En los Altos, la nieve llega a los techos. Los pasos del norte desaparecieron bajo diez metros de blanco. Los pueblos de la cumbre están solos: no sube nadie, no baja nadie."],
                 [null, "En la plaza del pueblo más alto, una mujer de pelo gris toca un tambor chico. Cada golpe se oye lejísimos en el silencio de la nieve."],
                 ["romanza", "Soy Romanza. La última mensajera, ¿se acuerda? Toco para que los otros pueblos sepan que seguimos vivos. Ellos contestan con otro tambor. Si un día no contestan, sabemos."]],
           opts: [{ t: "«¿Cuántos pueblos contestan todavía?»", go: "cuantos", once: true },
                  { t: "Abrir un camino de bajada con palas", go: "camino" },
                  { t: "«Enséñeles a los otros pueblos un verso para pedir ayuda.»", go: "verso" }] },
      cuantos: { say: [["romanza", "Al principio del invierno, once. Ahora, siete. Los otros cuatro no contestan desde hace un mes."],
                       ["romanza", "Puede ser que se les rompió el tambor. Eso me digo todas las mañanas."]], back: "a" },
      camino: { say: [[null, "Cavas con los de la cumbre durante una semana. La nieve vuelve a caer de noche y tapa la mitad de lo cavado. Al final hay un pasillo angosto, de un cuerpo de ancho, hasta el valle."],
                      ["romanza", "Un pasillo. Para bajar de a uno. Bueno. Los viejos no lo van a poder usar. Pero los chicos sí."]], end: { xp: 14, flag: "e5_pasilloNieve" } },
      verso: { say: [["romanza", "¿Un verso para pedir ayuda? Los Altos nunca pidieron. Llevábamos los mensajes de los otros."],
                     [null, "Pero lo compone. Cuatro golpes largos, dos cortos: «Estamos vivos, nos falta». Lo toca. Del otro lado de la montaña, después de un rato, alguien lo repite."],
                     ["romanza", "Lo aprendieron. Ahora los Altos saben pedir. Es raro. Si llaman del Corazón, voy a ir tocando eso: estamos vivos, nos falta."]], end: { xp: 20, flag: ["e5_versoPedir", "u5_altos"] } },
    } },
  });

  /* ---------- Corazón del Claro: la segunda estatua, la Tumba Helada y el final ---------- */
  add("heart", {
    "e5-pareja": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { retama: "Retama, guarda del Tocón" }, start: "a", nodes: {
      a: { say: [[null, "En el Corazón, la nieve tapa todo menos la segunda estatua. Alrededor de ella, el suelo está limpio, como si la nieve no se animara a tocarla."],
                 [null, "Son dos figuras con las manos juntas. Una es de hielo, transparente, con la cara alzada. La otra es de una piedra blanda y porosa, como una seta enorme. Las dos tienen la boca abierta. Cantan."],
                 ["retama", "Soy Retama. Ya muy vieja. Cuido el Tocón desde hace cincuenta años. Esta estatua es la única que nunca cambió. Ni con la savia, ni con el lago, ni con el metal."]],
           opts: [{ t: "«¿Qué dice la base?»", go: "base", once: true },
                  { t: "Limpiar la escarcha de las manos juntas", go: "limpiar" },
                  { t: "Cantar la nana frente a la estatua", go: "cantar" }] },
      base: { say: [[null, "En la base hay letras talladas, rectas como las del Fondo. Retama las lee despacio."],
                    ["retama", "«Hielo y Seta cantaron juntos, y de su canto nació la primera luz. Que nunca más se separen las dos voces»."],
                    ["retama", "Y abajo, con otra letra, más nueva, rayada encima: «Que nunca más se junten». Alguien cambió la ley con un cuchillo. Y todos leen lo de abajo."]], back: "a" },
      limpiar: { say: [[null, "Con la manga limpias la escarcha de las manos juntas. Debajo, las dos manos de piedra están tibias. No como el Tocón, con fiebre: tibias como una mano de verdad."],
                       [null, "Tu criatura se sienta entre las dos figuras y cierra los ojos."]], end: { xp: 12, heal: 0.1, flag: "e5_manosTibias" } },
      cantar: { say: [[null, "Cantas la nana frente a la estatua. Tu voz suena sola en la plaza nevada. A mitad de la nana te das cuenta de que una nana para dos voces no suena bien con una."],
                      ["retama", "Le falta la otra voz. Siempre le faltó. Desde que alguien rayó la base."]], end: { xp: 14, flag: "e5_unaVoz" } },
    } },

    "e5-tumba": { kind: "dialogo", need: { era: 5, layer: 3 }, who: { desvelo: "Desvelo, voz de Los Que Oyen", cellisca: "Regente Cellisca" }, start: "a", nodes: {
      a: { say: [[null, "La Tumba Helada está en el Corazón del Fondo, pero esta noche todos los que importan están frente a ella. La regente Cellisca, con la corona. Desvelo, con la túnica gris. Guardias. Gente del Día que bajó a pedir y se quedó a mirar."],
                 [null, "La puerta tallada de la Tumba tiene una grieta nueva. Por la grieta sale un aire tibio, el único aire tibio del Fondo. Y un ruido, bajo, como alguien que se da vuelta en la cama."],
                 ["desvelo", "El Rey quiere salir. Es la señal. Hay que abrir y dejarlo hablar."],
                 ["cellisca", "O hay que sellarla para siempre. Si la gente ve lo que hay adentro, la regencia se termina. Y si se termina la regencia, se abre el granero, y se termina la comida."]],
           opts: [{ t: "«¿Qué hay adentro de verdad?»", go: "adentro", once: true },
                  { t: "Abrir la Tumba otra vez, delante de todos", go: "abrir" },
                  { t: "Sellarla, con Desvelo adentro de la cripta, como él pide", go: "sellar" },
                  { t: "Dejarla como está", go: "dejar" }] },
      adentro: { say: [["desvelo", "Una raíz. La punta de una raíz enorme, sobre una losa. Y la puerta arañada por dentro."],
                       ["cellisca", "Lo sabe. Siempre lo supo. Y le dice a la gente que es un rey."],
                       ["desvelo", "Y usted lo sabe y gobierna en nombre de ese rey. No me mire como si yo fuera el único que miente, regente."]], back: "a" },
      abrir: { say: [[null, "Empujas la puerta tallada. Se abre con un crujido de hielo viejo. Adentro, sobre una losa, la punta de una raíz enorme, gris, cubierta de escarcha. Late, muy despacio."],
                     [null, "La gente del Día se acerca. Miran. Nadie dice nada durante mucho rato."],
                     [null, "Después alguien pregunta: «¿Y el Rey?». Y otro contesta: «Nunca hubo». Y la pregunta corre por la fila, hacia afuera, hasta el Prado."],
                     ["cellisca", "Ya está. Ahora saben que mi corona es de hielo y nada más. Mañana van a querer abrir el granero también."]], end: { xp: 20, flag: "m5_tumbaAbierta" } },
      sellar: { say: [["desvelo", "Adentro. Sí. Si el Rey no habla, que hable alguien desde adentro. Yo. Para siempre. Es lo único que sé hacer: decir lo que necesitan oír."],
                      [null, "Desvelo entra en la Tumba con una lámpara y una manta. Cellisca lo mira entrar. Los guardias sellan la puerta con agua que se congela al instante."],
                      [null, "Desde adentro, al rato, se oye su voz. Cálida, lenta. Habla del Rey. Habla de esperar."],
                      ["cellisca", "Ya tenemos un Rey que habla. Los Que Oyen van a tener templo por esto. Dentro de muchas generaciones, alguien va a rezarle a esa puerta."]], end: { xp: 16, flag: "m5_desveloSellado" } },
      dejar: { say: [[null, "No haces nada. La grieta sigue abierta. El aire tibio sigue saliendo. Desvelo sigue hablando del Rey. Cellisca sigue gobernando en su nombre."],
                     ["desvelo", "Bueno. Así seguimos. Usted también eligió, Cuidador. Elegir no elegir también es elegir."]], end: { xp: 10, flag: "m5_tumbaDejada" } },
    } },

    "e5-final": { kind: "dialogo", need: { era: 5, eraWin: "heart" }, first: true, once: true, who: { cellisca: "Regente Cellisca", lirio: "Lirio, de la Casa del Hielo", moho: "Moho, de la Casa de la Seta" }, start: "a", nodes: {
      a: { say: [[null, "La Raíz Sorda cae sin un ruido. Sobre el Corazón sigue nevando. Frente a la segunda estatua, la de las dos voces, están la regente Cellisca, Lirio y Moho. Nadie sabe cómo llegaron los tres al mismo lugar."],
                 ["cellisca", "Los antiguos sellaban los puntos de la Raíz con tumbas. Así se paraba lo que la Raíz no podía parar sola. Una tumba nueva aquí, y el invierno termina. Lo dicen las tablillas del Fondo."],
                 ["moho", "Y la ley se queda como está. Y nosotros, cada uno en su Casa, para siempre."],
                 ["lirio", "Hay otra cosa. La estatua dice que el Hielo y la Seta cantaron juntos y nació una luz. Si cantamos aquí, con todos de testigo... no sé qué pasa. Nadie lo hizo en mil años."],
                 ["cellisca", "Y hay una tercera. Derretir todo el hielo de raíz. El granero entero. El frío guardado se suelta y vuelve a la Raíz, y la Raíz se despierta. Primavera. Y hambre: la comida se pudre en una semana."]],
           opts: [{ t: "«¿Qué pasa si sellamos una tumba nueva?»", go: "q1", once: true },
                  { t: "«¿Y si derretimos el hielo de raíz?»", go: "q2", once: true },
                  { t: "«¿Y si Lirio y Moho cantan juntos?»", go: "q3", once: true },
                  { t: "Sellar un punto nuevo de la Raíz con una tumba", go: "tumba" },
                  { t: "Derretir todo el hielo de raíz guardado", go: "deshielo" },
                  { t: "Que Lirio y Moho canten juntos, con los nueve de testigos", go: "boda", cNeed: "e5_nueve" }] },
      q1: { say: [["cellisca", "El invierno termina. El granero queda lleno, la regencia queda en pie, la ley queda escrita. Todo en orden."],
                  ["moho", "Todo en orden. Como en un congelador."]], back: "a" },
      q2: { say: [["cellisca", "La Raíz se despierta. El Claro respira. Y el Fondo pierde todo lo que tiene: el hielo, la comida, el poder. Esa primavera muere gente de hambre. Y el Fondo no va a perdonar."],
                  ["lirio", "Mi Casa vive de ese hielo. Mi madre, mis hermanas. No sé si podría mirarlas."]], back: "a" },
      q3: { say: [["lirio", "No sé. Nadie sabe. Si la estatua dice la verdad, nace algo. Una luz. Como la primera."],
                  ["moho", "Y si dice la verdad, también hay que pensar esto: la primera luz vio el pacto. Si nace otra, va a haber dos que lo vieron. Y no van a acordarse de lo mismo."],
                  ["cellisca", "Y eso solo vale si los nueve pueblos están. Sin testigos, es una boda prohibida y nada más."]], back: "a" },
      tumba: { say: [[null, "Los cortadores del Fondo traen bloques de hielo de raíz. Construyen una tumba chica sobre una grieta del Corazón, donde la Raíz asoma. Cellisca la sella con su propia mano."],
                     [null, "Esa noche deja de nevar. Por primera vez en veinte años, el cielo está despejado. Al amanecer, gotea un carámbano en el Prado."],
                     ["cellisca", "Terminó. El invierno terminó. Y la regencia lo terminó."],
                     [null, "Lirio y Moho están parados lejos uno del otro. No se miran. A la semana, Lirio se casa con un muchacho del Hielo. Moho deja de cantar."]], end: { xp: 60, flag: "m5_tumba" } },
      deshielo: { say: [[null, "Bajas al granero con Lirio, Moho y los cortadores que quieren ayudar. Abren las salas una por una. Rompen las paredes de hielo de raíz con sierras, con fuego, con lo que hay."],
                        [null, "El hielo de raíz se derrite por primera vez en mil años. Sale un viento frío que sube por todo el Claro y se mete en la tierra. Abajo, algo enorme respira."],
                        [null, "Al día siguiente, el sol calienta. La nieve se derrite en el Prado. Y en el granero, la comida empieza a oler mal."],
                        ["cellisca", "Primavera. Ya está. Ahora el Fondo no tiene nada. Y el Claro tiene hambre. Me van a odiar. A usted también."]], end: { xp: 60, flag: "m5_deshielo" } },
      boda: { say: [[null, "Llegan los nueve. El Prado, apretado, con mantas. El Fuego, con brasas. El Bosque, con las puertas de los robles. La Corte, con mantas con etiqueta. Las Mareas, con banderas de trapo. La Hondura, con los chicos. Los Altos, con el tambor. El Barrio, en fila. El Fondo, con Centeno contando."],
                    [null, "Lirio y Moho se paran frente a la segunda estatua, de la mano. Cantan la nana. Ella con la voz recta del Hielo. Él con la voz rota de la Seta. Las dos voces no suenan bien juntas. Después, sí."],
                    [null, "Entre las dos figuras de la estatua aparece una luz. Chica, temblorosa. Crece. Sube. Se queda en el aire, sobre el Corazón: una Estrella nueva."],
                    ["cellisca", "La ley se rompió delante de todos. No hay forma de volver a escribirla."],
                    [null, "Esa noche deja de nevar. Lirio y Moho miran la Estrella. Ella dice que la Estrella le guiñó. Él dice que no, que se rió. Ya no recuerdan lo mismo."]], end: { xp: 60, flag: "m5_boda" } },
    } },
  });

  /* ==================== Entrega 2: el Día en invierno (Prado, Cráter, Bosque) ==================== */

  /* ---------- Prado Aurora: casas vacías, medio saco, coplas y las llamas que se derriten ---------- */
  add("aurora", {
    "e5-velon": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { velon: "Velón, guarda del Farol" }, start: "a", nodes: {
      a: { say: [[null, "Anochece en el Prado. Un guarda del Farol con la capa blanca de escarcha sostiene del cuello del abrigo a un chico flaco. El chico abraza dos sillas rotas, como si fueran un perro."],
                 ["velon", "Soy Velón, guarda del Farol. Hay toque de frío: después del anochecer nadie anda por la calle. Este sacó sillas de una casa vacía. Para quemarlas."],
                 ["velon", "La familia de esa casa se fue a la fila del Fondo hace un mes. A lo mejor vuelven. A lo mejor no. Si vuelven y no tienen sillas, la culpa es mía."]],
           opts: [{ t: "«¿Por qué hay toque de frío?»", go: "toque", once: true },
                  { t: "Dejar que el chico se vaya con las sillas", go: "soltar" },
                  { t: "«Llévelo al puesto de guardia. Ahí tiene estufa.»", go: "estufa" },
                  { t: "Ayudar al chico a devolver las sillas", go: "devolver" }] },
      toque: { say: [["velon", "Porque de noche se roba. No por maldad: por frío. Primero se roban las sillas. Después las puertas. Después las casas enteras se caen porque alguien se llevó las vigas."],
                     ["velon", "Si el Prado se quema a sí mismo, cuando termine el invierno no va a haber Prado. Eso me dijeron. Lo repito. A veces lo creo."]], back: "a" },
      soltar: { say: [[null, "Velón te mira, después mira al chico. Le suelta el abrigo."],
                      ["velon", "Váyase. Rápido. Yo no vi nada."],
                      [null, "El chico corre por la nieve con las sillas a cuestas. A los dos pasos se le cae una. No vuelve a buscarla."],
                      ["velon", "Una silla da calor para una hora. Bueno. Que sea una buena hora."]], end: { xp: 10, flag: "e5_ninoSuelto" } },
      estufa: { say: [[null, "El puesto del Farol es una casilla con una estufa de hierro. Velón sienta al chico al lado del fuego. Quema una de las sillas, despacio, astilla por astilla."],
                      [null, "El chico se duerme sentado. Velón lo tapa con su capa."],
                      ["velon", "Mañana me van a preguntar por qué quemé una silla robada en la estufa del Farol. Voy a decir que hacía frío. Es verdad."]], end: { xp: 14, flag: "e5_velonEstufa" } },
      devolver: { say: [[null, "Llevas las sillas de vuelta con el chico. La casa vacía tiene una marca de tiza en la puerta, a la manera del Barrio: «Fuimos al Fondo. Volvemos»."],
                        [null, "El chico mira la marca mucho rato. Después saca un pedazo de tiza del bolsillo y escribe debajo, con letra torcida: «Les cuidé las sillas»."],
                        ["velon", "Eso no calienta a nadie. Pero si vuelven, van a saber que alguien pasó por aquí y no se llevó nada."]], end: { xp: 12, flag: "e5_sillasDevueltas" } },
    } },

    "e5-casasvacias": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { pavesa: "Pavesa, farolera" }, start: "a", nodes: {
      a: { say: [[null, "La calle de los Albor tenía las casas más lindas del Prado. Ahora la mitad están vacías. En cada puerta, una marca de tiza: «Fuimos al Fondo». Algunas tienen la fecha. Las más viejas son de hace dos inviernos."],
                 [null, "Al final de la calle, una familia del Barrio duerme en un portal, en la nieve, apretada contra una puerta cerrada."],
                 ["pavesa", "Pavesa otra vez, la de los faroles. Ese portal es de una casa vacía. Adentro hay camas. Afuera, ellos. Nadie se anima a abrir, porque las marcas dicen «volvemos»."]],
           opts: [{ t: "«¿Volvió alguien alguna vez?»", go: "volvio", once: true },
                  { t: "Abrir la casa para la familia del portal", go: "abrir" },
                  { t: "Tapiar las casas vacías para que nadie las saquee", go: "tapiar" },
                  { t: "«Que la familia entre, pero que deje una marca nueva en la puerta.»", go: "marca" }] },
      volvio: { say: [["pavesa", "Una familia. Volvieron sin el abuelo y sin la vaca. Encontraron la casa sin puertas. Se fueron otra vez."],
                      ["pavesa", "Las marcas de tiza son una promesa. Las promesas en invierno valen lo que dura la tiza."]], back: "a" },
      abrir: { say: [[null, "Fuerzas la puerta con el hombro. Adentro huele a encierro y a jabón viejo. Hay camas con mantas, una mesa, un reloj parado."],
                     [null, "La familia del portal entra sin hablar. La madre toca las mantas como si fueran a morderla."],
                     ["pavesa", "Ya está. Si vuelven los dueños, va a haber pelea. Pero va a haber alguien vivo para pelear."]], end: { xp: 14, flag: "e5_casaAbierta" } },
      tapiar: { say: [[null, "Clavas tablas en puertas y ventanas, casa por casa, con Pavesa sosteniendo los clavos. Al final de la calle, la familia del portal te mira trabajar."],
                      ["pavesa", "Las casas van a estar enteras cuando termine el invierno. Los que duermen afuera, no sé."],
                      [null, "A la mañana siguiente, el portal está vacío. Nadie sabe adónde fueron."]], end: { xp: 8, flag: "e5_casasTapiadas" } },
      marca: { say: [[null, "La familia entra. Antes, la madre escribe con tiza debajo de la marca vieja: «Entramos por frío. Cuidamos todo. Si vuelven, les dejamos la cama del medio»."],
                     ["pavesa", "Una marca debajo de otra marca. Así se hacía en el Barrio cuando faltaban casilleros. Mi abuelo estaría contento."],
                     [null, "En una semana, la mitad de las casas vacías de la calle tienen dos marcas. En la de la esquina, alguien agregó una tercera: «Gracias», con letra de chico."]], end: { xp: 18, flag: "e5_dosMarcas" } },
    } },

    "e5-mediosaco": { kind: "dialogo", need: { era: 5, layer: 2 }, who: { ortiga: "Ortiga, del Prado" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza del Prado, una mujer de hombros anchos reparte lo que trajo del Fondo entre cinco chicos sentados en un banco. Corta el pan con cuidado, con un hilo, para que las partes salgan iguales."],
                 ["ortiga", "Ortiga me llamo. Cinco hijos. Bajé cuatro días a la fila y me dieron esto. Ustedes, los que deciden, ¿alguna vez cortaron un pan en cinco con un hilo?"]],
           opts: [{ t: "«¿Por qué le dieron tan poco?»", go: "poco", once: true },
                  { t: "«Lo repartimos por igual. Para todos es poco.»", go: "igual", cNeed: "m5_racionesIgual" },
                  { t: "«Primero comen los que trabajan. Usted no tiene trabajo.»", go: "trabajo", cNeed: "m5_racionesTrabajo" },
                  { t: "«Primero los niños. Sus hijos comen entero.»", go: "ninos", cNeed: "m5_racionesNinos" },
                  { t: "Darle lo que tienes encima", go: "dar" },
                  { t: "«Junte a las madres del Prado. Vayan al Fondo a hablar.»", go: "marcha" }] },
      poco: { say: [["ortiga", "Porque el Prado no corta hielo ni carga sacos ni cava. El Prado siembra. Y en invierno no hay qué sembrar. Así que el Prado no vale nada."],
                    ["ortiga", "Mi abuela decía que el Prado alimentaba al Claro entero. Ahora el Claro nos da las sobras. Me lo voy a acordar. Mis hijos también."]], back: "a" },
      igual: { say: [["ortiga", "Poco para todos. Sí. Ya sé. La regente come poco también, dicen."],
                     ["ortiga", "No dicen que la regente tiene un solo hijo y yo cinco. Lo igual no es lo mismo para todos, Cuidador."]], back: "a" },
      trabajo: { say: [[null, "Ortiga deja el hilo. Te mira de una forma que no se olvida."],
                       ["ortiga", "Mi marido cortaba leña. Se murió en el Bosque el invierno pasado, cortando para el Cráter. Ahora no tengo trabajo. ¿Eso cuenta?"],
                       ["ortiga", "No me conteste. Ya sé lo que cuenta."]], back: "a" },
      ninos: { say: [["ortiga", "Sí. Mis hijos comen entero. Por eso lo que traigo es para ellos y yo no como desde ayer."],
                     ["ortiga", "No me quejo. Bueno, sí me quejo. Pero lo volvería a elegir. Eso es lo que más rabia me da."]], back: "a" },
      dar: { say: [[null, "Le das el pan y la carne seca que llevabas para el camino. Ortiga lo mira sin tocarlo."],
                   ["ortiga", "¿Y mañana? ¿Me va a traer pan mañana también? ¿Y a las otras cuarenta madres de la plaza?"],
                   [null, "Lo acepta igual. Lo corta en cinco con el hilo. Ella no come."]], end: { xp: 10, flag: "e5_ortigaPan" } },
      marcha: { say: [["ortiga", "¿Ir al Fondo? ¿A hablar? ¿Con la regente?"],
                      [null, "Mira a los chicos. Mira la plaza, donde otras madres cortan pan con hilo."],
                      ["ortiga", "Bueno. Pero no a hablar. A pararnos en la puerta del granero con los hijos de la mano, todas juntas, y que nos miren. Hablar es para los que tienen tiempo."],
                      [null, "Una semana después, ochenta madres del Prado bajan al Fondo con sus hijos. Se paran en la puerta del granero en silencio. No piden nada. La fila de atrás las deja pasar."],
                      [null, "Cellisca sale al tercer día. Les da un saco a cada una. Esa noche, en el Fondo, la guardia anota los nombres de las ochenta."]], end: { xp: 20, flag: "m5_marchaPrado" } },
    } },

    "e5-tablero": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { pavesa: "Pavesa, farolera" }, start: "a", nodes: {
      a: { say: [[null, "Detrás de la plaza, bajo un metro de nieve, Pavesa cava con una pala de madera. Debajo aparece una pared de piedra cubierta de casilleros de tiza, borrosos por la humedad."],
                 ["pavesa", "El tablero de mi abuelo. Las noches del Barrio, una por casillero. Lo tapó la nieve el primer invierno. Pensé que se había borrado."],
                 ["pavesa", "Mire el último casillero. Es de la noche antes de la primera nevada. Después, nada. Como si el tiempo se hubiera parado aquí."]],
           opts: [{ t: "«¿Por qué dejó de contar?»", go: "porque", once: true },
                  { t: "Empezar a contar los días de invierno en el tablero", go: "contar" },
                  { t: "Borrar el tablero para empezar de cero", go: "borrar" },
                  { t: "Llevar el tablero a la plaza, donde todos lo vean", go: "plaza" }] },
      porque: { say: [["pavesa", "Mi abuelo se murió esa noche. De viejo, en su cama, con la tiza en la mano. No por el frío. Fue casualidad."],
                      ["pavesa", "Nadie siguió contando porque nadie quería ser el que contara el invierno. Contar es aceptar que dura."]], back: "a" },
      contar: { say: [[null, "Pavesa y tú cuentan los inviernos con los dedos, con los viejos, con las marcas de las puertas. Al final, ella dibuja casilleros nuevos. Muchos. Llenan la pared entera y siguen por la de al lado."],
                      [null, "Al anochecer hay siete mil trescientos casilleros. Veinte años. Pavesa se sienta en la nieve y los mira."],
                      ["pavesa", "Ahora se ve. Antes era una sola noche larga. Ahora son siete mil noches. Es peor. Pero es verdad. Mañana pongo uno más."]], end: { xp: 16, flag: "e5_tableroDias" } },
      borrar: { say: [[null, "Pavesa pasa la mano por la pared. La tiza vieja se deshace como harina mojada."],
                      ["pavesa", "Ya está. Ni noches que faltan ni noches que sobran. Pared limpia."],
                      [null, "Al día siguiente, alguien dibujó un casillero solo en el medio de la pared limpia. Adentro dice «hoy»."]], end: { xp: 10, flag: "e5_tableroBorrado" } },
      plaza: { say: [[null, "Cortan el pedazo de pared con los casilleros, piedra por piedra, y lo arman otra vez bajo el farol grande de la plaza. Tarda tres días."],
                     [null, "La gente pasa y lo mira. Una vieja busca el casillero del día que se casó. Un chico busca el día que nació. Nadie encuentra el día de hoy: no está."],
                     ["pavesa", "Mañana lo agrego. Y pasado. Y si algún día termina el invierno, el último casillero lo dibuja el que tenga la mano más fría."]], end: { xp: 14, flag: "e5_tableroPlaza" } },
    } },

    "e5-carbonilla": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { carbonilla: "Carbonilla, deshollinadora" }, start: "a", nodes: {
      a: { say: [[null, "De una chimenea de la casa grande de los Albor sale humo. Es la única chimenea con humo de la calle. Por el techo baja una chica negra de hollín de la cabeza a los pies."],
                 ["carbonilla", "¡Shh! Me llamo Carbonilla. Limpio chimeneas, o limpiaba, cuando había fuego. Esta tiene fuego todos los días. Me metí para ver por qué."],
                 ["carbonilla", "Tienen un sótano lleno de sacos con el sello del Fondo. Sacos de granero. Muchos. Y allá en la fila dicen que no alcanza."]],
           opts: [{ t: "«¿Cómo consiguieron esos sacos?»", go: "como", once: true },
                  { t: "Contárselo a toda la calle", go: "contar" },
                  { t: "Sacar algunos sacos de noche y llevarlos a la plaza", go: "sacar" },
                  { t: "Golpear la puerta y hablar con los Albor", go: "hablar" }] },
      como: { say: [["carbonilla", "Comprados. Hay un guardia del Fondo que vende sacos por la puerta de atrás, por monedas. Los Albor tienen monedas. Siempre tuvieron."],
                    ["carbonilla", "La regente dice que no sabe. A lo mejor no sabe. A lo mejor no quiere saber, porque las monedas del guardia también suben."]], back: "a" },
      contar: { say: [[null, "Carbonilla se sube a un farol y grita lo del sótano a toda la calle. La gente sale de las casas con las mantas puestas. Se juntan frente a la puerta de los Albor."],
                      [null, "Nadie rompe nada. Se quedan parados. Al rato, el viejo Albor abre la puerta, mira la multitud y empieza a sacar sacos. Uno por familia."],
                      ["carbonilla", "No lo hizo por bueno. Lo hizo porque eran muchos. Igual comimos. Y ahora todo el Prado sabe que en el Fondo se vende por atrás."]], end: { xp: 18, flag: "m5_ventaExpuesta" } },
      sacar: { say: [[null, "Esa noche entras con Carbonilla por la carbonera. Entre Carbonilla y tú cargan cuatro sacos, en silencio, y los dejan en la plaza, bajo el farol."],
                     [null, "A la mañana, cuatro familias comen. A la tarde, los Albor ponen dos guardias en la puerta. Guardias del Fondo."],
                     ["carbonilla", "Cuatro sacos. Y ahora tienen guardia. Bueno. La próxima vez entro por la chimenea. Para eso soy flaca."]], end: { xp: 12, coins: 5, flag: "e5_sacosRobados" } },
      hablar: { say: [[null, "Te abre el viejo Albor en persona. Tiene un chaleco de lana gruesa y las mejillas rojas de calor. Te escucha sin dejarte pasar."],
                      [null, "«Los compré con lo mío. No le robé a nadie. Si los vendían, alguien los iba a comprar. ¿Prefiere que los compre alguien peor?»"],
                      [null, "Cierra la puerta. Carbonilla, en el techo, te hace un gesto de que eso ya lo sabía."]], end: { xp: 8, flag: "e5_alborHablado" } },
    } },

    "e5-coplas": { kind: "encuentro", need: { era: 5, layer: 3 }, who: { ortiga: "Ortiga, del Prado", velon: "Velón, guarda del Farol" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza del Prado, alrededor del farol grande, un grupo canta una copla nueva. Es sobre una chica del Hielo y un chico de la Seta que se quieren y no los dejan. La letra es chistosa. Al final, no."],
                 ["ortiga", "Ortiga, la del hilo. ¿La oyó? La trajo un carretero del Fondo. Dicen que la hizo el mismo chico de la Seta. Ahora la canta todo el Prado."],
                 ["velon", "Velón, del Farol. Me llegó la orden del Fondo: la copla no se canta. La regente dice que esa canción hace más daño que el frío."]],
           opts: [{ t: "«¿Qué daño hace una canción?»", go: "dano", once: true },
                  { t: "Pararte delante de los que cantan", go: "proteger" },
                  { t: "«Cambien la letra. Que no nombre a nadie.»", go: "cambiar" },
                  { t: "Dejar que el guarda los disperse", go: "callar" }] },
      dano: { say: [["velon", "Dice que si la gente canta que una ley es injusta, después va a pensar que todas las leyes son injustas. Y después el granero."],
                    ["ortiga", "Una canción no abre graneros, Velón. El hambre sí. La canción solo dice lo que ya sabemos."]], back: "a" },
      proteger: { say: [[null, "Te paras entre Velón y los que cantan. No dices nada. Velón te mira largo rato."],
                        ["velon", "Si me quedo, tengo que cumplir la orden. Si me voy, nadie la cumple. Me voy a buscar a otro guarda. Tardo mucho en encontrarlo, seguro."],
                        [null, "Velón se va despacio. La copla sigue. A la mitad, Ortiga la canta más fuerte. Al final, con los últimos versos, la plaza entera canta."]], end: { xp: 18, flag: "e5_coplasLibres" } },
      cambiar: { say: [["ortiga", "¿Sin nombres? Bueno. Que sea una chica de una casa y un chico de otra. Cualquiera."],
                       [null, "La copla cambia. Ahora no habla del Hielo ni de la Seta. Habla de dos casas cualquiera y una ley cualquiera. Velón la escucha entera y no encuentra nada que prohibir."],
                       ["velon", "Así no la puedo parar. Y así la puede cantar cualquiera, sobre cualquier ley. No sé si ganó la regente o perdió."]], end: { xp: 14, flag: "e5_coplasCambiadas" } },
      callar: { say: [[null, "Velón golpea el farol con la vara. La gente deja de cantar, uno por uno. Se van a sus casas sin mirarlo."],
                      ["ortiga", "Mañana la canto en mi casa. Con la puerta cerrada. Mis cinco hijos se la saben."],
                      ["velon", "Ya sé. Cumplí la orden. La orden no decía nada de las casas."]], end: { xp: 8, flag: "e5_coplasCalladas" } },
    } },

    "e5-llamas": { kind: "encuentro", need: { era: 5, layer: 3 }, who: { pavesa: "Pavesa, farolera" }, start: "a", nodes: {
      a: { say: [[null, "Pavesa te espera en su casa, con la puerta cerrada y las cortinas corridas. Sobre la mesa hay un cuenco con una llama congelada adentro. La llama se mueve. Muy poco, como un párpado."],
                 ["pavesa", "Mire. Anoche mi vecina vino a llorar porque se le murió la madre en la fila. Le agarré las manos. Las dos teníamos el cuenco entre las manos sin darnos cuenta."],
                 ["pavesa", "La llama se movió. Se derritió un poco. Calentó. Cuando la solté, se quedó quieta otra vez. Lo probé sola, con una mano, con las dos. Nada. Tiene que ser entre dos."]],
           opts: [{ t: "«¿La llama que saqué del farol?»", go: "mia", cNeed: "e5_llamaFria", once: true },
                  { t: "Probarlo con ella, entre las dos manos", go: "probar" },
                  { t: "«Cuénteselo a todo el Prado.»", go: "contar" },
                  { t: "«No lo cuente todavía. Primero hay que entenderlo.»", go: "guardar" }] },
      mia: { say: [["pavesa", "Esa. La que se le cayó en la mano. La guardé. Le debo una."],
                   ["pavesa", "Usted la sacó del vidrio. Yo la tenía en un cuenco. Hacía falta alguien llorando para que se moviera. No sé qué quiere decir eso. Algo, seguro."]], back: "a" },
      probar: { say: [[null, "Pones las manos alrededor del cuenco, del otro lado de las de Pavesa. Las manos de ella están frías y ásperas."],
                      [null, "La llama tiembla. Se estira. Por un momento, el cuenco calienta como una taza de caldo. Después Pavesa suelta y la llama se queda quieta."],
                      ["pavesa", "Ya ve. Entre dos. La segunda estatua del Corazón tiene dos figuras con las manos juntas. Mi abuelo decía que cantaban. A lo mejor también calentaban."]], end: { xp: 16, heal: 0.05, flag: "e5_llamaDosManos" } },
      contar: { say: [[null, "Pavesa sale a la plaza con el cuenco. Lo pasa de pareja en pareja. Con algunas parejas la llama no se mueve. Con otras se mueve apenas."],
                      [null, "Con una vieja y un chico que no se conocen, la llama se estira entera y calienta la plaza un instante. La gente aplaude como si fuera un fuego de verdad."],
                      ["pavesa", "No es con cualquiera. No sé con quién es. Pero la gente se agarra de las manos para probar. Eso ya es algo, en este invierno."]], end: { xp: 18, flag: "e5_llamaPlaza" } },
      guardar: { say: [["pavesa", "Tiene razón. Si se sabe, el Fondo va a querer las llamas. O la Corte. Y van a venderlas por pareja."],
                       [null, "Envuelve el cuenco en un trapo y lo esconde en el horno frío."],
                       ["pavesa", "Cuando sepamos qué es, lo cuento. Ojalá no lo sepamos demasiado tarde. Esporina, la de la Seta, dice que la verdad tarde no sirve. Eso dicen, por lo menos."]], end: { xp: 12, flag: "e5_llamaGuardada" } },
    } },

    "e5-ladrona": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { carbonilla: "Carbonilla, deshollinadora", velon: "Velón, guarda del Farol" }, start: "a", nodes: {
      a: { say: [[null, "En la puerta del puesto del Farol, Velón tiene sentada en un banco a una chica tiznada de negro, con las muñecas atadas con cinta. A los pies, un balde de carbón."],
                 ["carbonilla", "¡Usted! Soy Carbonilla, la de las chimeneas. Dígale que el carbón estaba tirado. Que nadie lo usaba."],
                 ["velon", "Velón, del Farol. El carbón estaba en la carbonera del Farol. Es para las estufas de los puestos. Si no hay carbón, los guardas se congelan. Y sin guardas, se roba más."]],
           opts: [{ t: "«¿Para quién era el carbón?»", go: "quien", once: true },
                  { t: "Pagar el carbón y que la suelten", go: "pagar", fx: { cost: 12 } },
                  { t: "«Que trabaje en el puesto hasta pagarlo.»", go: "trabajar" },
                  { t: "«La ley es la ley.»", go: "ley" }] },
      quien: { say: [["carbonilla", "Para la casa de los Robles, en la calle de abajo. Tienen un bebé. El bebé no para de toser."],
                     ["velon", "Siempre hay un bebé. A veces es verdad. Esta vez lo es, ya fui a mirar. Eso no cambia de quién es el carbón."]], back: "a" },
      pagar: { say: [[null, "Le das a Velón unas monedas. Él las cuenta, las guarda y le corta la cinta a Carbonilla."],
                     ["velon", "Pagado. Lleve el balde. Y la próxima vez, golpee la puerta del puesto primero. Hay más carbón del que parece."],
                     ["carbonilla", "¿En serio? Bueno. Golpeo. Pero si no abre, entro por la chimenea."]], end: { xp: 14, flag: "e5_carbonPagado" } },
      trabajar: { say: [["velon", "¿Trabajar en el puesto? ¿Ella?"],
                        [null, "Carbonilla se ríe. Después ve que no es chiste."],
                        [null, "Durante una semana, Carbonilla limpia las chimeneas de los puestos del Farol. Al final, las estufas tiran el doble. Velón le da un balde de carbón por cada chimenea."],
                        ["velon", "Pagó el carbón y se llevó más. Y mis estufas no echan humo. No sé quién le robó a quién."]], end: { xp: 16, flag: "e5_carbonillaFarol" } },
      ley: { say: [["velon", "La ley es la ley. Sí. Una noche en el puesto, con la estufa. Mañana se va."],
                   [null, "Esa noche, Carbonilla duerme al lado de la estufa del Farol. Es la primera noche tibia en un mes. El balde de carbón se queda en el puesto."],
                   [null, "En la calle de abajo, el bebé de los Robles tose toda la noche."]], end: { xp: 8, flag: "e5_carbonillaPresa" } },
    } },
  });

  /* ---------- Cráter Tibio: el Gremio, el metal de raíz, las filas de dormidos y la grieta ---------- */
  add("crater", {
    "e5-brasero": { kind: "dialogo", need: { era: 5, layer: 1 }, who: { brasero: "Maese Brasero, del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En la puerta del Cráter, sentado en una silla de hierro junto a una montaña de troncos, un hombre gordo con el delantal del Gremio cuenta la leña que entra. Cada tronco, una raya en una pizarra."],
                 ["brasero", "Maese Brasero, del Gremio. Usted es la persona del Vado. ¿Viene a quejarse de la entrada? Todos vienen a quejarse. Nadie viene a cortar leña."],
                 ["brasero", "Sin troncos no hay fuego. Sin fuego no hay Cráter. Yo no hago las reglas del invierno. Solo las anoto."]],
           opts: [{ t: "«¿Qué pasa con la leña que sobra?»", go: "sobra", once: true },
                  { t: "«El Gremio vendió el calor toda la vida. Ahora cobra la entrada.»", go: "gremio" },
                  { t: "Cortar leña para pagar la entrada de otros", go: "cortar" },
                  { t: "«Cuénteme cómo era el Cráter antes del invierno.»", go: "antes" }] },
      sobra: { say: [[null, "Brasero deja de anotar. Mira la montaña de troncos, que es más alta que la puerta."],
                     ["brasero", "No sobra. Se guarda. Para cuando no traigan."],
                     ["brasero", "Bueno. Una parte va a la Hondonada. La Corte da mantas de sombra por leña. Las mantas las usan los maestros. ¿Qué quiere? Los maestros también tienen frío."]], end: { xp: 10, flag: "e5_braseroVende" } },
      gremio: { say: [["brasero", "Toda la vida, sí. Mi abuelo vendió hornos. Mi padre vendió metal de raíz. Yo vendo una noche al lado del fuego."],
                      ["brasero", "Lo que cambia es lo que se vende. El Gremio no cambia. Si no fuera así, no habría Gremio. Y sin Gremio, ¿quién cuida el fuego? ¿Usted?"]], back: "a" },
      cortar: { say: [[null, "Vas al borde del Bosque con un hacha prestada y cortas ramas muertas todo el día. Las traes en un trineo. Brasero las cuenta una por una, sin perdonar ninguna."],
                      ["brasero", "Doce troncos. Doce noches. ¿Para quién?"],
                      [null, "Le señalas a la gente del final de la cola. Brasero los raya en la pizarra, de mala gana."],
                      ["brasero", "Doce. Ni una más. Mañana, si quiere, vuelva con el hacha. Es la única queja que acepto."]], end: { xp: 14, flag: "e5_lenaCortada" } },
      antes: { say: [["brasero", "Antes había humo. Mucho. Y ruido de martillos. Y se cobraba el metal, no la entrada. Nadie quería dormir aquí: era el lugar más feo del Claro."],
                     ["brasero", "Ahora es el más lindo. Porque hace calor. Lo lindo depende del frío que haga afuera. Anótelo, si quiere. Es gratis."]], back: "a" },
    } },

    "e5-rescoldo": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { rescoldo: "Rescoldo, nieto de Chispa" }, start: "a", nodes: {
      a: { say: [[null, "Al fondo del Cráter, donde estaban los hornos hondos de la primera forja, alguien sacó las piedras que tapaban la escalera de hierro. Abajo brilla algo rojo. Sube un calor seco."],
                 [null, "Un muchacho con un pico sale del agujero, sudado, con la cara roja. Tiene las manos envueltas en trapos."],
                 ["rescoldo", "Soy Rescoldo. Mi abuela es Chispa. No le diga que me vio. Ahí abajo el metal de raíz sigue caliente, como hace cincuenta años. Si lo subo, el Cráter entero se calienta. Nadie duerme afuera."]],
           opts: [{ t: "«¿Sabe lo que el metal les hizo a las manos?»", go: "manos", once: true },
                  { t: "«Su abuela forja en frío. Sabe por qué.»", go: "abuelaA", cNeed: "end_chispa_A" },
                  { t: "«Su abuela tiene una mano entera gris.»", go: "abuelaB", cNeed: "end_chispa_B" },
                  { t: "«Su abuela dejó la forja por eso.»", go: "abuelaC", cNeed: "end_chispa_C" },
                  { t: "Ayudarlo a cavar", go: "cavar" },
                  { t: "Tapar el agujero con él", go: "tapar" },
                  { t: "Contárselo a Chispa", go: "contar" }] },
      manos: { say: [[null, "Rescoldo se mira los trapos de las manos."],
                     ["rescoldo", "Lo sé. Me envuelvo. Y no lo trabajo: solo lo subo. Un poco de gris a cambio de que nadie se congele. Mire la cola de afuera y dígame que no vale."]], back: "a" },
      abuelaA: { say: [["rescoldo", "Forja en frío y hace clavos torcidos. Y nosotros nos congelamos con clavos torcidos."],
                       ["rescoldo", "No la juzgo. Ella eligió las manos. Yo elijo la cola de afuera."]], back: "a" },
      abuelaB: { say: [["rescoldo", "Gris hasta el codo. Y es la mejor forjadora que hubo. Lo dice todo el mundo."],
                       ["rescoldo", "Ella me enseñó que el metal se paga con las manos. Yo pago. Igual que ella."]], back: "a" },
      abuelaC: { say: [["rescoldo", "La dejó, sí. Vende pan. Y cuando pasa por el Cráter no mira para adentro."],
                       ["rescoldo", "Yo no quiero dejar nada. Quiero que el Fuego sirva para algo. Para eso es el Fuego."]], back: "a" },
      cavar: { say: [[null, "Bajas con Rescoldo por la escalera de hierro. Abajo, el aire quema los ojos. El metal de raíz asoma de la roca como venas rojas."],
                     [null, "Suben tres canastos en un día. Los ponen en el centro del Cráter. El calor llega hasta la puerta. Esa noche entra la cola entera."],
                     [null, "A la mañana, Rescoldo se saca los trapos. Tiene una línea gris fina en el borde de las uñas."],
                     ["rescoldo", "Ya empezó. Bueno. Ya sabía."]], end: { xp: 18, coins: 10, flag: "e5_rescoldoCava" } },
      tapar: { say: [["rescoldo", "¿Taparlo? ¿Con la cola de afuera?"],
                     [null, "Pero te ayuda. Ponen las piedras otra vez, una por una. El brillo rojo desaparece. El calor seco se va."],
                     ["rescoldo", "Usted elige por mis manos. Gracias, supongo. Esta noche voy a dormir afuera, con la cola. Para ver si me arrepiento."]], end: { xp: 12, flag: "e5_rescoldoParado" } },
      contar: { say: [[null, "Encuentras a Chispa repartiendo brasas. Cuando le cuentas, deja el balde en el suelo y se queda quieta."],
                      [null, "Baja al fondo del Cráter despacio, con su bastón. Rescoldo la ve llegar y suelta el pico."],
                      [null, "No le grita. Se sientan los dos al borde del agujero, mirando el rojo de abajo. Hablan una hora. Cuando suben, el agujero sigue abierto. Rescoldo tiene los trapos nuevos, bien atados, y Chispa lleva el pico."]], end: { xp: 16, flag: "e5_chispaSabe" } },
    } },

    "e5-dormidos": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { chispa: "Chispa, forjadora" }, start: "a", nodes: {
      a: { say: [[null, "Amanece en el Cráter. La gente se levanta de las filas, dobla las mantas, sale a la nieve. En la última fila, la más lejos del fuego, un viejo no se levanta."],
                 ["chispa", "Chispa. ¿Se acuerda de mí? Ayúdeme con él. Es el tercero esta semana. Siempre en la última fila."],
                 ["chispa", "Las filas van por lo que se paga. Dos troncos, al lado del fuego. Uno, en el medio. Ramas, al fondo. El que trae ramas duerme en el borde, y el borde es casi afuera."]],
           opts: [{ t: "«¿Quién decidió el orden?»", go: "quien", once: true },
                  { t: "«Que las filas roten. Cada noche, una fila más cerca.»", go: "rotar" },
                  { t: "«Los viejos y los chicos, al lado del fuego. Paguen lo que paguen.»", go: "necesidad" },
                  { t: "Sacar al viejo en silencio", go: "sacar" }] },
      quien: { say: [["chispa", "Nadie. Se fue haciendo. El que traía más se ponía más cerca, y nadie le dijo que no. Después los maestros lo anotaron. Y lo anotado es ley."],
                     ["chispa", "Así se hacen casi todas las leyes, en el Gremio. Alguien se pone primero y después se escribe."]], back: "a" },
      rotar: { say: [[null, "Esa noche, Chispa y tú mueven a la gente fila por fila. Los de dos troncos protestan. Los de ramas no se animan a acostarse cerca del fuego."],
                     [null, "En una semana, cada familia durmió una noche al lado de las brasas y una noche en el borde. Nadie se muere en la última fila. Dos se enferman en la primera, de calor y de nervios."],
                     ["chispa", "Nadie está contento. Todos están vivos. Así son las cosas justas, en mi experiencia."]], end: { xp: 18, flag: "e5_filasRotan" } },
      necesidad: { say: [["chispa", "¿Y quién decide quién es viejo? ¿Yo? ¿Usted?"],
                         [null, "Lo hacen igual. Los viejos y los chicos al centro, los demás alrededor. Los que pagaron dos troncos duermen en el borde, furiosos."],
                         [null, "A la semana, algunas familias jóvenes dejan de traer leña. ¿Para qué, si igual duermen lejos?"],
                         ["chispa", "Los viejos viven. Hay menos leña. Ya veremos qué pesa más. Nada es gratis en el Cráter. Ni siquiera la bondad."]], end: { xp: 14, flag: "e5_filasNecesidad" } },
      sacar: { say: [[null, "Envuelves al viejo en su manta y lo sacas con Chispa por la puerta de atrás, para que no lo vean los chicos. Afuera, lo dejan en la nieve, junto a otros dos."],
                     ["chispa", "La tierra está demasiado dura para enterrarlos. Esperan la primavera. Todos esperamos la primavera."],
                     [null, "Chispa vuelve adentro a repartir brasas. Reparte un puñado extra en la última fila."]], end: { xp: 8 } },
    } },

    "e5-cizalla": { kind: "dialogo", need: { era: 5, layer: 2 }, who: { cizalla: "Cizalla, compradora de afuera" }, start: "a", nodes: {
      a: { say: [[null, "En un rincón del Cráter, una mujer muy vieja con una capa de piel que nadie en el Claro sabe curtir ofrece pan a cambio de algo. El pan es blanco, de un trigo que no crece aquí."],
                 ["cizalla", "Cizalla. Usted me conoce. Vine por los túneles de la Hondura, del otro lado de la montaña. Allá el invierno es corto. Nadie sabe por qué aquí no termina."],
                 ["cizalla", "Traigo trigo. Mucho. Lo cambio por metal de raíz. El rojo, el que no se enfría. Allá lo pagan bien. Para lo que lo usan, no le voy a mentir: espadas."]],
           opts: [{ t: "«¿Para qué quieren espadas, del otro lado?»", go: "espadas", once: true },
                  { t: "«Rescoldo está subiendo metal del fondo.»", go: "rescoldo", cNeed: "e5_rescoldoCava" },
                  { t: "Cambiar metal por trigo", go: "cambiar" },
                  { t: "«Llévese el trigo y no vuelva.»", go: "echar" },
                  { t: "«Trigo por otra cosa. Mantas, lana, lo que sea.»", go: "otra" }] },
      espadas: { say: [["cizalla", "Para lo de siempre. Hay tres señores del otro lado y cada uno quiere el valle del otro. Con metal de raíz, la espada no se mella. Gana el que tiene más."],
                       ["cizalla", "No me mire así. Ustedes tienen una Raíz que les cuida el valle. Nosotros tenemos espadas. Cada uno se arregla con lo que hay."]], back: "a" },
      rescoldo: { say: [["cizalla", "El nieto de la chica de los clavos. Sí. Ya hablé con él. Dijo que no vende a forasteros."],
                        ["cizalla", "Es joven. El invierno es largo. Ya va a vender."]], back: "a" },
      cambiar: { say: [[null, "Le traes a Cizalla un canasto de metal rojo del fondo del Cráter. Ella lo pesa en una balanza de hueso. Te da diez sacos de trigo blanco."],
                       [null, "Esa semana, el Cráter come pan blanco. Los chicos nunca vieron pan así. Cizalla se va por los túneles con el canasto a la espalda."],
                       ["cizalla", "Un buen negocio. Para usted y para mí. Del otro lado alguien va a ganar una guerra con su metal. Usted nunca va a saber quién. Eso también es un buen negocio."]], end: { xp: 16, coins: 20, flag: "m5_metalVendido" } },
      echar: { say: [["cizalla", "¿Sin trigo? ¿Con esta cola afuera?"],
                     [null, "Se ríe, una risa seca de vieja. Carga los sacos en su trineo."],
                     ["cizalla", "Vuelvo la próxima luna. Para entonces van a tener más hambre y menos orgullo. Siempre pasa."]], end: { xp: 10, flag: "e5_cizallaEchada" } },
      otra: { say: [["cizalla", "¿Mantas? Allá tenemos ovejas. ¿Lana? Tenemos lana."],
                    [null, "Piensa un rato. Mira las brasas del Cráter."],
                    ["cizalla", "Hay una cosa. Las canciones. Allá no tenemos canciones que hagan dormir a nadie. Cánteme la nana, la del Claro, y le dejo dos sacos. Para mis nietos, que no duermen."],
                    [null, "Le cantas la nana. Cizalla la repite tres veces, mal, hasta que le sale. Te deja dos sacos y se va por los túneles tarareando."]], end: { xp: 14, flag: "m5_nanaAfuera" } },
    } },

    "e5-voto": { kind: "dialogo", need: { era: 5, layer: 2 }, who: { brasero: "Maese Brasero, del Gremio", chispa: "Chispa, forjadora" }, start: "a", nodes: {
      a: { say: [[null, "En la sala de los maestros del Gremio, sobre el Cráter, hay doce maestros sentados en semicírculo. En el centro, de pie, Chispa. Brasero preside."],
                 ["brasero", "Votamos si el Cráter recibe gente sin leña. Hay quien dice que el Fuego no cobra a los que no tienen. Hay quien dice que sin cobrar no hay Fuego."],
                 ["chispa", "Yo digo lo primero. Ya lo saben. Por eso estoy de pie."]],
           opts: [{ t: "«Chispa ya los dejó entrar. ¿Se apagó el fuego?»", go: "apago", cNeed: "e5_calorGratis" },
                  { t: "Hablar a favor de Chispa", go: "chispa" },
                  { t: "«Que la Corte pague leña por las mantas que vende.»", go: "corte" },
                  { t: "No meterte en el voto", go: "nada" }] },
      apago: { say: [["brasero", "No. No se apagó. Pero hubo que quemar dos sillas del Gremio. Las sillas eran de mi abuelo."],
                     ["chispa", "Las sillas de su abuelo calentaron a cuarenta personas, Brasero. Su abuelo estaría orgulloso. O no. No lo conocí."]], back: "a" },
      chispa: { say: [[null, "Hablas ante los doce. Les cuentas la última fila, el viejo que no se levantó, el balde de brasas. No levantas la voz."],
                      [null, "Votan. Seis y seis. Brasero tiene que decidir. Se rasca la barba mucho tiempo."],
                      ["brasero", "Los que no tienen leña entran. Pero cargan agua, barren y atizan. Nadie duerme gratis: el que no paga con troncos, paga con manos. Así no se quejan los otros."],
                      ["chispa", "Con manos. Bueno. Eso el Fuego lo entiende."]], end: { xp: 18, flag: "e5_votoChispa" } },
      corte: { say: [["brasero", "¿La Corte? ¿Pagar? La Corte no paga, cambia."],
                     [null, "Pero lo piensa. Los maestros murmuran. La Corte se lleva leña del Cráter para tejer al calor."],
                     ["brasero", "Bueno. Por cada manta que la Corte se lleve hecha con nuestra leña, una noche gratis para alguien de la cola. Lo escribo. A ver si la Corte se entera."],
                     [null, "La Corte se entera. Durante un mes, nadie de la Hondonada vuelve a pedir leña. Después vuelven, y pagan."]], end: { xp: 16, flag: "e5_impuestoCorte" } },
      nada: { say: [[null, "Te quedas al fondo de la sala, sin hablar. Los maestros votan. Siete contra cinco: sin leña no se entra."],
                    ["chispa", "Bueno. Siete contra cinco. Antes eran once contra uno. Algo es."],
                    [null, "Chispa sale de la sala con la cabeza alta. Afuera, en la cola, la esperan cuarenta personas sin tronco."]], end: { xp: 8, flag: "e5_votoPerdido" } },
    } },

    "e5-molde": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { chispa: "Chispa, forjadora" }, start: "a", nodes: {
      a: { say: [[null, "En el fondo del Cráter, el viejo molde de la primera fundición está volcado de costado. Es tan grande que dentro duermen cuatro familias. Por dentro, la escarcha llenó las rayas de los nombres."],
                 ["chispa", "La lista de los que trabajaron la primera forja. Cuarenta y dos. Los raspé con la uña de chica, ¿se acuerda? Ahora, con la escarcha, se leen todos. Hasta el tachado."],
                 [null, "Debajo de la raya del nombre tachado, la escarcha dibuja letras. Y al lado, con otra mano, chiquito: «se fue al Hielo»."],
                 ["chispa", "Nevado. Dice Nevado."]],
           opts: [{ t: "«¿Nevado? ¿El del Turno?»", go: "nevado", once: true },
                  { t: "Contárselo a Esporina", go: "esporina" },
                  { t: "Raspar la escarcha para que no se lea", go: "raspar" },
                  { t: "Copiar la lista entera en una tablilla", go: "copiar" }] },
      nevado: { say: [["chispa", "El mismo. Trabajó en la primera forja de joven, antes del Hielo. Se fue cuando vio las manos grises. Los maestros lo tacharon por desertor."],
                      ["chispa", "Después fue al Fondo y cuidó a los que llegaban del Cráter con las manos grises. Toda la vida. Nunca supe por qué. Ahora sí."]], back: "a" },
      esporina: { say: [[null, "Bajas al Fondo, a los invernaderos de la Seta. Esporina te escucha sentada entre sus setas. Cuando dices «se fue al Hielo», cierra los ojos."],
                        [null, "«Nunca me contó que había sido del Fuego. Ciento veinte años creyendo que lo sabía todo de él. Y no sabía de dónde venía»."],
                        [null, "«Se fue del Fuego por las manos. Se fue de mí por la ley. Siempre se iba de lo que dolía. Yo me quedaba. No sé cuál de los dos tenía razón»."]], end: { xp: 18, flag: "e5_esporinaNevado" } },
      raspar: { say: [["chispa", "¿Raspar? ¿Otra vez?"],
                      [null, "Pero te deja. Raspas la escarcha con la manga. El nombre tachado vuelve a ser una raya. Las familias que duermen adentro te miran sin entender."],
                      ["chispa", "Ya está. Desertor otra vez. Que descanse tachado, si eso quería."]], end: { xp: 8, flag: "e5_nombreRaspado" } },
      copiar: { say: [[null, "Copias los cuarenta y dos nombres en una tablilla, con el carbón de una brasa. El tachado también, con la nota de al lado."],
                      [null, "Chispa la lee en voz alta, nombre por nombre. Algunas familias que duermen en el molde reconocen a un bisabuelo. Una mujer llora por un nombre que no conocía."],
                      ["chispa", "Cuarenta y dos. Ahora están en dos lugares. Si uno se borra, queda el otro. Eso aprendí de las Mareas: siempre dos copias."]], end: { xp: 16, flag: "e5_listaCopiada" } },
    } },

    "e5-martillo": { kind: "dialogo", need: { era: 5, layer: 3 }, who: { chispa: "Chispa, forjadora", rescoldo: "Rescoldo, nieto de Chispa" }, start: "a", nodes: {
      a: { say: [[null, "Chispa te pide que vengas a su casa, en la ladera sur. Es una casa chica con una forja apagada. Sobre el yunque frío hay un martillo con el mango gastado por una sola mano. Rescoldo está sentado en la puerta."],
                 ["chispa", "Me queda poco, Cuidador. Lo sé por cómo me cuesta subir la ladera. Este martillo fue lo primero que tuve del Fuego. Quiero decidir adónde va."],
                 ["rescoldo", "Yo lo quiero. Ya sé lo que va a decir, abuela. Igual lo quiero."]],
           opts: [{ t: "«¿Qué quiere usted que pase con él?»", go: "querer", once: true },
                  { t: "«Déselo a Rescoldo.»", go: "rescoldo" },
                  { t: "«Entiérrelo con usted.»", go: "enterrar" },
                  { t: "«Mándelo al Vado. Que lo use quien venga.»", go: "vado" }] },
      querer: { say: [["chispa", "Que nadie se ponga las manos grises con él. Eso quiero. Y que se siga golpeando. Las dos cosas no van juntas. Nunca fueron."],
                      ["rescoldo", "Yo me puse las manos grises sin martillo, abuela. Con un pico. El martillo no cambia nada."]], back: "a" },
      rescoldo: { say: [[null, "Chispa le alcanza el martillo a Rescoldo. Él lo agarra con las dos manos, como si pesara más de lo que pesa."],
                        ["chispa", "Golpea en frío cuando puedas. En rojo, cuando no haya más remedio. Y cuenta cada vez que no hubo más remedio. Si son muchas, algo estás haciendo mal."],
                        ["rescoldo", "Cuento. Lo prometo. Con tiza, como los del Barrio."]], end: { xp: 18, flag: "e5_martilloRescoldo" } },
      enterrar: { say: [["chispa", "¿Conmigo? Sí. Me gusta. Que el Fuego que yo hice se vaya conmigo y que Rescoldo haga el suyo."],
                        ["rescoldo", "Abuela..."],
                        ["chispa", "Ya sé. No es justo. Tú vas a tener que empezar de cero. Como yo, con un clavo torcido. Es la mejor manera que conozco."]], end: { xp: 14, flag: "e5_martilloEnterrado" } },
      vado: { say: [["chispa", "¿Al Vado? ¿Con usted, que no envejece?"],
                    [null, "Se ríe. Una risa de chica, la de la ladera sur, hace muchos años."],
                    ["chispa", "Bueno. Usted lo guarda. Cuando Rescoldo sea viejo y sepa lo que cuesta, se lo da. Si para entonces todavía quiere golpear, que golpee."],
                    [null, "Rescoldo no dice nada. Te mira llevarte el martillo como se mira algo que va a volver."]], end: { xp: 16, flag: "e5_martilloVado" } },
    } },

    "e5-grieta": { kind: "encuentro", need: { era: 5, layer: 3 }, who: { brasero: "Maese Brasero, del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En el piso del Cráter se abrió una grieta, de punta a punta, justo debajo de las filas de dormidos. Sale aire caliente, húmedo, con olor a tierra. La gente se pelea por dormir encima."],
                 ["brasero", "Brasero. La grieta apareció anoche. Calienta mejor que diez hornos. Y gratis. Por primera vez en mi vida, algo da calor gratis y yo no sé cobrarlo."],
                 [null, "Te agachas. El aire que sale es tibio como un aliento. Abajo, muy abajo, algo late despacio. Los que durmieron encima tienen una línea gris en las uñas."]],
           opts: [{ t: "«¿Por qué se abrió aquí?»", go: "porque", once: true },
                  { t: "Tapar la grieta con nieve y piedras", go: "tapar" },
                  { t: "«Que duerman encima. Una noche cada uno.»", go: "turnos" },
                  { t: "Avisar a todos lo de las uñas", go: "avisar" }] },
      porque: { say: [["brasero", "Los viejos del Gremio dicen que el Cráter es donde la Raíz tiene fiebre. Siempre tuvo. Por eso aquí se forja."],
                      ["brasero", "Si la Raíz se enfría por todos lados, a lo mejor viene aquí a calentarse. Como nosotros. Qué gracia."]], back: "a" },
      tapar: { say: [[null, "Traes nieve en baldes, piedras, tierra. La gente protesta. Algunos se acuestan encima de la grieta para que no la tapes."],
                     [null, "Al final queda tapada. El Cráter vuelve a estar frío en los bordes. Brasero suspira."],
                     ["brasero", "Las uñas se salvan. Los de la última fila, no sé. Usted decide qué se pierde, Cuidador. Siempre usted."]], end: { xp: 12, flag: "e5_grietaTapada" } },
      turnos: { say: [[null, "Organizas turnos: cada noche, una familia distinta duerme sobre la grieta. Una sola noche. Brasero lo anota en su pizarra, por costumbre."],
                      [null, "Al mes, medio Cráter tiene una raya gris fina en las uñas. Nadie se congela."],
                      ["brasero", "Una raya. Una noche, una raya. Así se paga en el Cráter desde siempre. Ahora lo pagamos todos un poco en vez de algunos mucho."]], end: { xp: 16, flag: "m5_grietaTurnos" } },
      avisar: { say: [[null, "Le muestras a la gente las uñas de los que durmieron encima. Algunos se alejan de la grieta. Otros se encogen de hombros y se acuestan."],
                      [null, "Una madre mira las uñas de su hija y la cambia de lugar. Un viejo se queda encima, abrazado al calor."],
                      ["brasero", "Ya saben. Ahora cada uno elige. Eso no lo puedo cobrar tampoco. Este invierno me está arruinando."]], end: { xp: 14, flag: "e5_grietaAviso" } },
    } },
  });

  /* ---------- Bosque Hondo: el leñador de noche, la madre de Centeno, la Madre helada, las cuentas y las semillas ---------- */
  add("forest", {
    "e5-serrin": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { serrin: "Serrín, leñador" }, start: "a", nodes: {
      a: { say: [[null, "De noche, en el Bosque Hondo, se oye un hacha. Golpes rápidos, nerviosos. Entre los robles, un muchacho con la cara tapada con una bufanda está tumbando un roble joven, sano."],
                 ["serrin", "¡No grite! Soy Serrín. Ya sé que no se puede. Pero en el Cráter un tronco es una noche. Y este roble son cuarenta noches. Mis hermanas duermen afuera."],
                 ["serrin", "El Concejo no corta. Dice que los robles son techo. Los robles no son techo para mí. Yo no tengo roble."]],
           opts: [{ t: "«¿Cuántos robles cortó?»", go: "cuantos", once: true },
                  { t: "Llevarlo ante Abeto, del Concejo", go: "abeto" },
                  { t: "«Corte ramas muertas. Le enseño cuáles.»", go: "muertas" },
                  { t: "Comprarle la leña y regalarla en el Cráter", go: "comprar", fx: { cost: 15 } }] },
      cuantos: { say: [["serrin", "Seis. Este es el séptimo. Todos jóvenes, porque los viejos son de familias y los jóvenes no son de nadie."],
                       ["serrin", "Los jóvenes eran los tres por uno. Los que plantaron para reponer. Ya sé. Ya sé, ya sé."]], back: "a" },
      abeto: { say: [[null, "Llevas a Serrín ante Abeto. El hombre del Concejo lo escucha en silencio, con las manos en las rodillas."],
                     [null, "«Los robles jóvenes son los que van a ser techo en diez años. Cortaste el techo de diez familias que todavía no existen»."],
                     [null, "El Concejo lo castiga a plantar diez bellotas por cada roble cortado, en la nieve, donde no crecen. Serrín planta setenta. Sus hermanas siguen durmiendo afuera."]], end: { xp: 10, flag: "e5_serrinCastigado" } },
      muertas: { say: [[null, "Le muestras a Serrín cómo reconocer una rama muerta: sin yemas, gris, que suena hueca. Trabajan codo con codo hasta el amanecer."],
                       [null, "Sale menos leña que de un roble. Mucha menos. Pero ningún árbol se cae."],
                       ["serrin", "Doce noches. No cuarenta. Bueno. Mis hermanas duermen adentro doce noches. Después vuelvo a buscar ramas. El Bosque tiene muchas ramas muertas este invierno."]], end: { xp: 16, flag: "e5_serrinRamas" } },
      comprar: { say: [[null, "Le pagas a Serrín por los troncos del roble ya cortado. Los cargas en un trineo y los llevas al Cráter. Los das en la puerta a los que no tienen."],
                       ["serrin", "Usted pagó un roble que ya estaba muerto. No sé si me ayudó o me enseñó que se vende."],
                       [null, "A la semana, se oye un hacha otra vez de noche, más lejos."]], end: { xp: 10, flag: "e5_serrinPagado" } },
    } },

    "e5-avena": { kind: "dialogo", need: { era: 5, layer: 1 }, who: { avena: "Doña Avena, madre de Centeno" }, start: "a", nodes: {
      a: { say: [[null, "En una casa al pie de un roble hueco, una mujer muy flaca teje una bufanda junto a una estufa sin fuego. Tres chicos duermen en una cama, abrazados."],
                 ["avena", "Pase. Soy Avena, la madre de Centeno. El que reparte en el granero. Mi hijo es el hombre más honrado del Claro. ¿Lo conoce? Cuenta todo, hasta los granos."],
                 ["avena", "Por eso no tenemos más que los demás. Él no se guarda nada. Otros en su lugar se llenarían el sótano. Él, nada."]],
           opts: [{ t: "«¿Usted sabe lo de los sacos debajo del piso?»", go: "piso", once: true },
                  { t: "«Centeno devolvió todo. Por eso usted está así de flaca.»", go: "devolvio", cNeed: "e5_centenoDevuelve" },
                  { t: "«Centeno repartió lo suyo entre las familias de los robles.»", go: "repartio", cNeed: "e5_centenoReparte" },
                  { t: "«Su hijo guarda sacos debajo del piso.»", go: "guarda", cNeed: "e5_centenoGuarda" },
                  { t: "«Su hijo es honrado. Tiene razón.»", go: "honrado" }] },
      piso: { say: [[null, "Avena deja de tejer. Se mira las manos."],
                    ["avena", "Debajo del piso hay lo que hay. Yo no miro el piso. Una madre no mira debajo del piso de su hijo."],
                    ["avena", "Si mira, tiene que elegir. Y yo no quiero elegir entre mi hijo y los nietos de otra."]], back: "a" },
      devolvio: { say: [["avena", "¿Devolvió? ¿Qué devolvió?"],
                        [null, "Le cuentas. Avena escucha con la bufanda a medio tejer en las rodillas."],
                        ["avena", "Entonces tenía sacos. Y los devolvió. Por los demás. Mientras sus sobrinos comían la mitad."],
                        [null, "Se queda callada un rato largo. Después sigue tejiendo, más rápido."],
                        ["avena", "Es honrado. Ya le dije. No sé si me alegra."]], end: { xp: 16, flag: "e5_avenaSabe" } },
      repartio: { say: [["avena", "¿Repartió? ¿Lo de quién?"],
                        [null, "Le cuentas. Los tres sacos, las cuarenta familias, el puñado para cada una."],
                        ["avena", "Lo robó y lo regaló. Mi hijo. Robó para todos y nos dio a nosotros lo mismo que a los demás. Un puñado."],
                        ["avena", "No sé si es un santo o un tonto. En mi pueblo, en invierno, es lo mismo."]], end: { xp: 16, flag: "e5_avenaSabe" } },
      guarda: { say: [[null, "Avena mira el piso. Mira la alfombra vieja que lo tapa. No se levanta."],
                      ["avena", "Ya lo sé. Desde el primer saco. Por eso los chicos tienen las mejillas así."],
                      ["avena", "Le digo a todo el mundo que es honrado para que nadie mire debajo de la alfombra. Si se lo cuenta a alguien, no le voy a perdonar. Si no, tampoco. Usted ya lo sabe."]], end: { xp: 14, flag: "e5_avenaSabe" } },
      honrado: { say: [["avena", "Sí. Eso digo yo."],
                       [null, "Te da la bufanda, terminada. Es gris, de lana áspera, larga."],
                       ["avena", "Para el frío del camino. Dígale a Centeno que la tejí yo, si lo ve. Que coma algo. Siempre se olvida de comer cuando reparte."]], end: { xp: 10, flag: "e5_bufandaAvena" } },
    } },

    "e5-madre": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { abeto: "Abeto, del Concejo" }, start: "a", nodes: {
      a: { say: [[null, "La Madre del Bosque, el árbol más grande del Claro, está cubierta de hielo hasta la copa. De las heridas viejas de su corteza cuelgan carámbanos de savia oscura, color miel quemada."],
                 [null, "Unos chicos rompen los carámbanos con palos y los chupan. Dicen que son dulces. Que calientan por dentro."],
                 ["abeto", "Abeto, del Concejo. Los chicos vienen todos los días. Dicen que con la savia helada no tienen frío. Lo que no dicen es que esa noche sueñan negro. Todos lo mismo."]],
           opts: [{ t: "«¿Qué sueñan?»", go: "suenan", once: true },
                  { t: "«¿Cómo está la Madre desde que la sangraron?»", go: "sangrada", cNeed: "end_hacha_A" },
                  { t: "«¿Queda algo de la Madre? Hacha dijo que no quedaba qué cortar.»", go: "nada", cNeed: "end_hacha_B" },
                  { t: "Prohibir que coman la savia", go: "prohibir" },
                  { t: "«Que coman. Un carámbano por chico, no más.»", go: "racion" },
                  { t: "Juntar la savia y llevarla a la Casa de la Seta", go: "seta" }] },
      suenan: { say: [["abeto", "Un lugar oscuro, abajo, donde algo enorme tiene frío. Los chicos dicen que lo abrazan para darle calor. Que se despiertan con los brazos cansados."],
                      ["abeto", "No sé qué es. Sé que es la savia de la Madre. Y que la Madre está conectada con todo lo de abajo."]], back: "a" },
      sangrada: { say: [["abeto", "Sangra de a poco, como dijo Hacha. Tres por uno. Ahora, con el hielo, la savia se congela al salir."],
                        ["abeto", "Hacha decía que la Madre nos daba lo que le pedíamos, aunque doliera. Me parece que ahora da sin que le pidan. Eso me asusta más."]], back: "a" },
      nada: { say: [["abeto", "Hacha se equivocó. Siempre queda algo. Quedaba la Madre, que no se corta porque es la Madre."],
                    ["abeto", "Hacha le vendía a la Corte la leña de los tocones. La Madre se quedó sola entre tocones. Por eso llora savia, dicen los chicos. Los chicos dicen muchas cosas."]], back: "a" },
      prohibir: { say: [[null, "Abeto pone una guardia del Concejo al pie de la Madre. Los chicos dejan de venir de día. Vienen de noche."],
                        ["abeto", "Prohibir es la mitad de cuidar. La otra mitad no sé cuál es."]], end: { xp: 10, flag: "e5_saviaProhibida" } },
      racion: { say: [[null, "Un carámbano por chico, por día. Abeto los reparte él mismo, de una canasta. Los chicos hacen fila. Nadie pelea."],
                      [null, "Esa noche, todos los chicos del Bosque sueñan lo mismo, más corto. Al despertar, dicen que el lugar de abajo tenía un poco menos de frío."],
                      ["abeto", "Abrazan algo en sueños, todos juntos. Y ese algo tiene menos frío. No sé si eso es bueno para los chicos. Para eso de abajo, parece que sí."]], end: { xp: 16, flag: "e5_saviaRacion" } },
      seta: { say: [[null, "Juntas los carámbanos de savia en un canasto y los llevas al Fondo, a los invernaderos de la Seta. Esporina los mira con la nariz arrugada."],
                    [null, "«Savia de la Madre. Esto se come en sueños, no despierto. La Seta sabe de sueños. La guardamos, la estudiamos. Si sirve para algo, se lo digo»."],
                    [null, "Te devuelve el canasto vacío. En el fondo hay una nota: «Gracias. No vuelva a traer más»."]], end: { xp: 14, flag: "e5_saviaSeta" } },
    } },

    "e5-pelea": { kind: "dialogo", need: { era: 5, layer: 2 }, who: { abeto: "Abeto, del Concejo" }, start: "a", nodes: {
      a: { say: [[null, "Dentro de un roble hueco hay gritos. Dos familias, una del Bosque y una del Prado, se pelean por un rincón al lado del fuego. Una olla está tirada en el suelo."],
                 ["abeto", "Abeto otra vez. Así todos los días, en todos los robles. Los de adentro dicen que el roble es suyo. Los de afuera dicen que el frío es de todos."],
                 ["abeto", "El Concejo me pide una regla. Una sola, que sirva para todos los robles. Yo no sé hacer reglas. Sé ahuecar árboles."]],
           opts: [{ t: "«¿Las familias de afuera viven en los robles?»", go: "afuera", once: true },
                  { t: "«Una cortina en el medio. Cada familia, su mitad.»", go: "cortina" },
                  { t: "«Una sola regla: el fuego en el centro, para todos.»", go: "centro" },
                  { t: "«El que pelea, sale a la nieve una noche.»", go: "nieve" }] },
      afuera: { say: [["abeto", "En algunos. Donde el Concejo abrió las puertas, sí. Donde no, se meten igual, de noche, y es peor."],
                      ["abeto", "Abrir no es lo difícil. Lo difícil es el día después, cuando ya están adentro y nadie sabe dónde poner la olla."]], back: "a" },
      cortina: { say: [[null, "Cuelgan una manta de lado a lado del roble. Cada familia, su mitad. Cada una, su fuego chico."],
                       [null, "Dejan de pelear. Tampoco hablan. Del otro lado de la manta se oye toser y no se pregunta quién."],
                       ["abeto", "Paz. Dos fuegos chicos queman más leña que uno grande. Pero paz."]], end: { xp: 12, flag: "e5_robleCortina" } },
      centro: { say: [[null, "Pones el fuego en el centro del roble. Las dos familias se sientan alrededor, de mala gana, mirándose."],
                      [null, "La primera noche, nadie habla. La tercera, la abuela del Bosque le enseña a la chica del Prado a tejer. La quinta, comparten la olla."],
                      ["abeto", "Un fuego, una olla. Lo escribo. Y si alguien se pelea, que se acuerde de quién le enseñó a tejer."]], end: { xp: 18, flag: "e5_robleFuego" } },
      nieve: { say: [[null, "Abeto lo anuncia en todos los robles: el que pelea, una noche en la nieve. La primera noche salen tres hombres. Uno no vuelve a entrar: se va al Cráter."],
                     [null, "Después nadie pelea. Nadie habla fuerte tampoco. En los robles se vive en voz baja."],
                     ["abeto", "Funciona. No me gusta cómo. Pero funciona."]], end: { xp: 10, flag: "e5_robleCastigo" } },
    } },

    "e5-criaturas": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { serrin: "Serrín, leñador" }, start: "a", nodes: {
      a: { say: [[null, "En un claro del Bosque, una manada de criaturas silvestres flacas rodea un roble hueco. Tienen el pelo erizado de escarcha. Huelen la comida de adentro."],
                 ["serrin", "Serrín. Vienen todas las noches desde que empezó el invierno. Se comen la corteza de los robles. Si se comen la corteza, el roble se muere, y la familia de adentro se queda sin techo."],
                 ["serrin", "La gente quiere matarlas. Yo tengo el hacha. Nadie más se anima."]],
           opts: [{ t: "«¿Siempre vinieron hasta aquí?»", go: "siempre", once: true },
                  { t: "Darles de comer de los sacos del granero", go: "comer" },
                  { t: "Espantarlas con fuego", go: "espantar" },
                  { t: "Guiarlas hasta los invernaderos de la Seta", go: "guiar" }] },
      siempre: { say: [["serrin", "No. Antes se quedaban en lo hondo. Pero en lo hondo ya no hay nada verde. Lo único verde que queda es lo que la gente guarda."],
                       ["serrin", "Tienen hambre como nosotros. No es culpa de nadie. Eso no ayuda, ¿no?"]], back: "a" },
      comer: { say: [[null, "Abres un saco del granero en la nieve. Las criaturas se acercan despacio, desconfiadas. Comen todo. No dejan nada."],
                     [null, "A la noche siguiente, vuelven el doble. Y a la otra, el triple."],
                     ["serrin", "Les enseñamos que aquí hay comida. Ahora no se van a ir nunca. Y el saco era de una familia."]], end: { xp: 10, flag: "e5_criaturasComen" } },
      espantar: { say: [[null, "Serrín y tú prenden antorchas y corren entre los robles gritando. Las criaturas huyen hacia lo hondo del Bosque."],
                        [null, "Una, la más flaca, no corre rápido. Se cae en la nieve. Serrín la mira, con el hacha en la mano. No la usa."],
                        ["serrin", "Se va a morir de frío igual. Pero no por mí. Es raro lo que uno elige no hacer."]], end: { xp: 12, flag: "e5_criaturasEspantadas" } },
      guiar: { say: [[null, "Con un saco de setas secas, abres un camino por la nieve hasta los túneles de la Seta, debajo del Fondo. Las criaturas te siguen, de lejos, toda la noche."],
                     [null, "En los invernaderos, Moho las ve llegar y se ríe a carcajadas. Les da los tallos que no se comen. Las criaturas se echan en el calor húmedo y se duermen."],
                     ["serrin", "La Seta tiene lugar para todo lo que nadie quiere. Debe ser por eso que la quieren tan poco."]], end: { xp: 18, flag: "e5_criaturasSeta" } },
    } },

    "e5-cuentas": { kind: "dialogo", need: { era: 5, layer: 3 }, who: { abeto: "Abeto, del Concejo" }, start: "a", nodes: {
      a: { say: [[null, "En la sala del Concejo, dentro del roble más viejo, Abeto te muestra un libro enorme de hojas de corteza. Cada página es un año. Cada línea, un árbol cortado y tres plantados."],
                 ["abeto", "Abeto. El libro de los tres por uno. Desde que se hizo la regla. Cada árbol que se corta, tres que se plantan. Está todo anotado. Mírelo bien."],
                 [null, "Lo miras. Las líneas son perfectas, todas iguales. Demasiado iguales. En los últimos veinte años, la letra no cambia nunca."]],
           opts: [{ t: "«¿Quién escribe esto?»", go: "quien", once: true },
                  { t: "«Hacha contaba los que vivían, uno por uno.»", go: "hacha", cNeed: "end_hacha_C" },
                  { t: "«Cuente en voz alta, ante todo el Bosque.»", go: "publicar" },
                  { t: "«Corríjalo en silencio. Desde hoy, cuentas reales.»", go: "corregir" },
                  { t: "«Déjelo como está. Ahora no es momento.»", go: "dejar" }] },
      quien: { say: [[null, "Abeto cierra el libro despacio."],
                     ["abeto", "Yo. Hace veinte años que escribo tres. Se planta uno. A veces ninguno, porque en la nieve no crece nada. Pero escribo tres."],
                     ["abeto", "Si escribo uno, el Concejo deja de cortar. Y si deja de cortar, los robles no se ahuecan. Y las familias se congelan. El libro miente para que el Bosque viva."]], back: "a" },
      hacha: { say: [["abeto", "Hacha. Sí. Contaba los vivos. Dos de cada tres se le morían, y lo anotaba. Lloraba anotando, dicen."],
                     ["abeto", "Después se murió ella y nadie quiso llorar anotando. Yo tampoco. Por eso escribo tres."]], back: "a" },
      publicar: { say: [[null, "Abeto llama a todo el Bosque a la sala del Concejo. Lee el libro en voz alta, página por página. Y después dice cuántos se plantaron de verdad."],
                        [null, "Silencio. Después gritos. Un viejo le tira una bellota a la cara. Una mujer llora por un roble que creía que estaba creciendo."],
                        ["abeto", "Ya saben. El Bosque se va a quedar con menos robles de los que creía. Y desde mañana, el libro dice la verdad. Una línea por árbol vivo."]], end: { xp: 20, flag: "m5_cuentasBosque" } },
      corregir: { say: [[null, "Abeto da vuelta a una página en blanco. Escribe la fecha. Debajo, con letra chica: «Desde aquí, lo que hay»."],
                        ["abeto", "Lo de atrás queda como está. Nadie lo va a leer. Y si alguien lo lee, que vea dónde cambió la letra."],
                        [null, "En la línea siguiente, Abeto escribe: «Cortados: uno. Plantados: uno. Vivos: ninguno»."]], end: { xp: 16, flag: "e5_cuentasCorregidas" } },
      dejar: { say: [["abeto", "Ahora no. Sí. Nunca es momento."],
                     [null, "Guarda el libro en un hueco del roble. Pasa la mano por la tapa, como quien acaricia a un perro viejo."],
                     ["abeto", "Cuando termine el invierno, lo corrijo. Si termina. Si no, que lo corrija el que venga."]], end: { xp: 8, flag: "e5_cuentasDejadas" } },
    } },

    "e5-semillas": { kind: "encuentro", need: { era: 5, layer: 3 }, who: { avena: "Doña Avena, madre de Centeno", abeto: "Abeto, del Concejo" }, start: "a", nodes: {
      a: { say: [[null, "Avena te espera en la puerta del roble del Concejo con una lista en la mano, hecha con un carbón. Abeto está a su lado, preocupado."],
                 ["avena", "Avena. Las semillas del Bosque están en el granero del Fondo, bajo el hielo de raíz. Todas: bellotas, piñas, trigo de primavera. Para cuando termine el invierno."],
                 ["abeto", "Si el hielo de raíz se derrite algún día, se pudren con la comida. Y si se pudren, no hay primavera aunque termine el invierno. Nadie pensó en eso."]],
           opts: [{ t: "«¿Por qué las guardaron ahí?»", go: "porque", once: true },
                  { t: "Sacar las semillas del Fondo y guardarlas en un roble", go: "sacar" },
                  { t: "«El granero es el lugar más seguro del Claro.»", go: "dejar" },
                  { t: "«La mitad afuera, la mitad adentro.»", go: "mitad" }] },
      porque: { say: [["abeto", "Porque el hielo de raíz conserva todo. Las semillas duran cien años ahí. En un roble, duran lo que dure la humedad."],
                      ["avena", "Y porque mi hijo reparte en el granero. Confiamos en él. Si sacamos las semillas, la gente va a preguntar por qué ya no confiamos."]], back: "a" },
      sacar: { say: [[null, "Bajas al Fondo con Avena y un trineo. Centeno los ve llegar y entiende sin que le expliquen. Les abre la sala de las semillas en silencio."],
                     [null, "Cargan bolsas de bellotas, de piñas, de trigo. Cellisca los ve pasar desde el pasillo y no dice nada. Anota algo en una tablilla."],
                     [null, "Las guardan en el roble más seco del Bosque, en tarros de barro sellados con cera."],
                     ["avena", "Ahora son nuestras. Si se pudren, es culpa nuestra. Prefiero eso."]], end: { xp: 18, flag: "e5_semillasFuera" } },
      dejar: { say: [["avena", "Sí. El más seguro. Mientras nadie lo derrita."],
                     ["abeto", "Y mientras el Fondo quiera devolverlas. Las semillas del Bosque en el sótano del Fondo. Si yo fuera la regente, también me gustaría."],
                     [null, "Avena guarda la lista en el bolsillo. No la tira."]], end: { xp: 8, flag: "e5_semillasDentro" } },
      mitad: { say: [[null, "Bajan al Fondo y sacan la mitad. Centeno cuenta cada bolsa dos veces, y anota «la mitad» en su tablilla."],
                     [null, "La mitad se queda bajo el hielo de raíz. La otra mitad, en tarros de barro en un roble del Bosque."],
                     ["abeto", "Si se pudre una mitad, queda la otra. Las Mareas tienen razón con lo de las dos copias. Hasta para las bellotas."]], end: { xp: 16, flag: "e5_semillasMitad" } },
    } },
  });

  /* ==================== Entrega 3: la Noche en invierno (Hondonada, Lago, Cuevas) ==================== */

  /* ---------- Hondonada Umbría: la Reina de las mantas, el archivo, la sombra de raíz y el primer olvido ---------- */
  add("hollow", {
    "e5-reina": { kind: "dialogo", need: { era: 5, layer: 1 }, who: { caligine: "Reina Calígine" }, start: "a", nodes: {
      a: { say: [[null, "En el Trono de la Hondonada, sentada entre pilas de mantas de sombra dobladas como monedas, hay una mujer joven con un velo de humo. Cuenta las mantas con los ojos, sin mover la cabeza."],
                 ["caligine", "Soy la Reina Calígine. Pase, pase. Usted es la persona del Vado. Tengo una propuesta para el Fondo, y el Fondo no habla con la Corte."],
                 ["caligine", "Mantas de sombra para todas las salas del Fondo. Todas. A cambio, la Corte come del granero como come el Fondo: primero. Nadie se congela en el Fondo, nadie pasa hambre en la Hondonada. ¿Ve algo malo?"]],
           opts: [{ t: "«¿Y los demás pueblos?»", go: "demas", once: true },
                  { t: "«La Reina Merma compraba noches para el norte vacío.»", go: "mermaA", cNeed: "end_merma_A" },
                  { t: "«Merma dejó el Trono cuando se supo todo.»", go: "mermaB", cNeed: "end_merma_B" },
                  { t: "«Merma pisa las monedas del Barrio todas las mañanas.»", go: "mermaC", cNeed: "end_merma_C" },
                  { t: "Llevar la propuesta a la regente", go: "llevar" },
                  { t: "«No. La Corte no come primero.»", go: "negar" },
                  { t: "«Mantas para la cola del Cráter, y lo hablo.»", go: "cola" }] },
      demas: { say: [["caligine", "Los demás pueblos tienen el Cráter, las cuevas, los robles. Y la fila. La fila es para todos."],
                     ["caligine", "La Corte siempre supo una cosa: en invierno, el que tiene lo que el otro necesita no hace fila. No lo inventé yo. Lo inventó el frío."]], back: "a" },
      mermaA: { say: [["caligine", "Mi tía abuela. La Corte se hizo pobre por eso. Pobre y querida. Eso no abriga."],
                      ["caligine", "Yo aprendí de ella lo contrario. No me mire así: la quise mucho."]], back: "a" },
      mermaB: { say: [["caligine", "Y vive en una casa chica, haciendo las cuentas del Bosque. Muy digna. Muy pobre."],
                      ["caligine", "El Trono no se deja, Cuidador. Si lo deja usted, se sienta otra. Mejor que me siente yo, que sé lo que cuesta."]], back: "a" },
      mermaC: { say: [["caligine", "Las pisa, sí. Y firma. Y la puerta sigue abierta. La Corte aprendió a vivir con vergüenza a la vista."],
                      ["caligine", "Eso es lo que somos ahora: una Corte que no esconde lo que hace. Por eso le propongo el trato en voz alta."]], back: "a" },
      llevar: { say: [[null, "Le llevas la propuesta a Cellisca. La regente la lee dos veces. Sonríe apenas, la primera vez que la ves sonreír."],
                      [null, "«Mantas para el Fondo. La regencia más tibia y la Corte más gorda. Y el Prado, más lejos de la puerta. Acepto»."],
                      [null, "A la semana, las salas del Fondo tienen mantas de sombra. La Corte baja a la fila y no hace fila. La gente de la fila mira pasar los velos sin decir nada."]], end: { xp: 14, coins: 15, flag: "m5_mantasFondo" } },
      negar: { say: [["caligine", "No. Bueno. Lo dijo claro, al menos."],
                     [null, "Se acomoda el velo. Una manta de la pila se desliza sola y cae al suelo."],
                     ["caligine", "Entonces el Fondo se congela un poco y la Corte come un poco menos. Todos un poco peor. Como a usted le gusta: parejo."]], end: { xp: 10, flag: "e5_caligineNo" } },
      cola: { say: [["caligine", "¿Mantas gratis para la cola del Cráter? ¿Para gente que no paga?"],
                    [null, "Lo piensa. Cuenta mantas con los ojos."],
                    ["caligine", "Cien. Cien mantas para la cola, con el sello de la Corte bien grande. Que todos vean quién abriga. Y usted me lleva el trato al Fondo."],
                    [null, "Las cien mantas llegan al Cráter con un sello negro del tamaño de una mano. La gente duerme tibia y mira el sello antes de cerrar los ojos."]], end: { xp: 16, flag: "e5_mantasCola" } },
    } },

    "e5-pesados": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { grisalla: "Grisalla, el que no se levanta" }, start: "a", nodes: {
      a: { say: [[null, "En una casa de la Hondonada, un hombre está acostado en el piso, envuelto en una manta de sombra. Su sombra, en la pared, es tan oscura que parece un agujero. Y tan pesada que lo aplasta contra el suelo."],
                 ["grisalla", "Grisalla. Me llamo Grisalla. Dormí con la manta todo el invierno. Todo. No me la saqué ni una noche. Ahora no me puedo levantar. La sombra pesa como una piedra."],
                 ["grisalla", "No me duele. Estoy tibio. Es lo único que importa, ¿no? Estar tibio."]],
           opts: [{ t: "«¿Por qué no se la sacó nunca?»", go: "nunca", once: true },
                  { t: "Sacarle la manta a la fuerza", go: "sacar" },
                  { t: "Llevarlo al Cráter, con la manta puesta", go: "crater" },
                  { t: "Quedarte con él y quitársela de a poco", go: "poco" }] },
      nunca: { say: [["grisalla", "Porque afuera hace frío. Y porque la manta no deja pensar. Uno se acuesta y deja de acordarse de por qué estaba triste."],
                     ["grisalla", "Se me murió la mujer en la fila del Fondo. Desde que tengo la manta, casi no me acuerdo. Casi."]], back: "a" },
      sacar: { say: [[null, "Tiras de la manta. Grisalla grita como si le arrancaras la piel. La manta sale. La sombra, en la pared, tarda un rato en soltarlo."],
                     [null, "Cuando lo suelta, Grisalla tirita, llora y se acuerda de todo de golpe. Del nombre de su mujer. De la fila. De todo."],
                     ["grisalla", "Ahora tengo frío. Y me acuerdo. ¿Era esto lo que quería para mí?"]], end: { xp: 12, hurt: 0.05, flag: "e5_grisallaFrio" } },
      crater: { say: [[null, "Lo cargas en un trineo, con manta y todo. Pesa el doble de lo que debería. En el Cráter lo pones al lado de las brasas."],
                      [null, "Con el calor de verdad, la sombra se afloja. A los tres días, Grisalla se sienta solo. A la semana, se saca la manta y la dobla."],
                      ["grisalla", "Calor de afuera. No es lo mismo que el de la manta. El de la manta era de adentro, y me comía."]], end: { xp: 16, flag: "e5_grisallaCrater" } },
      poco: { say: [[null, "Te quedas con Grisalla tres noches. Cada noche le sacas un poco la manta: los pies, después las piernas, después un brazo. Le cuentas cosas para que no se duerma."],
                    [null, "La tercera noche, él te cuenta de su mujer. Cómo se reía, cómo cortaba el pan. Llora. La sombra se afloja con cada palabra."],
                    ["grisalla", "Me hacía falta acordarme para poder levantarme. Qué cosa más rara. Pensé que era al revés."]], end: { xp: 18, flag: "e5_grisallaHabla" } },
    } },

    "e5-archivo": { kind: "dialogo", need: { era: 5, layer: 1 }, who: { sepia: "Sepia, archivera de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "En el archivo de la Corte, un sótano lleno de cajas de papel negro, una archivera joven con los dedos manchados de tinta te espera con un rollo abierto sobre la mesa."],
                 ["sepia", "Soy Sepia. Aprendí el archivo de Ébano, el viejo. Encontré esto en una caja que nadie abría. Es de antes de las Casas. De antes de los nombres de las zonas."],
                 ["sepia", "Habla de un invierno largo. Otro, no este. Uno que duró una vida entera. Y dice cómo terminó: «Hicimos una tumba sobre la herida de la Raíz, y la llamamos casa de un rey, para que nadie la abriera»."]],
           opts: [{ t: "«La Tumba Helada. No hay rey: es un sello.»", go: "sello", once: true },
                  { t: "«Ébano dejaba copias en todas las paredes.»", go: "ebanoA", cNeed: "end_ebano_A" },
                  { t: "«Ébano guardó una lista bajo llave toda su vida.»", go: "ebanoB", cNeed: "end_ebano_B" },
                  { t: "Mandar una copia a Desvelo, el de Los Que Oyen", go: "desvelo" },
                  { t: "Llevarle el rollo a la regente Cellisca", go: "cellisca" },
                  { t: "Copiarlo en las paredes del Corazón", go: "pared" }] },
      sello: { say: [["sepia", "Eso dice. La Tumba Helada no guarda un rey. Guarda un invierno que se terminó porque alguien selló un punto de la Raíz. Y después inventó el rey para que nadie quitara el sello."],
                     ["sepia", "Lo que no dice es qué le pasó a la Raíz con el sello puesto. Si le dolió. Si la dejó sorda. Los antiguos no anotaban eso."]], back: "a" },
      ebanoA: { say: [["sepia", "Sí. Me dejó la caja de copias cuando se fue. Me dijo: «Lo que guardas solo, lo pierdes»."],
                      ["sepia", "Por eso se lo muestro. Si me lo guardo, la Corte lo vende. Usted no lo va a vender. Creo."]], back: "a" },
      ebanoB: { say: [["sepia", "La lista. Sí. Se murió esperando el momento. Nunca llegó. La llave me la dio a mí."],
                      ["sepia", "No quiero envejecer esperando como él. Por eso le traigo esto ahora, aunque no sea el momento. Nunca es el momento."]], back: "a" },
      desvelo: { say: [[null, "Sepia copia el rollo con letra prolija y le das la copia a Desvelo frente a la Tumba. Él la lee de pie, en silencio, una vez, dos veces."],
                       [null, "Esa tarde no habla del Rey. Les dice a los de la fila que la Tumba es una tumba, que adentro hay una herida tapada, y que el invierno de antes terminó así."],
                       [null, "La gente lo escucha igual que siempre, con la misma cara. Al final, una mujer pregunta: «¿Y no se puede hacer otra?»."]], end: { xp: 16, flag: "e5_rolloDesvelo" } },
      cellisca: { say: [[null, "Cellisca lee el rollo en la sala del trono, sola, con la puerta cerrada. Cuando termina, lo enrolla con mucho cuidado."],
                        [null, "«Una tumba nueva. Así se terminó la otra vez. Esto le sirve a la regencia, Cuidador. Gracias. Va a ir a la caja de la regente, con llave»."],
                        [null, "Sepia, cuando se entera, no dice nada. Pero esa noche empieza otra copia."]], end: { xp: 12, flag: "e5_rolloCellisca" } },
      pared: { say: [[null, "Subes al Corazón con Sepia. Ella copia el rollo, palabra por palabra, con carbón, en la base de la Tumba Helada, del lado de afuera. Tarda toda la noche."],
                     [null, "A la mañana, la gente de la fila lo lee al pasar. Algunos se ríen. Otros se quedan mucho rato."],
                     ["sepia", "Ahora no es de nadie. Ni de la Corte ni del Fondo. Lo que está en una pared es de todos. Eso decía Ébano, o algo así."]], end: { xp: 18, flag: "m5_rolloPublico" } },
    } },

    "e5-telares": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { tizna: "Tizna, tejedora de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "Tizna te lleva detrás de los telares, a un cuarto sin ventanas. En el piso hay una grieta fina. De la grieta sube algo que no es humo ni niebla: sombra, espesa, que se mueve sola."],
                 ["tizna", "De aquí sale el hilo. Sombra de raíz, la llamaban las tejedoras viejas. La Corte cavó aquí en su primer exilio. Nunca lo dijo."],
                 ["tizna", "Lo malo es que la que teje se olvida de cosas. Chicas. El nombre de una calle. La cara de una tía. Las tejedoras viejas no saben cómo se llamaban sus madres."]],
           opts: [{ t: "«¿Usted se olvidó de algo?»", go: "olvido", once: true },
                  { t: "Tapar la grieta", go: "tapar" },
                  { t: "«Que cada tejedora teje un mes y descanse otro.»", go: "turnos" },
                  { t: "«Anote lo que olvida, antes de olvidarlo.»", go: "anotar" }] },
      olvido: { say: [[null, "Tizna se queda callada. Busca algo en la cabeza. No lo encuentra."],
                      ["tizna", "Sé que tuve un hermano. Sé que me enseñó a silbar. No sé cómo se llamaba. Lo busco todas las noches."],
                      ["tizna", "No me mire con pena. Todas las tejedoras tenemos un hermano sin nombre. Es el precio de las mantas."]], back: "a" },
      tapar: { say: [[null, "Echas tierra, piedra y cera en la grieta hasta que deja de subir sombra. Tizna te mira trabajar sin ayudarte ni impedirlo."],
                     [null, "Al día siguiente, los telares de la Corte se paran. No hay hilo. La Reina manda a cavar otra grieta, al otro lado de la Hondonada. La encuentran en una semana."],
                     ["tizna", "Siempre hay otra grieta. La Hondonada está llena. Gracias igual. Esta semana me acordé de una calle."]], end: { xp: 12, flag: "e5_grietaSombra" } },
      turnos: { say: [["tizna", "¿Descansar? ¿La Corte? Bueno. Le digo a la Reina que así las mantas salen mejor. Es verdad, a lo mejor."],
                      [null, "Las tejedoras tejen un mes y descansan otro. En el mes de descanso, algunas se acuerdan de cosas. Una se acuerda del nombre de su madre y llora un día entero."],
                      ["tizna", "Salen la mitad de mantas. La Reina está furiosa. Las tejedoras, menos tristes. No sé qué pesa más en la Hondonada."]], end: { xp: 16, flag: "e5_tejerTurnos" } },
      anotar: { say: [[null, "Tizna consigue un cuaderno. Esa noche anota todo lo que sabe de su vida: nombres, calles, la canción de silbar. Llena veinte páginas."],
                      [null, "A la semana, lee el cuaderno y hay cosas que no recuerda haber escrito. Pero están ahí, con su letra."],
                      ["tizna", "Es raro leerse. Como leer a una tía. Pero ahora sé que el silbido era de mi hermano. Eso lo dice el cuaderno."]], end: { xp: 14, flag: "m5_sombraRaizHallada" } },
    } },

    "e5-contrabando": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { sepia: "Sepia, archivera de la Corte", centeno: "Centeno, intendente del granero" }, start: "a", nodes: {
      a: { say: [[null, "Por un túnel bajo la Hondonada pasa un trineo cargado de mantas de sombra, de noche, sin farol. Al otro lado, en la entrada sur del Fondo, un guardia del Fondo cambia las mantas por sacos del granero."],
                 ["sepia", "Sepia. Lo anoto todo, es mi trabajo. Cuarenta mantas por semana. Veinte sacos. Los sacos salen del granero sin que Centeno los cuente: los saca el guardia por la puerta de las setas."],
                 ["sepia", "Los Albor del Prado compran del mismo guardia. Es un solo hombre. Le dicen el Portero. Nadie sabe su nombre de verdad."]],
           opts: [{ t: "«¿La Reina lo sabe?»", go: "reina", once: true },
                  { t: "Contárselo a Cellisca", go: "cellisca" },
                  { t: "Contárselo a Centeno", go: "centeno" },
                  { t: "Desviar los sacos de esta noche a la cola del Cráter", go: "desviar" }] },
      reina: { say: [["sepia", "La Reina lo manda. La regente, no sé. Si no lo sabe, es tonta. Y la regente no es tonta."],
                     ["sepia", "Lo que sé es que en el Fondo dicen que no alcanza. Y alcanza para el Portero, para la Corte y para los Albor. Alcanza para los que tienen algo que dar."]], back: "a" },
      cellisca: { say: [[null, "Cellisca escucha sin mover las manos cruzadas. Al final, manda llamar al Portero. Esa misma noche lo echan del Fondo, a la nieve, sin abrigo."],
                        [null, "«Un guardia que vende. Se terminó. La regencia no vende»."],
                        [null, "A la semana, la Corte manda las mantas por otro túnel. Las recibe otro guardia. Sepia lo anota en su cuaderno sin sorprenderse."]], end: { xp: 12, flag: "e5_porteroEchado" } },
      centeno: { say: [[null, "Centeno escucha y se pone blanco. Cuenta con los dedos, rápido, como quien cuenta lo que le robaron."],
                       ["centeno", "Veinte por semana. Desde hace un año. Es la mitad de lo que reparto al Prado."],
                       [null, "Esa noche, Centeno pone su cama en la puerta de las setas. Duerme ahí todo el invierno, con la tablilla en el pecho. El trineo de la Corte no vuelve a pasar por ahí."]], end: { xp: 18, flag: "e5_centenoPuerta" } },
      desviar: { say: [[null, "Esperas al trineo en el túnel. Cuando el Portero carga los sacos, le dices que hay un cambio de ruta. Te cree, porque nadie más sabe del túnel."],
                       [null, "Los veinte sacos llegan esa noche a la cola del Cráter. Los reparte Chispa con el balde de brasas en la otra mano."],
                       ["sepia", "Lo anoto: «Veinte sacos, desviados por la persona del Vado». Cuando la Corte lea mi cuaderno, va a saber. Yo no miento en el cuaderno."]], end: { xp: 16, flag: "e5_sacosDesviados" } },
    } },

    "e5-sombras": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { tizna: "Tizna, tejedora de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "En una calle de la Hondonada, la noche dura tanto que las sombras de los muertos se quedan en las paredes. En el muro de una casa hay una sombra chica, de chico, quieta, con una mano levantada."],
                 [null, "Una mujer le habla todas las noches. Le cuenta cómo estuvo el día. Le deja un plato de sopa al lado."],
                 ["tizna", "Tizna. Es la madre de un chico que se congeló en la fila. La sombra se quedó. Pasa en toda la Hondonada este invierno. Hay calles con más sombras que gente."]],
           opts: [{ t: "«¿La sombra le contesta?»", go: "contesta", once: true },
                  { t: "Dejarla hablar con la sombra", go: "dejar" },
                  { t: "«Su hijo ya no está. Tiene que soltarlo.»", go: "soltar" },
                  { t: "Llevarla a la sala de los soñadores del Fondo", go: "turno" }] },
      contesta: { say: [["tizna", "No. Pero se mueve un poco cuando ella habla. Como la llama de la Pavesa, dicen en el Prado. Con dos, se mueve."],
                        ["tizna", "Los viejos dicen que cuando venga el sol, las sombras se van. Ella no quiere que venga el sol. Es la única persona del Claro que no quiere."]], back: "a" },
      dejar: { say: [[null, "Te sientas en el umbral y escuchas. La mujer le cuenta a la sombra que hoy consiguió leña, que la vecina tosió menos, que la nieve está alta."],
                     [null, "En un momento, la sombra baja la mano. Despacio. La mujer se calla y la mira mucho rato."],
                     ["tizna", "Nunca la había bajado. A lo mejor estaba esperando que alguien más escuchara."]], end: { xp: 14, flag: "e5_sombraBaja" } },
      soltar: { say: [["tizna", "¿Decírselo usted? ¿A ella?"],
                      [null, "Se lo dices. Despacio, con cuidado. La mujer te escucha sin dejar de mirar la pared."],
                      [null, "«Ya sé que no está. No soy tonta. Le hablo porque si no le hablo yo, no le habla nadie. Y si nadie le habla, se va del todo»."],
                      [null, "Te cierra la puerta. La sopa sigue en el plato, al lado de la sombra."]], end: { xp: 8, flag: "e5_sombraDicho" } },
      turno: { say: [[null, "La llevas al Fondo, a la sala del Turno. Los soñadores la reciben sin preguntas y le dan una manta encerada."],
                     [null, "Esa noche sueña con su hijo. Él le dice cosas que ella no sabía, cosas de chico, cosas que nunca le contó. Al despertar, las repite en voz alta para no olvidarlas."],
                     ["tizna", "Volvió a la Hondonada más tranquila. La sombra sigue en la pared. Pero ahora ella le cuenta menos y le escucha más."]], end: { xp: 18, flag: "e5_sombraSueno" } },
    } },

    "e5-castigo": { kind: "dialogo", need: { era: 5, layer: 3 }, who: { caligine: "Reina Calígine", tizna: "Tizna, tejedora de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "En el Trono, Tizna está de rodillas frente a la Reina Calígine. Le ataron las manos con su propio hilo. El hilo se le enrosca en las muñecas solo, como si la conociera."],
                 ["caligine", "Mi mejor tejedora me roba. No monedas: mantas. Y me arruina las ventas contando lo que cuestan. Dígame, Cuidador: ¿qué hace una Reina con algo así?"],
                 ["tizna", "Lo que hacen todas, Majestad. Esperar a que otra teja mejor. No hay otra."]],
           opts: [{ t: "«¿Qué hizo exactamente?»", go: "hizo", once: true },
                  { t: "«Las mantas que regaló salvaron veinte familias.»", go: "regalo", cNeed: "e5_mantasRegaladas" },
                  { t: "«Las etiquetas hacen que la gente confíe en la Corte.»", go: "etiqueta", cNeed: "e5_mantasEtiqueta" },
                  { t: "Defender a Tizna ante la Reina", go: "defender" },
                  { t: "Ofrecer pagar lo que se perdió", go: "pagar", fx: { cost: 25 } },
                  { t: "No meterte", go: "nada" }] },
      hizo: { say: [["caligine", "Veinte mantas perdidas en un traslado que nunca pasó. Y papeles cosidos que dicen que la manta pesa. ¿Sabe cuántas mantas dejé de vender por un papel?"],
                    ["tizna", "Las que hubieran aplastado a alguien, Majestad. Esas dejó de vender."]], back: "a" },
      regalo: { say: [["caligine", "Veinte familias de otros pueblos. Que ni saben que fue la Corte. Llegaron sin nota."],
                      ["caligine", "Si las hubiera mandado con el sello, por lo menos. Regalar sin firmar es tirar."]], back: "a" },
      etiqueta: { say: [["caligine", "Confiar. Sí. La gente compra menos y confía más. No se come confianza."],
                        [null, "Lo dice. Pero se queda mirando una manta con etiqueta mucho rato."]], back: "a" },
      defender: { say: [[null, "Hablas ante el Trono. Dices lo de la cola del Cráter, lo de Grisalla, lo del hermano sin nombre. La Reina escucha detrás del velo."],
                        ["caligine", "Bueno. Basta. Me aburre la bondad ajena."],
                        [null, "Corta el hilo de las muñecas de Tizna con una tijera de plata."],
                        ["caligine", "Vuelva al telar. Con etiquetas, si quiere. Pero las mantas que regale, con mi sello. Si la Corte va a ser buena, que se note."]], end: { xp: 20, flag: "e5_tiznaLibre" } },
      pagar: { say: [[null, "Pones un puñado de monedas en el escalón del Trono. La Reina las mira sin agacharse."],
                     ["caligine", "Pagado. La Corte siempre acepta. Por eso nunca pierde."],
                     [null, "Le sueltan las manos a Tizna. Ella no te agradece. Se frota las muñecas y vuelve al telar sin mirar a nadie."]], end: { xp: 12, flag: "e5_tiznaPagada" } },
      nada: { say: [[null, "Te quedas al fondo de la sala, sin hablar. La Reina espera un rato. Después hace un gesto."],
                    ["caligine", "A la grieta. Un mes tejiendo al lado de la sombra de raíz, sin descanso. A ver qué recuerda después."],
                    [null, "Tizna sale sin resistirse. Cuando pasa a tu lado, te dice bajito, sin enojo: «Anote mi nombre en algún lado, por las dudas»."]], end: { xp: 8, flag: "e5_tiznaGrieta" } },
    } },

    "e5-frascos": { kind: "encuentro", need: { era: 5, layer: 3 }, who: { sepia: "Sepia, archivera de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "En un puesto del mercado de la Hondonada, un vendedor con guantes negros ofrece frascos chicos tapados con cera. Adentro se mueve algo oscuro. Hay fila."],
                 ["sepia", "Sepia. Es sombra de raíz, en frasco. Se respira una vez y se olvida una cosa. Una sola. La que uno elija, si piensa fuerte en ella."],
                 ["sepia", "La gente compra para olvidar a sus muertos del invierno. A sus hijos, a sus viejos. Un frasco, un muerto. Y se van más livianos. Lo anoto todo, y no sé dónde anotar esto."]],
           opts: [{ t: "«¿Quién lo vende?»", go: "quien", once: true },
                  { t: "Romper los frascos", go: "romper" },
                  { t: "«Que cada uno elija. Pero que sepa lo que compra.»", go: "elegir" },
                  { t: "Respirar un frasco, para saber qué es", go: "probar" }] },
      quien: { say: [["sepia", "La Corte. La Reina dice que es un servicio. Que el invierno ya tiene demasiada pena y que la pena no abriga."],
                     ["sepia", "Lo que no dice es que el que olvida no protesta. Una fila sin muertos es una fila tranquila."]], back: "a" },
      romper: { say: [[null, "Tiras el puesto. Los frascos se rompen contra las piedras. La sombra sube, se enrosca, se va hacia arriba como humo pesado."],
                      [null, "Los de la fila respiran un poco sin querer. Algunos se quedan quietos, con la cara en blanco. Otros te gritan."],
                      [null, "Una mujer te agarra del brazo: «Yo quería olvidarla. Usted no sabe lo que es acordarse todos los días». Después se va, llorando, acordándose."]], end: { xp: 12, hurt: 0.05, flag: "e5_frascosRotos" } },
      elegir: { say: [["sepia", "Que sepan. Bueno. Les escribo un papel, como los de Tizna."],
                      [null, "Sepia pega en el puesto un papel con letra grande: «Lo que olvidas no vuelve. El que te quiso, tampoco»."],
                      [null, "La fila se achica a la mitad. La otra mitad compra igual. Uno lee el papel dos veces, compra, respira y se va silbando."],
                      ["sepia", "La mitad. Lo anoto. Dentro de veinte años, alguien va a vender esto en todas las esquinas. Lo sé por cómo silbaba ese hombre."]], end: { xp: 16, flag: "m5_olvidoVendido" } },
      probar: { say: [[null, "Abres un frasco y respiras. Es frío y no huele a nada. Piensas fuerte en algo: el camino de esta mañana."],
                      [null, "Un segundo después, no sabes cómo llegaste al mercado. Sabes que llegaste. No sabes por dónde."],
                      ["sepia", "Una cosa chica. ¿Ve? Ahora imagínese a su madre. Uno se lleva el frasco a la boca pensando en una cosa chica, y después piensa en otra más grande."]], end: { xp: 14, hurt: 0.05, flag: "e5_olvidoProbado" } },
    } },
  });

  /* ---------- Lago Espejo: la pesca bajo el hielo, los que están abajo, las Mareas y el lago que respira ---------- */
  add("lake", {
    "e5-pesca": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { ancla: "Ancla, pescador de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "Sobre el hielo del Lago hay cien agujeros redondos, cada uno con una persona sentada al lado, con una caña corta. Pescan de noche, con faroles bajos, porque de noche los peces suben."],
                 ["ancla", "Ancla, de las Mareas. Pescamos para el Fondo. Cada canasto de pescado son dos sacos del granero. El Fondo lo congela y lo guarda para siempre."],
                 ["ancla", "Lo raro es que el Prado tiene hambre a medio día de aquí. Y nosotros pescamos para el Fondo, que tiene el sótano lleno. Así es el trato."]],
           opts: [{ t: "«¿Por qué no le venden al Prado?»", go: "prado", once: true },
                  { t: "Llevar el pescado de hoy al Prado, directo", go: "llevar" },
                  { t: "«Cumplan el trato. Dos sacos por canasto es bueno.»", go: "trato" },
                  { t: "«Que las Mareas coman primero. Pescan ustedes.»", go: "mareas" }] },
      prado: { say: [["ancla", "El Prado no tiene nada que dar. El Fondo tiene sacos. Un pescador no come pescado todo el invierno, se enferma. Necesita grano."],
                     ["ancla", "Las Mareas aprendimos a cambiar con el que tiene. No es maldad. Es el agua: corre para abajo, hacia el que tiene el pozo más hondo."]], back: "a" },
      llevar: { say: [[null, "Cargas tres canastos en un trineo y cruzas el lago por las banderas. Al amanecer llegas a la plaza del Prado."],
                      [null, "Ortiga reparte el pescado con el hilo, en partes iguales. Esa mañana, el Prado come caliente."],
                      ["ancla", "Tres canastos menos para el Fondo. Seis sacos menos para nosotros. Bueno. Mis hijos comen pescado esta semana. Se van a quejar."]], end: { xp: 16, flag: "e5_pescadoPrado" } },
      trato: { say: [["ancla", "Bueno. Es bueno. Para nosotros."],
                     [null, "Los canastos van al Fondo. Los sacos vuelven al lago. Las Mareas comen grano y pescado, y en sus casas de la orilla no se pasa hambre."],
                     ["ancla", "Las Mareas comemos. Eso es lo que me toca cuidar. Los otros, que cuiden los suyos."]], end: { xp: 10, coins: 10, flag: "e5_pescaFondo" } },
      mareas: { say: [["ancla", "¿Primero nosotros? Siempre fuimos los últimos. Los que llegaban tarde, sin casa."],
                      [null, "Ancla lo piensa. Mira a los pescadores, flacos, con las manos rojas de frío."],
                      ["ancla", "Un canasto de cada tres queda en el lago. Para nosotros. Por primera vez, las Mareas comen de lo que pescan. Mi abuela no lo vio nunca."]], end: { xp: 12, flag: "e5_pescaMareas" } },
    } },

    "e5-caras": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { rada: "Doña Rada" }, start: "a", nodes: {
      a: { say: [[null, "Cerca de las banderas del camino seguro, una familia de las Mareas está arrodillada sobre el hielo. Abajo, a un brazo de profundidad, hay un hombre congelado con los ojos abiertos. Es su padre."],
                 ["rada", "Rada. Se cayó el invierno pasado, cruzando de noche. Lo encontraron recién ahora, cuando el hielo se aclaró. Quieren sacarlo para enterrarlo en la orilla."],
                 ["rada", "Pero está debajo del camino. Si rompen el hielo aquí, el camino se rompe. Y por el camino cruzan cien personas por día."]],
           opts: [{ t: "«¿Hay otra forma de cruzar?»", go: "otra", once: true },
                  { t: "Ayudarlos a sacarlo", go: "sacar" },
                  { t: "«Déjenlo. El camino es de los vivos.»", go: "dejar" },
                  { t: "Poner una bandera negra sobre él, para que nadie lo pise", go: "bandera" }] },
      otra: { say: [["rada", "Hay. Por el borde norte, que es más largo. Medio día más. Con chicos y viejos, medio día más en el hielo es mucho."],
                    ["rada", "Los muertos no tienen apuro. Los vivos sí. Eso dicen los que no tienen un muerto abajo."]], back: "a" },
      sacar: { say: [[null, "Picas el hielo con la familia toda la noche. Al amanecer, el hombre sale entero, duro, con la escarcha en las pestañas. Lo envuelven en una vela de barca."],
                     [null, "El agujero queda abierto en el camino. Al día siguiente, la fila tiene que dar la vuelta por el norte. Un viejo se cae en el borde y se moja hasta la cintura."],
                     ["rada", "Lo enterraron en la orilla. La familia duerme. El viejo mojado tiene fiebre. Así se reparte el invierno: a uno le das, al otro le sacas."]], end: { xp: 14, flag: "e5_padreSacado" } },
      dejar: { say: [[null, "La familia te escucha. La hija mayor asiente despacio. Los chicos lloran."],
                     [null, "Cada mañana, antes de cruzar, la familia se arrodilla un momento en el mismo lugar y después sigue. La fila aprende a esperarlos."],
                     ["rada", "Ahora el camino tiene un muerto debajo, y todos lo saben. Se pisa más despacio ahí. Algo es."]], end: { xp: 10, flag: "e5_padreDejado" } },
      bandera: { say: [[null, "Pones una bandera negra en el hielo, encima de él. El camino da una pequeña vuelta para no pisarlo."],
                       [null, "A la semana hay otras banderas negras, puestas por otras familias, sobre otros muertos. El camino serpentea entre ellas."],
                       ["rada", "Un cementerio sobre el agua. Las Mareas nunca tuvimos cementerio: los muertos se iban con la corriente. Ahora se quedan, mirando para arriba."]], end: { xp: 18, flag: "e5_banderasNegras" } },
    } },

    "e5-horno": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { ancla: "Ancla, pescador de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "En el centro del lago, el hielo tiene un círculo más fino. Debajo se ve la forja redonda hundida, con su brasa roja encendida en el fondo. Alrededor del círculo, el hielo suda."],
                 ["ancla", "Ancla. Una forja de las del metal, de las que el Lago compró y después hundió. Abajo sigue prendida. Es metal de raíz: no se apaga nunca."],
                 ["ancla", "Unos jóvenes quieren bajar a buscarla. Con una forja así, las casas de la orilla tendrían calor todo el invierno. Bajar es meterse en agua helada."]],
           opts: [{ t: "«¿Por qué la hundieron?»", go: "porque", once: true },
                  { t: "Bajar a buscar la brasa", go: "bajar", fx: { cost: 10 } },
                  { t: "«Dejen la forja donde está.»", go: "dejar" },
                  { t: "Abrir un agujero para que el calor suba", go: "agujero" }] },
      porque: { say: [["ancla", "Porque los pescadores se ponían grises. Los que pescaban cerca de la forja. El pescado salía cocido y con gusto a metal."],
                      ["ancla", "La hundimos para que el agua la apagara. El agua no la apagó. Solo la tapó."]], back: "a" },
      bajar: { say: [[null, "Atas una cuerda a la cintura y bajas por un agujero, con una pinza larga y un balde de hierro. El agua te muerde hasta los huesos."],
                     [null, "Abajo, la brasa late como un corazón. La agarras con la pinza, la metes en el balde y tiras de la cuerda. Te suben sin aliento, con los labios morados."],
                     [null, "La brasa calienta una casa de la orilla durante todo el invierno. Los que viven ahí tienen, a la primavera, una raya gris en las uñas."],
                     ["ancla", "Tibios y grises. Es el trato de siempre con el metal. Por lo menos ahora lo saben."]], end: { xp: 16, hurt: 0.1, flag: "e5_brasaLago" } },
      dejar: { say: [["ancla", "Donde está. Bueno. Que siga prendida abajo, sin hacerle daño a nadie."],
                     [null, "Pones una bandera roja al lado del círculo fino. Los jóvenes protestan, pero respetan la bandera."],
                     ["ancla", "Hay cosas que se guardan abajo del agua porque arriba no se sabe qué hacer con ellas. El Lago está lleno de esas."]], end: { xp: 10, flag: "e5_forjaDejada" } },
      agujero: { say: [[null, "Picas un agujero grande sobre la forja. El agua de abajo sale tibia, con vapor. La gente de la orilla viene a calentarse las manos."],
                       [null, "Por una semana, el agujero es el lugar más tibio del lago. Después se congela por los bordes y hay que volver a picarlo cada mañana."],
                       ["ancla", "Agua tibia, sin tocar el metal. Las manos rojas, no grises. Me gusta más así. Da más trabajo, pero me gusta más."]], end: { xp: 14, flag: "e5_aguaTibia" } },
    } },

    "e5-rompiente": { kind: "dialogo", need: { era: 5, layer: 2 }, who: { rompiente: "Rompiente, voz de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "En la casa más grande de la orilla, la que tiene el techo de barca dada vuelta, las Mareas están reunidas. Habla una mujer joven, de pie sobre un banco, con la voz fuerte de los que gritan en el agua."],
                 ["rompiente", "Soy Rompiente, voz de las Mareas este invierno. Las Cuevas están tibias. El Lago, congelado. Las Mareas siempre se fueron cuando el agua se ponía mala. Yo digo que nos vayamos a las Cuevas."],
                 ["rompiente", "Pero la Hondura cobra la entrada. Y si nos vamos, las casas de la orilla se pierden. Nos costó tres generaciones tener casas. No quiero que se pierdan por un invierno."]],
           opts: [{ t: "«La Hondura deja entrar gratis a los chicos.»", go: "chicos", cNeed: "e5_chicosGratis" },
                  { t: "«Vayan todos a las Cuevas.»", go: "irse" },
                  { t: "«Quédense. Las casas son lo que tienen.»", go: "quedarse" },
                  { t: "«Que vayan los chicos y los viejos. Los demás cuidan las casas.»", go: "partir" }] },
      chicos: { say: [["rompiente", "Los chicos, sí. Y el que lleva un chico de la mano. Ya lo sé. La mitad de las Mareas tiene un chico de la mano."],
                      ["rompiente", "Pizca es buena. La Hondura, no sé. La Hondura cobra la mitad de los años y regala la otra mitad. Nunca se sabe en cuál estamos."]], back: "a" },
      irse: { say: [[null, "Las Mareas votan con las manos. Gana irse. A la semana, una fila de trineos cruza el lago hacia las Cuevas."],
                    [null, "Las casas de la orilla se quedan vacías. Para la primavera, la gente del Prado quema las puertas. El Lago tiene otra vez una orilla sin casas."],
                    ["rompiente", "Estamos vivos. Estamos en las Cuevas, pagando con lo que hay. Y otra vez no tenemos casa. Como mi bisabuela. El agua siempre vuelve al mismo lugar."]], end: { xp: 14, flag: "m5_mareasCuevas" } },
      quedarse: { say: [["rompiente", "Quedarnos. Con las casas. Bueno. Las casas no abrigan, pero son nuestras."],
                        [null, "Las Mareas se quedan en la orilla. Queman la mitad de las barcas para calentarse. A la primavera no van a tener con qué pescar."],
                        ["rompiente", "Tenemos casas y no tenemos barcas. Un pueblo de agua sin barcas. Mi abuela se moriría de risa."]], end: { xp: 12, flag: "e5_mareasOrilla" } },
      partir: { say: [[null, "Se parten. Los chicos y los viejos, a las Cuevas. Los grandes, en la orilla, cuidando las casas, pescando de noche."],
                      [null, "Cada luna, los de la orilla cruzan a ver a los suyos. Los chicos les cuentan de las galerías tibias. Los grandes les cuentan del hielo."],
                      ["rompiente", "Partidos. Como el agua cuando le pones una piedra en el medio. Del otro lado se junta otra vez. Eso espero."]], end: { xp: 18, flag: "e5_mareasPartidas" } },
    } },

    "e5-valvulas": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { ancla: "Ancla, pescador de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla sur, las válvulas del Lago están congeladas dentro de un bloque de hielo. Son las que manejaba Salitre: las que dejan correr el agua de abajo hacia arriba."],
                 ["ancla", "Ancla. Si las abrimos, el agua de abajo sube. El agua de abajo es tibia, porque viene de cerca de la Raíz. Puede que derrita la orilla. Puede que congele todo lo de abajo."],
                 ["ancla", "Nadie sabe usarlas. La llave la tenía Salitre. Se murió con la llave al cuello."]],
           opts: [{ t: "«Salitre anotaba más palabras que números.»", go: "salA", cNeed: "end_salitre_A" },
                  { t: "«Salitre tenía un cofre de monedas y vergüenza en la última hoja.»", go: "salB", cNeed: "end_salitre_B" },
                  { t: "«Salitre juntaba pescado cocido para el Barrio.»", go: "salC", cNeed: "end_salitre_C" },
                  { t: "Romper el hielo y abrir las válvulas", go: "abrir" },
                  { t: "Dejarlas cerradas", go: "cerrar" }] },
      salA: { say: [["ancla", "Su cuaderno. Sí. Lo tiene Rada. Dice: «Abrir de a poco. El Lago se enoja si lo apuras»."],
                    ["ancla", "Si eso es una instrucción o un consejo de vieja, no sé. Con Salitre era lo mismo."]], back: "a" },
      salB: { say: [["ancla", "El cofre se lo llevó la Corte cuando se murió, por deudas. La última hoja la tiene su nieta. Dice una palabra: «Abrir»."],
                    ["ancla", "No sabemos si quiere decir que las abrió o que hay que abrirlas. Una palabra es poco para un Lago."]], back: "a" },
      salC: { say: [["ancla", "Lo que quedaba del pescado cocido de la orilla sur. Sí. Olía a metal. Comíamos igual."],
                    ["ancla", "Ella decía que las válvulas cerradas eran las que cocinaban el pescado. Que abiertas, el agua de abajo se mezcla y se enfría. No sé si tenía razón."]], back: "a" },
      abrir: { say: [[null, "Rompes el bloque con una barreta. Las válvulas aparecen, oxidadas, con forma de mano. Las giras de a poco, con Ancla del otro lado."],
                     [null, "Abajo, algo ruge. El agua sube por las grietas del hielo de la orilla, tibia, humeante. En una noche, la orilla sur se descongela un tramo de cien pasos."],
                     [null, "En el centro del lago, en cambio, el hielo se pone más grueso. El agua tibia se fue para arriba y dejó lo frío abajo."],
                     ["ancla", "Una orilla tibia y un fondo más frío. Los peces van a buscar la orilla. Nosotros también. Ya veremos qué pasa con el fondo."]], end: { xp: 16, flag: "m5_valvulasAbiertas" } },
      cerrar: { say: [["ancla", "Cerradas. Como estaban. Bueno."],
                      [null, "Ancla le echa nieve encima al bloque, como quien tapa una cosa que no quiere ver."],
                      ["ancla", "Un Lago congelado se cruza a pie. Un Lago medio derretido no se cruza de ninguna forma. Hay cosas peores que el hielo."]], end: { xp: 10, flag: "e5_valvulasCerradas" } },
    } },

    "e5-patines": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { ancla: "Ancla, pescador de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "Sobre el lago congelado patinan chicos de las Mareas con cuchillas de hueso atadas a las botas. Van rapidísimo, en silencio. Llevan bolsas al hombro."],
                 ["ancla", "Ancla. Son los mensajeros del invierno. Cruzan del Prado al Fondo en una hora. Llevan cartas, por una moneda. La gente se escribe más que nunca."],
                 [null, "Uno de los chicos frena delante de ti. Tiene una carta en la mano, sellada con cera blanca y una seta dibujada. «Es para la Casa del Hielo. Me pagaron el doble para que no la vea nadie. Usted no es nadie, ¿no?»."]],
           opts: [{ t: "«¿Quién la mandó?»", go: "quien", once: true },
                  { t: "«Llévala. Que llegue.»", go: "llevar" },
                  { t: "Abrir la carta", go: "abrir" },
                  { t: "«Dásela a la guardia del Fondo.»", go: "guardia" }] },
      quien: { say: [[null, "El chico se encoge de hombros."],
                     [null, "«Un muchacho flaco que se reía mucho, pero esta vez no se reía. En la puerta de los invernaderos. Me dio una seta seca de propina»."]], back: "a" },
      llevar: { say: [[null, "El chico sale patinando hacia el Fondo. Lo ves achicarse en la noche blanca hasta que es un punto."],
                      [null, "Al día siguiente, otro chico de las Mareas te encuentra y te da una carta sellada con cera azul. Adentro hay una sola palabra, en letra muy derecha: «Sí»."],
                      ["ancla", "Una palabra. Cruzó el lago dos veces por una palabra. Los mensajes más caros son los cortos."]], end: { xp: 16, flag: "e5_cartaLlevada" } },
      abrir: { say: [[null, "Rompes la cera. La carta dice: «Si no puedo verte, te canto. Esta noche, a la hora de los soñadores, canta la nana desde tu lado. Yo la canto desde el mío. A lo mejor el hielo la lleva»."],
                     [null, "El chico te mira con desprecio. Vuelve a doblar la carta como puede y se va patinando."],
                     ["ancla", "Ahora usted sabe. Y él sabe que usted sabe. En las Mareas, una carta abierta no se perdona. Aunque llegue."]], end: { xp: 10, flag: "e5_cartaAbierta" } },
      guardia: { say: [["ancla", "¿A la guardia? ¿Una carta de amor?"],
                       [null, "El chico te mira, después a Ancla. Le da la carta a un guardia del Fondo que cruza el lago. El guardia la lee ahí mismo, en voz alta, riéndose."],
                       [null, "A la semana, en la sala del Turno, ponen una guardia más. A la hora de los soñadores, nadie canta."]], end: { xp: 8, flag: "e5_cartaGuardia" } },
    } },

    "e5-barca": { kind: "dialogo", need: { era: 5, layer: 3 }, who: { rada: "Doña Rada" }, start: "a", nodes: {
      a: { say: [[null, "Rada te pide que la lleves hasta la barca hundida, la que se ve bajo el hielo cerca de la orilla norte. Camina muy despacio, apoyada en tu brazo y en su bastón."],
                 ["rada", "Rada. Me queda poco, se nota. Quiero leer esa barca antes de irme. Tiene letras en el costado. Las veo desde arriba hace dos inviernos y no las puedo tocar."],
                 ["rada", "Y quiero pedirle algo. Cuando me muera, no me entierre en la orilla. Póngame aquí, en el hielo, al lado de la barca. Las Mareas no tenemos tierra. Que me lleve el agua cuando se derrita."]],
           opts: [{ t: "Romper el hielo para que toque las letras", go: "romper" },
                  { t: "«La enterramos en la orilla, con su gente.»", go: "orilla" },
                  { t: "«Le prometo ponerla aquí, junto a la barca.»", go: "prometer" }] },
      romper: { say: [[null, "Picas el hielo junto a la barca hasta que el agua negra sube. Rada mete las dos manos. Lee con los dedos el costado de madera, letra por letra."],
                      ["rada", "«La primera barca que cruzó el Lago cuando había Lago. Antes del Lago, aquí había un valle. Y en el valle, una Raíz que cantaba sola»."],
                      [null, "Saca las manos azules. Tiembla. Sonríe."],
                      ["rada", "Cantaba sola. Antes de nosotros. Ya está. Lo leí. Ahora me puedo ir cuando quiera."]], end: { xp: 20, hurt: 0.05, flag: "e5_barcaLeida" } },
      orilla: { say: [["rada", "En la orilla. Con mi gente. Bueno. Usted manda en esto, porque usted se queda."],
                      [null, "Se sienta en el hielo, al lado de la barca, y la mira un rato largo sin decir nada."],
                      ["rada", "Por lo menos me va a visitar. Los de la orilla se visitan. Los del agua, no."]], end: { xp: 12, flag: "e5_radaOrilla" } },
      prometer: { say: [["rada", "Gracias. No tenía a quién pedírselo. Mis nietos me iban a enterrar con flores de papel."],
                        [null, "Rada se queda sentada al lado de la barca hasta que oscurece. Le cuenta a la barca cosas de las Mareas, en voz baja."],
                        [null, "Un mes después, Rada muere dormida. La pones en el hielo, envuelta en una vela de barca, junto a la barca hundida. Las Mareas ponen banderas de trapo alrededor."],
                        [null, "Cuando el hielo se derrita, el agua se la va a llevar. Mientras tanto, la gente que cruza el lago la saluda al pasar."]], end: { xp: 18, flag: "e5_radaHielo" } },
    } },

    "e5-crujido": { kind: "encuentro", need: { era: 5, layer: 3 }, who: { rompiente: "Rompiente, voz de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "De noche, el Lago cruje. Un ruido largo, grave, que viaja de orilla a orilla como un trueno abajo. La fila que cruza se para en seco."],
                 ["rompiente", "Rompiente. Lo hace desde hace un mes. Cada noche más fuerte. Los viejos dicen que el Lago respira. Que algo abajo respira y el hielo no lo deja."],
                 [null, "En el camino de banderas se abrió una raya negra, fina, de punta a punta. Del otro lado esperan cien personas con trineos."]],
           opts: [{ t: "«¿Desde cuándo cruje así?»", go: "cuando", once: true },
                  { t: "«Desde que cortaron el hielo de raíz en el Fondo.»", go: "cortado", cNeed: "m5_cortarHielo" },
                  { t: "Cerrar el camino hasta que se sepa", go: "cerrar" },
                  { t: "Abrir otro camino por el borde", go: "borde" },
                  { t: "«Crucen de a uno, despacio, sin parar.»", go: "cruzar" }] },
      cuando: { say: [["rompiente", "Desde la primera luna llena del invierno. Cruje más cuando hay luna. Los peces se van lejos del centro."],
                      ["rompiente", "Rada decía que el Lago tapó un valle donde la Raíz cantaba. Si la Raíz respira abajo, el hielo es una mano en la boca."]], back: "a" },
      cortado: { say: [["rompiente", "Sí. Desde que cortaron esa pared azul. Los del Fondo dicen que es casualidad. Las Mareas no creemos en casualidades de agua."],
                       ["rompiente", "El frío que se soltó en el Fondo sube por algún lado. Por aquí sube."]], back: "a" },
      cerrar: { say: [[null, "Pones una soga atravesada en las dos puntas del camino. La fila de los dos lados protesta. Algunos lloran: llevan días caminando."],
                      [null, "Al tercer día, la raya negra se abre del todo. El hielo se parte en dos con un estruendo. Donde estaba el camino, hay agua negra."],
                      ["rompiente", "Si cruzaban, se hundían cien. Ahora dan la vuelta, medio día más. Nadie le va a agradecer, Cuidador. Nadie agradece lo que no pasó."]], end: { xp: 18, flag: "e5_caminoCerrado" } },
      borde: { say: [[null, "Con Rompiente y diez de las Mareas, trazan un camino nuevo por el borde norte, tanteando el hielo con bastones. Ponen banderas nuevas."],
                     [null, "Es más largo. Pero no cruje. La fila se cambia al camino nuevo, rezongando."],
                     ["rompiente", "Más largo y más seguro. Como todo lo que sirve en invierno. El camino viejo lo dejamos con las banderas, por si alguien quiere ver dónde se rompe."]], end: { xp: 16, flag: "e5_caminoBorde" } },
      cruzar: { say: [[null, "La fila cruza de a uno, sin pararse, mirando para adelante. El hielo cruje debajo de cada paso. Nadie habla."],
                      [null, "Pasan noventa y ocho. El noventa y nueve, un viejo con un trineo cargado, pisa la raya negra. El hielo cede. Lo sacan del agua con sogas, entero, temblando."],
                      ["rompiente", "Noventa y nueve. Casi cien. El viejo perdió el trineo y todo lo que traía para cambiar en el Fondo. Ahora va a la fila sin nada. Pero va."]], end: { xp: 12, flag: "e5_cruceArriesgado" } },
    } },
  });

  /* ---------- Cuevas del Eco: los turnos de sueño, los ecos, las paredes y el túnel bajo la Tumba ---------- */
  add("caves", {
    "e5-turnos": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { pizca: "Pizca, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "En las galerías tibias de las Cuevas, la gente duerme por turnos: cuando suena un golpe de pico en la pared, los que duermen se levantan y los que esperan se acuestan en el mismo lugar, todavía tibio."],
                 [null, "En una galería hay gritos. Un hombre grande no se quiere levantar. Dice que pagó dos turnos. La mujer que espera tiene un bebé en brazos."],
                 ["pizca", "Pizca otra vez. Pagó uno. Lo sé porque yo cobro. Si no se levanta, el turno se rompe en toda la galería. Y si se rompe, nadie sabe cuándo le toca."]],
           opts: [{ t: "«¿Qué pasa si se rompe el turno?»", go: "rompe", once: true },
                  { t: "Sacarlo de la galería", go: "sacar" },
                  { t: "Darle tu lugar del próximo turno", go: "lugar" },
                  { t: "«Que la mujer con el bebé duerma con él, juntos.»", go: "compartir" }] },
      rompe: { say: [["pizca", "Pelea. La última vez que se rompió, hubo cuchillos. Un chico de la Hondura terminó con un corte en la cara. Desde entonces el pico manda."],
                     ["pizca", "En la Hondura siempre fue así: el que manda es el ruido de la pared, no la persona. Así nadie le guarda rencor a nadie."]], back: "a" },
      sacar: { say: [[null, "Lo agarras del brazo con dos picadores de la Hondura. Se resiste, grita, tira una patada. Al final sale a la galería fría, maldiciendo."],
                     [null, "La mujer se acuesta en el lugar tibio con el bebé. Se duerme antes de cerrar los ojos del todo."],
                     ["pizca", "El turno sigue. Ese hombre va a volver mañana con amigos. Ya veremos. Hoy, el pico manda."]], end: { xp: 12, flag: "e5_turnoSacado" } },
      lugar: { say: [[null, "Le dices al hombre que puede quedarse, y que el próximo turno es tuyo pero se lo das a la mujer. El hombre se queda callado, confundido."],
                     [null, "Esa noche no duermes. Caminas por las galerías frías hasta que suena el pico. El hombre, al levantarse, le deja a la mujer su manta."],
                     ["pizca", "Usted pagó con sueño. Él pagó con una manta. Nadie pagó con monedas. En la Hondura no sé cómo anotar eso."]], end: { xp: 16, hurt: 0.05, flag: "e5_turnoCedido" } },
      compartir: { say: [["pizca", "¿Juntos? ¿Un desconocido y una mujer con un bebé?"],
                         [null, "El hombre la mira. La mujer lo mira. Él se corre contra la pared, dejando lugar. Ella se acuesta del otro lado, con el bebé en el medio."],
                         [null, "A la mañana, el bebé duerme abrazado a la barba del hombre. Él no se movió en toda la noche, para no despertarlo."],
                         ["pizca", "Dos en un turno. Si lo hace toda la galería, entra el doble de gente. Va a ser incómodo. Va a ser tibio."]], end: { xp: 18, flag: "e5_turnoDoble" } },
    } },

    "e5-cinabrio": { kind: "dialogo", need: { era: 5, layer: 1 }, who: { cinabrio: "Cinabrio, picador" }, start: "a", nodes: {
      a: { say: [[null, "En el fondo de una galería caliente, un picador joven con la espalda llena de cicatrices finas golpea la roca. El calor sale de la pared como de un horno."],
                 ["cinabrio", "Cinabrio. Nieto de Galena, la Primera Picadora. Cuanto más hondo cavamos, más calor sale. Si bajamos diez galerías más, entra todo el Claro en las Cuevas."],
                 ["cinabrio", "Pero la pared de abajo es otra. Es de la que golpea de vuelta. Mi abuela lo sabía."]],
           opts: [{ t: "«Galena hacía votar a toda la Hondura antes de abrir un túnel.»", go: "galA", cNeed: "end_galena_A" },
                  { t: "«Galena selló todo lo que encontró.»", go: "galB", cNeed: "end_galena_B" },
                  { t: "«Galena golpeaba dos veces antes de cada turno.»", go: "galC", cNeed: "end_galena_C" },
                  { t: "«Caven más hondo.»", go: "cavar" },
                  { t: "«Paren aquí.»", go: "parar" },
                  { t: "«Que vote toda la Hondura.»", go: "votar" }] },
      galA: { say: [["cinabrio", "Sí. Y leía una pared en voz alta cada noche. La última que leyó decía: «Abajo no está vacío»."],
                    ["cinabrio", "Desde que se murió, nadie lee. Votamos, pero sin leer. Es votar a ciegas."]], back: "a" },
      galB: { say: [["cinabrio", "Todo. Los túneles calientes, las cámaras, las paredes con letras. Nosotros no sabemos qué hay detrás."],
                    ["cinabrio", "Ahora hace frío y queremos abrir lo que ella cerró. Si estuviera viva, me pegaría con el pico. Con el mango, por lo menos."]], back: "a" },
      galC: { say: [["cinabrio", "Dos veces. Y a veces le contestaban. Yo golpeo dos veces también, por costumbre."],
                    [null, "Golpea dos veces la pared. Esperan. Desde muy adentro, débil, llega un golpe. Uno solo."],
                    ["cinabrio", "Antes eran dos. Ahora contesta uno. Como si estuviera cansado."]], back: "a" },
      cavar: { say: [[null, "Cavas con Cinabrio y veinte picadores. Abren tres galerías nuevas en una semana. El calor sube. Entran cien familias más a las Cuevas."],
                     [null, "En la tercera galería, la pared golpea de vuelta. Fuerte. Una vez, y después muchas, como un corazón asustado. Los picadores salen corriendo."],
                     ["cinabrio", "Ya está. Cien familias tibias. Y algo allá abajo que se asustó. Mi abuela decía que no hay calor que no le cueste a alguien. Ahora sé a quién."]], end: { xp: 16, flag: "m5_cuevasHondas" } },
      parar: { say: [["cinabrio", "Parar. Con la fila de afuera. Bueno."],
                     [null, "Deja el pico apoyado contra la pared caliente. Pone la mano en la roca, como quien toca el lomo de un animal."],
                     ["cinabrio", "Que duerma lo que haya abajo. Arriba nos apretamos más. La Hondura sabe apretarse. Siempre supo."]], end: { xp: 12, flag: "e5_cuevasParadas" } },
      votar: { say: [[null, "Cinabrio llama a la Hondura entera a la galería grande. Se cuentan las manos a la luz de las lámparas."],
                     [null, "Gana cavar dos galerías más, no diez. Y que alguien lea las paredes antes de cada golpe."],
                     ["cinabrio", "Dos. Leyendo. Como mi abuela, a medias. La Hondura nunca hace nada entero. Por eso sigue viva."]], end: { xp: 18, flag: "e5_cuevasVoto" } },
    } },

    "e5-ecos": { kind: "encuentro", need: { era: 5, layer: 1 }, who: { mica: "Mica, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "En una galería sin turnos, una niña de la Hondura está sentada con la oreja pegada a la pared. Mueve los labios, repitiendo algo."],
                 ["mica", "Shh. Soy Mica. Escuche. Es mi mamá. Se murió en la fila del Fondo en otoño. Pero la pared la repite. Lo que dijo aquí, antes de irse."],
                 [null, "Pones la oreja en la roca. Desde muy lejos, como debajo del agua, una voz de mujer dice: «Te dejo la lámpara. Vuelvo en una semana. Come despacio»."]],
           opts: [{ t: "«¿Cuánto dura el eco?»", go: "dura", once: true },
                  { t: "Quedarte con ella escuchando", go: "quedarse" },
                  { t: "«Ven, Mica. Vamos a donde hay gente.»", go: "llevar" },
                  { t: "Decirle algo a la pared, para ella", go: "decir" }] },
      dura: { say: [["mica", "No sé. Cada día se oye más bajito. Los viejos dicen que la pared se olvida, como todos."],
                    ["mica", "Por eso vengo todos los días. Para oírla antes de que se olvide del todo. Después la voy a repetir yo."]], back: "a" },
      quedarse: { say: [[null, "Te sientas con Mica en el suelo frío de la galería. Escuchan la misma frase, una y otra vez, cada vez más baja."],
                        [null, "Al final del día, Mica la repite en voz alta, exacta, con la misma voz. La pared se queda callada, como si escuchara."],
                        ["mica", "Ahora la tengo yo. Si la pared se olvida, no importa. Yo me acuerdo."]], end: { xp: 16, flag: "e5_ecoMica" } },
      llevar: { say: [["mica", "¿A donde hay gente? Pero aquí está mi mamá."],
                      [null, "La convences de a poco. La llevas a la galería grande, donde Pizca reparte sopa. Mica come despacio, como le dijeron."],
                      [null, "Al día siguiente, la encuentras otra vez con la oreja en la pared. Pero ahora vino con otra niña, que también escucha."]], end: { xp: 12, flag: "e5_micaGente" } },
      decir: { say: [[null, "Pones la boca cerca de la roca y dices, despacio: «Mica come despacio. Mica tiene la lámpara. Mica está bien»."],
                     [null, "La pared lo repite, bajito, mezclado con la voz de la madre. Las dos voces juntas."],
                     ["mica", "Ahora la pared le contesta. Para cuando alguien venga a escuchar. Gracias."]], end: { xp: 18, flag: "e5_ecoRespuesta" } },
    } },

    "e5-lamparas": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { mica: "Mica, de la Hondura", pizca: "Pizca, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "En la galería grande, Mica tiene un puesto con lámparas de aceite hechas con cáscaras de seta. Las vende por un pedazo de pan. Hay cola."],
                 ["mica", "Mica. ¿Se acuerda? Hago lámparas con lo que tira la Seta. La gente se pierde en las galerías de noche, y con lámpara no se pierde."],
                 ["pizca", "Pizca. La Hondura dice que el que vende en las Cuevas paga. Ella no paga. Si no paga ella, los demás tampoco van a pagar."]],
           opts: [{ t: "«¿Cuánto tendría que pagar?»", go: "cuanto", once: true },
                  { t: "«Mica no paga. Es una niña.»", go: "nena" },
                  { t: "«Que pague con lámparas para las galerías.»", go: "lamparas" },
                  { t: "«La regla es la regla.»", go: "regla" }] },
      cuanto: { say: [["pizca", "Una lámpara de cada cinco. Para las galerías comunes. Es lo que pagan los que venden sopa."],
                      ["mica", "Una de cada cinco. Y con las otras cuatro como yo. ¿Y si como menos?"]], back: "a" },
      nena: { say: [["pizca", "Una niña que vende. En la Hondura, a los diez años, se empuja baldes. Yo empujaba baldes."],
                    [null, "Mira a Mica. Se mira las rodillas vendadas."],
                    ["pizca", "Bueno. No paga. Hasta que cumpla los doce. Lo anoto, para que nadie diga que fue favor."]], end: { xp: 14, flag: "e5_micaLibre" } },
      lamparas: { say: [[null, "Mica hace una lámpara de cada cinco para las galerías comunes. Pizca las cuelga en los cruces, donde la gente se pierde."],
                        [null, "A la semana, las Cuevas tienen luz en todos los cruces. Nadie se pierde de noche. Los turnos se cambian más rápido."],
                        ["pizca", "Pagó con luz. La Hondura nunca cobró en luz. Me gusta. Lo voy a proponer para todos."]], end: { xp: 18, flag: "e5_lucesCruces" } },
      regla: { say: [["pizca", "La regla. Sí."],
                     [null, "Mica le da a Pizca la mitad de las lámparas del día. Pizca las vende en otra galería, más caras."],
                     [null, "Esa noche, Mica come la mitad de lo que comía. Al otro día no pone el puesto. Pone la oreja en la pared."]], end: { xp: 8, flag: "e5_micaPaga" } },
    } },

    "e5-pared": { kind: "dialogo", need: { era: 5, layer: 2 }, who: { pared: "La pared" }, start: "a", nodes: {
      a: { say: [[null, "En lo más hondo de las Cuevas, donde no llega el turno ni la luz, hay una pared lisa que habla cuando alguien le apoya la frente. Siempre habló. Este invierno, dice cosas nuevas."],
                 ["pared", "Frío. Frío arriba. Abajo, quieto. Quieto mucho. Antes cantaban dos. Ahora canta nadie."],
                 ["pared", "Dos de hielo y seta, juntos. Luz nació. Después raya, cuchillo. Ya no. ¿Por qué ya no?"]],
           opts: [{ t: "«¿Quién rayó la estatua?»", go: "quien", once: true },
                  { t: "«¿Qué pasa si vuelven a cantar dos?»", go: "cantar" },
                  { t: "«¿Qué pasa si se sella otra herida?»", go: "sellar" },
                  { t: "Apoyar la frente y no decir nada", go: "callar" }] },
      quien: { say: [["pared", "Uno con miedo. Vio la luz. Luz recordaba. Recordaba el pacto. Recordaba distinto a él."],
                     ["pared", "Él quería un solo recuerdo. Rayó. Una luz, un recuerdo. Más fácil. Más frío."]], back: "a" },
      cantar: { say: [["pared", "Otra luz. Otro recuerdo. Dos luces, dos recuerdos. No iguales."],
                      ["pared", "Pelea. Pero calor. Pelea es calor. Quieto es frío."]], back: "a" },
      sellar: { say: [["pared", "Tapa. Quieto. Más quieto. Tumba sobre herida. Herida no cierra. Herida espera."],
                      ["pared", "Ya hay una tumba. Tumba vieja. Rey de mentira. Tumba nueva, rey nuevo. Siempre rey nuevo."]], back: "a" },
      callar: { say: [[null, "Apoyas la frente en la piedra fría y no dices nada. La pared tampoco dice nada, durante mucho rato."],
                      [null, "Después, muy bajito, en vez de palabras, la pared tararea algo. Son las primeras notas de la nana. Solo las primeras. Después se calla, como si no se acordara del resto."],
                      [null, "Tu criatura apoya la cabeza en la pared al lado tuyo y tararea la nota que sigue."]], end: { xp: 18, heal: 0.1, flag: "e5_paredTararea" } },
    } },

    "e5-cuarenta": { kind: "encuentro", need: { era: 5, layer: 2 }, who: { cinabrio: "Cinabrio, picador" }, start: "a", nodes: {
      a: { say: [[null, "En la cámara de los cuarenta trabajadores de piedra, las figuras grises están sentadas en fila, como las dejaron hace cincuenta años. Entre ellas duermen familias. Usan las rodillas de piedra de almohada."],
                 ["cinabrio", "Cinabrio. Es la cámara más tibia de todas. Nadie sabe por qué. Mire esto."],
                 [null, "Te lleva hasta una de las figuras. Tiene la mano abierta, palma arriba. Al tocarla, la piedra está tibia. Late, muy despacio, como la punta de la raíz en la Tumba."]],
           opts: [{ t: "«¿Están vivos?»", go: "vivos", once: true },
                  { t: "Tapiar la cámara", go: "tapiar" },
                  { t: "Dejar que las familias sigan durmiendo ahí", go: "dormir" },
                  { t: "Avisarle a Chispa en el Cráter", go: "chispa" }] },
      vivos: { say: [["cinabrio", "No sé. No respiran. No se mueven. Pero las manos están tibias, todas. Y cuando duerme alguien al lado, se ponen más tibias."],
                     ["cinabrio", "Los viejos dicen que el metal de raíz no los mató: los guardó. Que son de la Raíz ahora. Que la Raíz se calienta a través de ellos."]], back: "a" },
      tapiar: { say: [[null, "Con Cinabrio y los picadores, levantan una pared de piedra suelta en la entrada. Las familias protestan: era la cámara más tibia."],
                      [null, "Antes de poner la última piedra, Cinabrio se queda mirando las cuarenta figuras."],
                      ["cinabrio", "Que descansen. Si están vivos, que descansen de nosotros. Si no, también."]], end: { xp: 12, flag: "e5_cuarentaTapiada" } },
      dormir: { say: [[null, "Las familias siguen durmiendo entre las figuras. Cada noche, las manos de piedra se ponen un poco más tibias."],
                      [null, "Un chico duerme con la mano metida en la palma de piedra de una figura. A la mañana, tiene la punta de los dedos gris. No le duele. Dice que soñó con alguien que le contaba cómo era la primera forja."],
                      ["cinabrio", "Se cuentan cosas. Los de piedra y los vivos. No sé si eso es bueno. Es tibio."]], end: { xp: 14, flag: "m5_cuarentaTibia" } },
      chispa: { say: [[null, "Chispa llega a las Cuevas con Rescoldo, apoyada en el bastón, dos días después. Entra en la cámara y se para delante de las cuarenta figuras."],
                      [null, "Las nombra una por una, de memoria, con los nombres del molde. Cuarenta. Cuando dice el último, una de las manos de piedra se cierra, despacio, un poco."],
                      [null, "Chispa no llora. Se sienta en el suelo y se queda un rato. Rescoldo se mira las uñas y no dice nada."]], end: { xp: 18, flag: "e5_cuarentaNombrada" } },
    } },

    "e5-precio": { kind: "dialogo", need: { era: 5, layer: 3 }, who: { pizca: "Pizca, de la Hondura", cinabrio: "Cinabrio, picador" }, start: "a", nodes: {
      a: { say: [[null, "En la galería grande, la Hondura está reunida. Los picadores viejos quieren subir la entrada a tres monedas. Pizca está de pie, con la caja de las monedas en los brazos."],
                 ["pizca", "Tres monedas. Dicen que la Hondura merece cobrar lo que vale el calor. Que por fin abajo vale algo. Yo lo dije también, al principio."],
                 ["cinabrio", "Y yo digo que la gente de afuera ya no tiene monedas. Si cobramos tres, entran los Albor y la Corte. Nadie más."]],
           opts: [{ t: "«¿Qué quiere usted, Pizca?»", go: "pizca", once: true },
                  { t: "«Una moneda, como siempre.»", go: "una" },
                  { t: "«Tres a los que tienen. Gratis a los que no.»", go: "escala" },
                  { t: "«Que la entrada se pague con trabajo, no con monedas.»", go: "trabajo" }] },
      pizca: { say: [[null, "Pizca mira la caja. La abre. Adentro hay monedas, una tiza, un casco chico de niña, abollado."],
                     ["pizca", "Quiero que la Hondura no tenga que empujar baldes nunca más. Y quiero que nadie se congele afuera de mi portón. No puedo querer las dos cosas con una sola caja."]], back: "a" },
      una: { say: [["pizca", "Una. Como siempre. Bueno."],
                   [null, "Los picadores viejos rezongan. Uno escupe en el suelo. Pero votan con Pizca, porque es Pizca."],
                   ["pizca", "La Hondura sigue cobrando poco. Seguimos siendo los que dan. Mi abuela diría que no aprendimos nada. Yo digo que aprendimos lo que queríamos."]], end: { xp: 14, flag: "e5_precioUna" } },
      escala: { say: [[null, "Se arma una tabla en la pared de la galería, con tiza: quién paga tres, quién paga una, quién no paga. Pizca la escribe con su letra."],
                      [null, "Los Albor y la Corte pagan tres. Las Mareas y el Prado, nada. Hay peleas en la puerta: todos dicen que no tienen."],
                      ["cinabrio", "Ahora la Hondura decide quién es pobre. Es mucho poder para un pueblo que siempre empujó baldes. Ojalá lo usemos mejor que los otros."]], end: { xp: 18, flag: "m5_honduraTabla" } },
      trabajo: { say: [["cinabrio", "¿Trabajo? ¿Que los de afuera caven?"],
                       ["pizca", "Que caven, que carguen, que barran, que cocinen. Lo que sepan. La Hondura siempre pagó con trabajo. Que ahora cobre igual."],
                       [null, "Lo hacen. Las galerías se limpian, se agrandan, se ordenan. Gente del Prado aprende a picar. Gente de la Corte aprende a cargar."],
                       ["pizca", "Cansados, todos. Tibios, todos. Es lo más parecido a justo que vi en mi vida. No es mucho."]], end: { xp: 20, flag: "e5_precioTrabajo" } },
    } },

    "e5-debajo": { kind: "encuentro", need: { era: 5, layer: 3 }, who: { cinabrio: "Cinabrio, picador" }, start: "a", nodes: {
      a: { say: [[null, "Cinabrio te lleva por una galería nueva, estrecha, que baja y baja. Al final hay un hueco en el techo. Por el hueco se ve, desde abajo, una losa de piedra tallada."],
                 ["cinabrio", "Cinabrio. Estamos debajo de la Tumba Helada. Abrimos sin querer, cavando para el calor. Esa losa es el piso de la Tumba. Y mire lo que pasa por al lado."],
                 [null, "Al lado de la losa, la punta de una raíz gris, enorme, atraviesa la roca hacia abajo. Late. Del lado de la galería está tibia. Del lado de la Tumba, cubierta de escarcha."]],
           opts: [{ t: "«¿Quién más sabe de este túnel?»", go: "quien", once: true },
                  { t: "Contárselo a Cellisca", go: "cellisca" },
                  { t: "Contárselo a Desvelo", go: "desvelo" },
                  { t: "Tapar el túnel", go: "tapar" },
                  { t: "Abrirlo a todo el que quiera ver", go: "abrir" }] },
      quien: { say: [["cinabrio", "Los tres picadores que estaban conmigo. Y usted. Y Pizca, que todo lo sabe."],
                     ["cinabrio", "Si se sabe arriba, unos van a querer entrar a la Tumba por aquí. Otros van a querer cerrar las Cuevas para siempre. La Hondura no quiere ni una cosa ni la otra."]], back: "a" },
      cellisca: { say: [[null, "Cellisca baja a las Cuevas de noche, sola, sin corona, con una capa de lana común. Mira la raíz desde abajo mucho rato."],
                        [null, "«Un camino a la Tumba que no pasa por la puerta. Si alguien lo usa, la Tumba ya no es secreta. Hay que sellarlo. Y la Hondura va a recibir dos sacos por semana por callarse»."],
                        [null, "Cinabrio acepta los sacos. No te mira cuando los carga."]], end: { xp: 12, coins: 10, flag: "e5_tunelCellisca" } },
      desvelo: { say: [[null, "Desvelo baja con una lámpara. Cuando ve la raíz, se arrodilla. No reza: toca la parte tibia con las dos manos."],
                       [null, "«Del lado del Rey, frío. De este lado, calor. Está vivo, Cuidador. Abajo está vivo y arriba lo tapamos. Lo voy a decir. Mañana. Esta vez sí»."],
                       [null, "Al día siguiente, Desvelo habla frente a la Tumba. No dice «el Rey». Dice «la Raíz». La gente lo escucha con la misma cara de siempre. Pero lo escucha."]], end: { xp: 18, flag: "e5_desveloRaiz" } },
      tapar: { say: [[null, "Tapan el túnel con piedras y tierra, de abajo para arriba. La raíz queda del otro lado, sola."],
                     ["cinabrio", "Ya está. Como si no lo hubiéramos encontrado. Mi abuela hubiera hecho esto. Mi abuela se equivocaba en esto."],
                     [null, "Esa noche, en la galería de al lado, la pared golpea dos veces. Nadie contesta."]], end: { xp: 10, flag: "e5_tunelTapado" } },
      abrir: { say: [[null, "Cinabrio pone lámparas por todo el túnel. Corre la voz: el que quiera ver la raíz, que baje. Bajan cientos, de todos los pueblos."],
                     [null, "La gente toca la parte tibia. Algunos lloran. Algunos se ríen nerviosos. Una vieja del Prado dice que es como tocar la panza de una vaca preñada."],
                     ["cinabrio", "Ahora todos saben que está viva. Lo que hagan con eso, ya no es cosa de la Hondura. Es de todos. Que pese en todos."]], end: { xp: 20, flag: "m5_tunelTumba" } },
    } },
  });

})(window.EVEVENTS);
